var e=JSON.parse(`[{"version":"0.1.1105","items":["ドリンクを飲んだときの音を、設定の「ゲーム・演出の音」で「本物っぽい音」と、飲んだ人の声の高さで鳴る「ピコピコ声」から選べるようにしました（最初は今までどおり本物っぽい音）"]},{"version":"0.1.1104","items":["スマホ版でも、設定の「ヘルプ・フィードバック」›「新機能・更新履歴」から、バージョンごと・新しい順に更新履歴を読めるようにしました（アップデートの後には一度だけ小さなお知らせが出て、まだ読んでいないあいだは設定の歯車に小さな点が付きます。検索と「スマホ版のこと」だけの表示もできます）。"]},{"version":"0.1.1103","items":["ドリンクコーナーで名前を日本語 IME で入力したとき、確定すると打った文字が消えて元の名前に戻ってしまう不具合を直しました（16 文字を超えたら欄の下にお知らせが出ます）。"]},{"version":"0.1.1102","items":["アバターを読み込むときに、アバターのファイルをメモリの中でまるごと写していた無駄をなくし、読み込み中のメモリの使い方を少し減らしました。"]},{"version":"0.1.1101","items":["スマホ版でも、通話から反射神経バトルの申し込みを受けたり、自分から申し込んだりして遊べるようにしました（デスクトップ版の誘う系ゲームで、スマホ版にまだなかったのはこれだけでした）。","スマホ版の通話から、じゃんけん・サイコロ勝負・チンチロ勝負・決闘に相手を選んで誘えるようにしました（これまでは誘われる側だけでした）。"]},{"version":"0.1.1100","items":["スマホ版でも、通話からタイピングダンジョンの募集に参加したり、自分で募集したりして遊べるようにしました（ローマ字でも、かなのフリック入力でも打てます）。"]},{"version":"0.1.1099","items":["スマホ版でも、通話中にババ抜き・カラーカードの募集に参加したり、自分から募集したりして遊べるようにしました。","スマホ版でも、通話中にボスレイドの募集に参加したり、自分から募集したりできるようにしました。"]},{"version":"0.1.1098","items":["自分が送った画像や動画が、アプリを閉じるまでメモリに残り続けていたのを直しました。あわせて、起動のどこに時間がかかっているかを測れるようにしました（起動を速くする手を決めるための下ごしらえです）。","不具合の報告に添えられるログに、アプリの起動のどこまでに何ミリ秒かかったかが残るようにしました（起動の速さを直すための下ごしらえで、動きは変わりません）。"]},{"version":"0.1.1097","items":["通話の部屋で画像や動画を送ったあと、そのファイルがアプリを閉じるまでメモリに残り続けていたのを直しました（フキダシが消えたら手放します）。"]},{"version":"0.1.1096","items":["スマホ版のホームで、サーバーの一覧を画面の左端からだけでなく、画面のどこから右へなぞっても出せるようにしました（縦のスクロールや長押し・入力欄とはぶつからないようにしています）。"]},{"version":"0.1.1095","items":["アプリ版のメモリを減らす手を洗い出し、まず安全で効果の大きいもの（使っていない文字起こしの仕組みを手放す・最小化中のウィンドウのメモリを控えめにする）を入れました。"]},{"version":"0.1.1094","items":["ホーム・DM・画面共有のビューアのウィンドウを最小化している間、そのウィンドウが使うメモリを控えめにするようにしました（戻すと元どおり）。"]},{"version":"0.1.1093","items":["文字起こしに Whisper を使っているとき、マイクを切って 5 分たったら、文字起こしのモデルを手放してメモリを空けるようにしました（マイクを入れ直すと読み込み直します）。"]},{"version":"0.1.1092","items":["スマホ版のホームで、サーバーの一覧をアイコンと名前で並べ、サーバーを押すとその画面が全体に大きく出るようにしました。画面の左端から右へなぞると下から一覧が現れ、右に残った画面を押すか左へなぞると元の画面に戻ります（左上の ‹ でも一覧を出せます）。"]},{"version":"0.1.1091","items":["iPhone のホーム画面アプリで画面の下に帯が残るときの直し方（ホーム画面のアプリを削除し、Safari から「ホーム画面に追加」し直す）を、よくある質問に追加し、当てはまる iPhone では一度だけお知らせするようにしました。"]},{"version":"0.1.1090","items":["iPhone のホーム画面から開いたとき、画面のいちばん上（時計の所）の色を、写真や画面共有を見ているときは黒、ログイン画面では背景の色に合わせ、帯だけ浮いて見えないようにしました。"]},{"version":"0.1.1089","items":["スマホ版で、入力中に入力欄の外（メッセージ一覧や余白など）をタップするとキーボードが閉じるようにしました（書きかけの文字は残り、送信ボタンでは閉じません）。"]},{"version":"0.1.1088","items":["iPhone のホーム画面から開いたとき、アプリをステータスバー（時計の所）の下から表示するようにし、新しい iOS で画面の一番下にできていた空いた帯をなくせるようにしました。"]},{"version":"0.1.1087","items":["スマホ版で、通話の画面や画面共有が出ているときに電話の「戻る」（iPhone の左端スワイプ・Android の戻る）をすると、下のチャットが閉じてしまっていたのを直し、通話の画面・画面共有から先に戻るようにしました。"]},{"version":"0.1.1086","items":["フィードバック・不具合の報告を、設定の中ではなく独立した窓で開くようにしました（設定を閉じても書き続けられ、ほかの画面と並べて書けます。設定の一覧・F9・ドックのボタンから開けます）。"]},{"version":"0.1.1085","items":["ワワワードで正解すると、同じ部屋のみんなの画面でその人の頭の上に「🎉 ワワワード正解！ n/6」と紙吹雪が出て、控えめなお祝いの音が 1 回鳴るようにしました（答えの単語や盤面は出ません）。"]},{"version":"0.1.1084","items":["自動化のやることに「鉱石を売る」「魚を売る」を追加し、鉱石だけ・魚だけを売れるようにしました（これまでの「鉱石・魚を売る」もそのまま使えます）。"]},{"version":"0.1.1083","items":["スマホ版で、設定などの下から出る画面が、キーボードが出ているときや画面の低い iPhone でも上が切れないようにし、幅の狭いスマホでは左のサーバーの列とサーバーのチャットの上の帯を詰めて、名前が見やすくなるようにしました。"]},{"version":"0.1.1082","items":["スマホ版のログイン画面から、ユーザー名でアカウントを作れるようにしました。iPhone の Safari で開いたときは、先に「ホーム画面に追加」のやり方をご案内します。"]},{"version":"0.1.1081","items":["iPhone のホーム画面から開いたスマホ版で、画面の下に何も描かれない帯が残ることがあったのを、画面の下端まで使えるように直しました。"]},{"version":"0.1.1080","items":["スマホ版で新しくアカウントを作った人に、実際の画面を指しながら進む短い「使い方の案内」（いつでもスキップでき、設定の「使い方の案内を見る」から見返せます）と、ホームの上の「はじめにやること」（サーバーに入る・フレンドを追加・アイコン・通知）を出すようにしました。"]},{"version":"0.1.1079","items":["スマホ版で、通話しながら DM を開いても見出しの下に「◯◯で通話中」とマイクのボタンが出て、押すと通話の画面に移れる（‹ で DM に戻る）ようにし、通話の画面・画面共有の戻るを DM と同じ左上の ‹ にそろえました。"]},{"version":"0.1.1078","items":["スマホ版で、電話の「戻る」（Android の戻る・iPhone の左端スワイプ）が、シートやゲームの画面が出ているときはそれを先に閉じるようにし、通知から開いた DM でも戻ると開く前の画面に戻れるようにしました。"]},{"version":"0.1.1077","items":["スマホ版（新しい iOS のホーム画面）で文字を打っている間、下の自分の帯が隠れて入力の場所が広くなるようにし、不具合の報告に画面の大きさのくわしい情報が付くようにしました。"]},{"version":"0.1.1076","items":["スマホ版で、サーバー列の選んでいるホーム／サーバーをもう一度押すと、一覧のいちばん上（サーバーのチャットならいちばん新しいメッセージ）へ移るようにしました。"]},{"version":"0.1.1075","items":["スマホ版で、チャット・フレンド・メッセージ・メンバー・サーバー列を読み込む間に「まだメッセージはありません」「読み込み中…」などを出さず、本物と同じ形の灰色の仮表示（遅いときだけ）にして表示がずれないようにし、一度開いたチャットは前回の中身をすぐ出すようにしました。"]},{"version":"0.1.1074","items":["スマホ版でも、設定の「アバター」から「フォトブースで撮る」を開いて、自分のアバターを 3・2・1 で撮り、アイコンに使ったり保存したりできるようにしました。"]},{"version":"0.1.1073","items":["スマホ版で通話画面を全画面で出し、左上の←で通話したまま前の画面に戻れるようにしました。通話中は下の自分の帯に「◯◯で通話中」が出て、押すと通話画面に戻れます。"]},{"version":"0.1.1072","items":["スマホ版をホーム画面から開いたとき、いちばん下の空白に見えていた帯を下の帯と同じ色にして画面の下端までつなげ、上の余白も少し詰めました（不具合の報告には画面の大きさが自動で付くようになりました）。"]},{"version":"0.1.1071","items":["スマホ版のアバター設定の説明に「オフのときは声だけで参加し、デスクトップ版の人からは名前の枠で見えます」と書き添えました（以前の通話タブにあった説明です）。"]},{"version":"0.1.1070","items":["スマホ・ブラウザ版で、再読み込みしたり開き直したりしても、前に見ていたホームの一覧（フレンド / メッセージ）・サーバーのチャット・DM に戻り、入力欄の書きかけのメッセージも消えずに残るようにしました（送ると消え、ログアウトすると端末から消えます）。"]},{"version":"0.1.1069","items":["スマホ版の設定画面を、iPhone の「設定」アプリ（Apple の UI ガイドライン）や Android の設定画面（Material Design）の作りに合わせて整理し、項目の種類ごとに見た目と操作をそろえました（ユーザー名・パスワードの変更は行全体を押すと開く形に、オン／オフはすべてスイッチに、説明文は各グループの下に、など）。"]},{"version":"0.1.1068","items":["スマホ版のホームを、アプリ版のホームのように「左のサーバー列（最後の＋で招待コードの入力）＋右の画面（ふだんはフレンド一覧、サーバーを押すとそのサーバー）＋一番下の自分の帯（押すと設定が下からのシートで出る）」の形に作り替えました。"]},{"version":"0.1.1067","items":["遠征隊の「おまかせ」で詰め直したあと、「元に戻す」で直前の詰め方に戻せるようにしました。"]},{"version":"0.1.1066","items":["スマホ版のサーバーのチャットで、右上の電話ボタンをいつも出すようにし、通話に人がいるときもそのボタンから参加できるようにしました。「◯人が通話中」のバーは参加ボタンを外し、誰がいるかの表示だけにしました。"]},{"version":"0.1.1065","items":["スマホ版（ホーム画面のアプリ）をよく開く方でも、アプリを閉じているときの DM の通知が届かなくなることがないようにしました（開いている会話の通知は残さず、同じメッセージの通知は 1 つにまとめます）。"]},{"version":"0.1.1064","items":["スマホ版で、友達リンク・サーバーの招待・チャットの画像を、スマホの共有メニュー（LINE など）からそのまま送れるようにしました（共有メニューがないブラウザでは今までどおりコピーします）。"]},{"version":"0.1.1063","items":["スマホ版（iPhone）で通話中の音を「通話」として扱うようにし、ロック画面やコントロールセンターに「通話中: サーバー名」を出して、そこからマイクのオン／オフ・通話から抜ける操作をできるようにしました（対応している端末のみ）。"]},{"version":"0.1.1062","items":["スマホ版をホーム画面に追加して通知を許可していると、アプリのアイコンに未読の DM・サーバーの数が出るようにしました（閉じているあいだに届いた DM でも数が増えます）。"]},{"version":"0.1.1061","items":["スマホ版のサーバーのチャットで、通話に入るボタンが 2 つ出ていたのを 1 つにまとめました。通話に人がいるときは「◯人が通話中・参加」バーの「参加」だけにして、右上の電話ボタンは隠しています。誰もいないときは右上の電話ボタンから通話を始められ、通話中は右上の（緑の）電話ボタンから通話の画面に戻れます。"]},{"version":"0.1.1060","items":["スマホ版の設定「ほかの人のアバターの動く映像を見る」を、オフ／Wi-Fi のときだけ／いつも の 3 つから選べるようにしました（Wi-Fi かどうかをブラウザが教えてくれない iPhone・iPad では「Wi-Fi のときだけ」は選べず、その理由を表示します）。"]},{"version":"0.1.1059","items":["スマホ版をホーム画面から開いたとき、画面の一番下（チャットの入力欄の下半分、タブ、シートの下端）が切れて見えなくなっていたのを直しました。"]},{"version":"0.1.1058","items":["チュートリアルに「フォトブースでアイコンを作る」を追加しました。光っているボタンを順に押していくと、フォトブースで写真を撮ってアイコンにするまでを実際に操作しながら覚えられます（設定の「全体」・よくある質問・はじめのチュートリアルから受けられ、いつでもやめられます）。"]},{"version":"0.1.1057","items":["スマホ版の設定に「ヘルプ・フィードバック」を置き、不具合の報告や要望をスマホから直接送れるようにしました（版と端末は自動で添えます）。"]},{"version":"0.1.1056","items":["スマホ版の通話で、ほかの人のアバターを押したときのメニュー（なでる・ドリンクなど）の下の方が切れて見えない・選べないのを直しました。項目が多いときはスクロールできます。"]},{"version":"0.1.1055","items":["スマホ版の設定画面で、読み込み中の項目を灰色の仮の形（スケルトン）で表示し、読み込み後に文字が入っても行の高さや位置がずれないようにしました。"]},{"version":"0.1.1054","items":["スマホ版のポップアップの閉じる✖️を右上にそろえ、下へスワイプ・外側をタップしても閉じられるようにしました（画像の拡大・画面共有の✖️も右上に）。"]},{"version":"0.1.1053","items":["スマホ版の設定で、ログアウトをページのいちばん下に移し、横幅いっぱいの押しやすい赤いボタンにしました（押すと確認が出ます）。"]},{"version":"0.1.1052","items":["スマホ版を iPhone のホーム画面から開いたとき、画面の下に余白が空いてしまうのを直し、どの画面も一番下まで表示されるようにしました。"]},{"version":"0.1.1051","items":["スマホ版のサーバー画面からメンバー一覧を開けるようにし、アプリ版と同じく通話中／オンライン／オフラインに分けて、離席中の人には「離席中」と出すようにしました。"]},{"version":"0.1.1050","items":["スマホ版でも通話中にブラックジャックの募集に参加して遊べるようにし、スマホからも募集できるようにしました（コインの賭けもできます）。"]},{"version":"0.1.1049","items":["スマホ版のメッセージタブで、新しいメッセージを書くボタンを右上から右下の押しやすい丸いボタンに変えました。"]},{"version":"0.1.1048","items":["ペットが言える言葉が 3 つ以上になると、ときどき覚えた言葉どうしをつなげた新しい言葉（「おはよう」と「ようこそ」で「おはようこそ」など）をしゃべるようにしました。なかよし度が高いほど、よく・自然につなげます。"]},{"version":"0.1.1047","items":["ペットに好きな言葉で話しかけられるようにしました。何度も話しかけた言葉は、はじめはカタコトで、だんだん全部言えるようになり（なかよし度が高いほど早く覚えます）、ときどき自分から吹き出しで言います。覚えた言葉は「ことば」から一覧で見られ、1 つずつ・ぜんぶ忘れさせることもできます（この PC だけに保存され、ほかの人には見えません）。"]},{"version":"0.1.1046","items":["合成工房のレシピで、回数（×1 / ×10 / 作れるだけ）を選んで、材料が足りる分だけまとめて一度に合成できるようにしました。作った数は「×N ができた！」で表示されます。"]},{"version":"0.1.1045","items":["すすめドリルラッシュの坑道にときどき敵が出るようにしました。通り道の敵はドリルで戦って倒し、コインやときどきアイテムがもらえます。強化に「戦う力」を追加し、上げると速く倒せて、深い所の強い敵も倒せるようになります（倒せない敵はすり抜けて掘り進みます）。"]},{"version":"0.1.1044","items":["フィードバックを送って紙飛行機がポストに入ったあと、小さなふみくまが出てきてポストから手紙を取り出して鞄に入れ、郵便バイクに乗って画面の奥へ小さくなって去るようにしました（ポストの横の狭い範囲だけを使います。「アップデートを郵便屋さんが届けにくる」がオフのときや、演出を控えめにする設定のときは出ません）。"]},{"version":"0.1.1043","items":["おたのしみの「すすめドリル隊」の名前を、画面に出るところすべて「すすめドリルラッシュ」に変えました（今までのセーブはそのまま使えます）。"]},{"version":"0.1.1042","items":["おたのしみの「記録を見る」から、コイン・すすめドリル隊・バックパック遠征隊・釣り・ペット・にぎり屋さん・買ったかざりなどのデータをまとめて書き出し、別の PC で同じアカウントでログインして読み込めるようにしました（別のアカウントのもの・書き換えたもの・途中で切れたものは読み込まず、上書きする前に確認を出します）。"]},{"version":"0.1.1041","items":["すすめドリル隊の進み具合を「書き出す」でコピーし、別の PC で同じアカウントでログインして「読み込む」と引き継げるようにしました（別のアカウントのものや書き換えたものは読み込めず、上書きする前に確認が出ます）。"]},{"version":"0.1.1040","items":["バックパック遠征隊のミシック級に、3×3 の「動く城塞」と、✕ 形でマスが離れた「浮かぶ魔晶」を足して 10 種にしました（格上げ合成で出ます。Anomaly 級には 10 種すべてが要ります。旧 8 種で合成すると新しい 2 種のどちらかが出ます）。"]},{"version":"0.1.1039","items":["バックパック遠征隊に「📖 図鑑」を付けました。全アイテムの形・効果・手に入れ方などを見られ、まだ手に入れていない物は薄く表示されます。"]},{"version":"0.1.1038","items":["スマホ版で、通話に入る前に、各サーバーの通話にいまいる人（アイコン・名前・人数）が、サーバー一覧・通話タブ・サーバーのチャットの上に出るようにしました。"]},{"version":"0.1.1037","items":["スマホ版でも、通話中にサイコロ勝負・チンチロ勝負・決闘に誘われたら、受けてそのまま遊べるようにしました。"]},{"version":"0.1.1036","items":["合成工房のアイテムの絵が古い絵文字のままだったのを直し、バックパック遠征隊と同じドット絵で表示するようにしました。"]},{"version":"0.1.1035","items":["バックパック遠征隊で、ミシック 10 個を自分で選んで格上げ合成できるようにしました（選んだ中に入っていない種類のミシックが出て、全種そろっていると隠しレアリティのアイテムが出ます。自動の合成ではミシックは使いません）。"]},{"version":"0.1.1034","items":["スマホ版でも通話中にパソコン版の人からじゃんけんに誘われると届き、受けて遊べるようにしました（まだ遊べないゲームに誘われたときや募集が出たときは「スマホ版ではまだ遊べません」と表示します）。"]},{"version":"0.1.1033","items":["スマホ版でも通話中にドリンクを贈れる・受け取って飲めるようにし、ドリンクコーナーでドリンクを作れるようにしました（アプリ版との間でも行き来します）。"]},{"version":"0.1.1032","items":["スマホ版の設定「アバター」で「ほかの人のアバターの動く映像を見る」をオンにすると、通話中にデスクトップ版の人のアバターの動く姿がアイコンの代わりに見られるようにしました（最初はオフ。通信量を抑えるため低画質で受け取ります）。"]},{"version":"0.1.1031","items":["スマホ版の通話でも、ほかの人の奥行きが見える（遠い人ほど小さく薄く、奥行き順に並ぶ）ようにし、スライダーで自分の奥行きを変えてアプリ版の人の画面にも反映されるようにしました。"]},{"version":"0.1.1030","items":["ペットが数秒おきに、すがたや性格に合わせていろいろな動き（きょろきょろ・はなうた・ころん・のび・あくび など）をするようになり、ごはん・なでる・あそぶ・おふろ・みまもる・ほめる への反応とセリフも、それぞれ何種類かの中から出るようにしました。"]},{"version":"0.1.1029","items":["遠征中でも、バックパックで装備中のアイテムを合成工房の「メイン」に選んで（クリックでもドラッグ＆ドロップでも）、装備したままその場で強化できるようにしました（サブには今どおり使えません）。"]},{"version":"0.1.1028","items":["バックパック遠征隊のアイテムを合成工房のパネルへドラッグ＆ドロップすると、そのアイテムが「メイン＋サブ」のメインに選ばれるようにしました（同じウィンドウの中なので、そのままドラッグできます。設定は増やしていません）。"]},{"version":"0.1.1027","items":["スマホ版のチャット（サーバー・DM）で、自分の発言（文字・音声の文字起こし）をタップすると「直す」が出て、書き直せるようにしました（長押しでも出ます）。"]},{"version":"0.1.1026","items":["ドリンクを飲むときの音を、可愛い声っぽい「ごくごく」と、飲み終わりの「ぷはー」に変えました。"]},{"version":"0.1.1025","items":["ドリンクコーナーのトッピングを、同じものを 20 段まで重ねられるようにしました（多く重ねても絵が崩れないよう、詰めて高く積みます）。"]},{"version":"0.1.1024","items":["ドリンクコーナーのカップに「マグカップ」「ティーカップ」「ワイングラス」を増やしました。マグカップとティーカップは温かいドリンクらしく湯気が立ち、飲むときや贈るときの絵にも出ます。"]},{"version":"0.1.1023","items":["ドリンクコーナーで作ったドリンクが、アプリの再起動（自動更新を含む）のあとも「ドリンクを贈る」の先頭に残り、続けて贈れるようにしました。"]},{"version":"0.1.1022","items":["ドリンクコーナーのトッピング（氷・ホイップ・さくらんぼ・ミント）を、押すたびに 1 段ずつ、同じものを 5 段まで重ねられるようにしました（ホイップ 5 段重ねなど）。重ねた段数は、作ったドリンク・贈ったドリンクの絵にも出ます。"]},{"version":"0.1.1021","items":["ワワワード（Wordle）で文字を入力すると、画面のキーボードの押したキーが一瞬光るようにしました（キーボードで打ったときも、対応する画面のキーが光ります）。"]},{"version":"0.1.1020","items":["毎日の単語当てゲーム「Wordle」の名前を、アプリの中ではすべて「ワワワード」に変えました。"]},{"version":"0.1.1019","items":["2 人でフォトブースを使うとき、相手のブースへ歩いていく姿や「満員」が、ほかの人の画面にも正しく出るように直しました。"]},{"version":"0.1.1018","items":["チャット欄で自分の発言（文字・音声）にマウスを乗せても「直す」が見えなかったのを直しました。"]},{"version":"0.1.1017","items":["ドリンクコーナーに行っている間、同じ部屋のほかの人の画面でも、元の場所の小さなドリンクコーナーと小さなアバターが見えるように直しました。"]},{"version":"0.1.1016","items":["遠征中・キャンバス中・自動化を見せています・回路設計中・Wordle 中を同時にオンにしても、全部がアバターの上に横に並んで出るようにしました（3 つ以上のときは少し小さく）。"]},{"version":"0.1.1015","items":["同じ部屋にいる人のペット（すがた・名前・メーター・なかよし度・時期・性格・好み）を、その人のプロフィールカードの「ペットを見る」から、見るだけで見られるようにしました。ペットの画面の「ペットを見せる」で、自分のペットを見せるかどうかを切り替えられます（最初はオン）。"]},{"version":"0.1.1014","items":["ホームウィンドウのサーバーのチャット欄でも、自分の発言（文字・音声の文字起こし）にマウスを乗せると「直す」が出て、書き直せるようにしました。"]},{"version":"0.1.1013","items":["バックパック遠征隊に、コインで買えるアップグレード「光るマス」（最大 3 つ）を足しました。乗せたアイテムが強くなり（武器の攻撃・魔法の速さ・防具の体力・回復）、好きなマスへいつでも動かせます。"]},{"version":"0.1.1012","items":["バックパック遠征隊で、コインを使ってバックパックを広げられるようにしました（「列を足す」「行を足す」、最大 7×8。「最初から」でも広さはそのままです）。"]},{"version":"0.1.1011","items":["バックパック遠征隊に、T 字・S 字・十字・2×3・斜めなどの新しい形のアイテムを 10 個（ドット絵付き）足しました。「武器を並べる」「とげの鎧で守りながら返す」「回復を隣に置いて伸ばす」「魔法を並べる」と、置き方しだいで違う勝ち方ができます。"]},{"version":"0.1.1010","items":["ペットのお世話ボタンのアイコン、なでる・ほめる・あそぶ・みまもるで出るハートや星・ボール・おもちゃ、なかよし度のハート、「すがた」のボタンもドット絵にしました。"]},{"version":"0.1.1009","items":["ペットの画面（ペット・たまご・部屋・ボタン）をドット絵調にしました（ドリル隊と同じ見た目）"]},{"version":"0.1.1008","items":["すすめドリル隊の坑道が、パネルの幅いっぱいに広がるようにしました（パネルの大きさを変えると追従し、縦に伸ばすと見える深さが増えます）。"]},{"version":"0.1.1007","items":["バックパック遠征隊のアイテム（全 58 種）を絵文字からドット絵にしました。バックパックのマス・持ち物・詳細・戦利品・戦闘で飛んでいく物が、ドット絵で出ます"]},{"version":"0.1.1006","items":["ペットの画面が 1 画面に収まらず、ペットが見えなくなっていたのを直しました（メーターとお世話のボタンを 1 行に並べ、時期・性格は押すと開く形に）"]},{"version":"0.1.1005","items":["バックパック遠征隊の戦闘画面の自分側に、顔が自分のアバターのドット絵の主人公が出るようにしました。バックパックに入れたアイテムで、勇者・戦士・騎士・魔法使い・僧侶と見た目が変わります（ほかの人の遠征を見るときも、その人の主人公が出ます）"]},{"version":"0.1.1004","items":["ペットに、エリクソンの 8 つの発達段階にあわせた時期ができ、その時期のお世話のしかた（すぐ応える・みまもる・あそぶ・ほめる・毎日会いに来る など）で性格や好きな食べ物・すごし方が決まり、あいさつやセリフ・よろこび方・部屋の様子に表れるようにしました（新しいお世話「みまもる」「ほめる」も足しました）。"]},{"version":"0.1.1003","items":["すすめドリル隊の画面を、坑道・ドリル・鉱石・宝箱・化石・お宝・破片などの演出まで、ドット絵の見た目にそろえました。"]},{"version":"0.1.1002","items":["ペットが育て方（あげたごはんの種類・お世話のしかた・なかよし度など）によって、こども・おとなと違うすがたに進化するようにしました。見つけたすがたは「📖 すがた」で見られます。"]},{"version":"0.1.1001","items":["バックパック遠征隊で、ほかの人の遠征を自分のパネルを閉じずに別のパネルで見られるようにし、遠征に出る前（準備中）も「遠征を見せる」がオンならアバターの上に「遠征の準備中…」が出て、押すとその人のバックパックを見られるようにしました。"]},{"version":"0.1.1000","items":["おたのしみ › そのほか に「ペット」を追加しました。たまごから生まれた自分だけのペットに、インベントリのアイテムや魚・鉱石をあげたり、なでたり、あそんだり、おふろに入れたりしてお世話できます（生まれたときに付く名前は、あとから自分で変えられます）。"]},{"version":"0.1.999","items":["釣りで釣れる魚を 9 種類（キス・メバル・カレイ・スズキ、大物のカツオ・カンパチ・カジキ、ヌシのマンボウ・イトウ）増やしました。"]},{"version":"0.1.998","items":["バックパック遠征隊に新しいアイテムを 12 種（各レアリティに 2 つずつ）、合成工房にすすめドリル隊の鉱石のレアリティに沿ったレシピを 8 つ足しました。"]},{"version":"0.1.997","items":["すすめドリル隊で、掘るたびに破片が飛び、下へなめらかに掘り進み、深くなるほど暗く地層の見た目が変わるようにし、見つけた物がレアリティの色で光るようにしました。各レアリティに新しい掘り出し物「お宝」（10 種）を追加しました。"]},{"version":"0.1.996","items":["バックパック遠征隊の「格上げ合成」に「自動で合成する」スイッチを付けました。オンにすると、遠征で同じレアリティが 10 個そろったら自動で格上げ合成します（バックパックの中の物と強化した物は使いません）。"]},{"version":"0.1.995","items":["バックパック遠征隊で、戦いの結果やお知らせが出ても、バックパックやボタンの位置が動かないようにしました。「n 連撃！」などの演出で横スクロールバーが出たり消えたりすることもなくなりました"]},{"version":"0.1.994","items":["バックパック遠征隊で、段が進むと新しい敵（8 体）とボス（4 体）が出てくるようにし、敵の見た目を絵文字からドット絵にしました。"]},{"version":"0.1.993","items":["バックパック遠征隊の戦闘画面を刷新しました。攻撃したアイテムがモンスターへ飛び、バックパックの中でも光るようになり、斬撃・魔法・回復のエフェクトや大きさの変わるダメージ数字、会心・連撃・とどめ・逆転勝利などの見せ場、5 段ごとに変わる背景、モンスターごとの動きが付きました。"]},{"version":"0.1.992","items":["バックパック遠征隊の画面で「遠征に出る」をいつも下に見えるようにし、遠征の設定と遊び方の説明は必要なときに開ける形にして、スクロールを減らしました"]},{"version":"0.1.991","items":["フィードバックを送るとき、「ログも一緒に送る」が種類「要望」では最初からオフ、「不具合」「その他」ではオンになるようにしました（手で切り替えたら、その選択を送るまで保ちます）。"]},{"version":"0.1.990","items":["合成工房の「メイン＋サブ」で、同じアイテムを 1 行にまとめ、アイテム・魚・鉱石のしぼりこみと並べ替え（おすすめ・レアリティ・種類・売値）を付けて、目当ての材料を探しやすくしました。サブは、いま選んでいるメインを強くできる物から並びます。"]},{"version":"0.1.989","items":["ホームウィンドウでサーバーを選ぶと、通話に入らなくてもそのサーバーのチャットを読んだり書き込んだりできるようにしました（Web 版と同じ）。"]},{"version":"0.1.988","items":["ドリンクコーナーでカップの蓋（なし・フラット・ドーム）も選べるようにしました。ストローは蓋を通り、作ったドリンクを飲むとき・贈るときもその蓋で見えます。"]},{"version":"0.1.987","items":["ドリンクコーナーで、カップの形（グラス・スリム・ジョッキ）、ストローのあり・なし、氷・ホイップ・さくらんぼ・ミントのトッピングを選べるようにしました。選んだものは、みんなに見える作ったドリンクや贈ったドリンクの絵・名前にも出ます。"]},{"version":"0.1.986","items":["ドリンクコーナーで作ったドリンクを、自分の足元に置いて飲んだり、「ドリンクを贈る」から部屋の人に贈ったりできるようにしました。"]},{"version":"0.1.985","items":["おたのしみに「ドリンクコーナー」を追加しました。行っている間は元の場所に小さなドリンクコーナーと小さなアバターが見え、注ぎ口を押した長さだけ注いで混ぜると色が変わり、戻ると作ったドリンクの名前がみんなに表示されます。"]},{"version":"0.1.984","items":["設定「音 › 効果音・通知」に「アップデートのお知らせの音」を足し、オフにするとアップデートのお知らせ（郵便屋さんの手紙のあと・自動アップデートの 10 秒前・アップデートしましたのお知らせ）だけ音を鳴らさないようにできるようにしました。お知らせ自体はいままでどおり出ます。"]},{"version":"0.1.983","items":["アバターダービーのレース中に、カメラが先頭を追いかけるようにし、控えめな歓声と（オンにすれば）実況の読み上げが流れるようにしました。"]},{"version":"0.1.982","items":["アバターダービーで、単勝のほかに複勝・馬連・馬単でもかけられるようにしました（オッズはかけ方ごとに、しめきりまでみんなの画面で動きます）。"]},{"version":"0.1.981","items":["バックパック遠征隊の「負けたら:」に「第 1 段から進む」を足しました。負けたら第 1 段に戻り、勝てばそこから先へ進みます（持ち物はそのまま）。"]},{"version":"0.1.980","items":["おたのしみに「アバターダービー」を追加しました。部屋のみんなのアバターが走るレースで、1 着をおたのしみのコインで当てられます（オッズはしめきりまでみんなの画面で動き、全員が同じレースを見ます）。"]},{"version":"0.1.979","items":["「ドリンクを贈る」で贈れるドリンクに、オレンジジュース・麦茶・牛乳・いちごミルク・タピオカミルクティー・ココア・ラムネ・エナジードリンクの 8 種類を足して、16 種類から選べるようにしました。"]},{"version":"0.1.978","items":["すすめドリル隊の強化「自動売却」をなくしました。買っていた方には代金の 120 コインをお返しします（自動で売りたいときは、おたのしみの「自動化」の「鉱石・魚を売る」が使えます）。"]},{"version":"0.1.977","items":["チャット・ホームウィンドウ・DM・ささっと入力で書きかけの文章が、アプリの再起動（自動更新など）のあとも残るようにしました（送ると消えます。添付の画像・動画は残りません）。"]},{"version":"0.1.976","items":["バックパック遠征隊でアイテムを人に渡したとき、同じ通話のほかの人にも「〇〇 さんが △△ さんに□□を渡しました」と出るようにしました。"]},{"version":"0.1.975","items":["バックパック遠征隊の「負けたら:」に「1 つ手前から進む」を足しました。負けたら 1 つ手前の段に戻り、勝てばそこから先へ進みます。"]},{"version":"0.1.974","items":["バックパック遠征隊で、遠征に出る前に「負けたら: 終える／1 つ手前をくり返す／同じ段に挑み続ける」を選べるようにし、負けても遠征を続けられるようにしました。"]},{"version":"0.1.973","items":["遠征隊のアイテムを 16 種類増やし、どのレアリティにも 5〜7 種類そろうようにしました（新しい戦利品は第 4 段から、レジェンダリーとミシックの新しい物は格上げ合成で手に入ります）","遠征隊の持ち物で同じアイテムが 1 つにまとまって「×数」で出るようになり、持てる数を 40 個から 120 個に増やしました（格上げ合成もまとまりから個数を選べます）"]},{"version":"0.1.972","items":["同じ項目を何回かに分けてお届けしたとき、前の版で載せた説明が次の版の更新履歴にもう一度載らないようにしました。"]},{"version":"0.1.971","items":["（アプリの変化なし。チーム内の仕組みだけ）協力者宛ての連絡が、届かないまま黙って既読になることがなくなりました。"]},{"version":"0.1.970","items":["チームの仕組みの直しで、アプリ自体は変わりません。返事を担当する係が止まったまま連絡がたまる件を直しました（止まっていれば見張りが気づいて知らせ、起動に時間の上限を付けました）。"]},{"version":"0.1.969","items":["アプリの見た目や動きは変わりません（開発チームの仕組みの直し）。取り下げたチケットの変更が、自動で取り込まれて出てしまうことがなくなりました。"]},{"version":"0.1.968","items":["アプリの変更はありません（開発チームの取り込みの仕組みを直しました）。"]},{"version":"0.1.967","items":["バックパック遠征隊の持ち物を 40 個まで持てるようにし、アイテムにレアリティ（コモン〜ミシックの 6 段階）を表示し、同じレアリティ 10 個を合成すると 1 つ上のレアリティのアイテムがランダムでもらえる「格上げ合成」を足しました。"]},{"version":"0.1.966","items":["ホームウィンドウを触ると、おたのしみ・すすめドリル隊などのウィンドウより手前に来るようにしました（最後に触ったウィンドウが一番手前に来ます）。","バックパック遠征隊に「おまかせ」ボタンを足しました。押すと、持ち物とバックパックの全部から、次の遠征の敵に強い組み合わせでバックパックを詰め直します（あとから手で入れ替えられます）。","バックパック遠征隊で、持ち物を残したまま前の段に戻って遠征できるようにしました（段の表示の ◀ ▶ で選べます）。ボスに勝てないときも、倒せる敵からアイテムを集め直して強くなれます","バックパック遠征隊の「最初から」でもらうはじめの持ち物を売れないようにし、くり返してもコインが増えないようにしました","バックパック遠征隊で、木の剣より強い攻撃アイテムを持っていないうちは第 3 段からのたからで必ず手に入るようにし、攻撃アイテムが引けずに詰むことがないようにしました","誰かが話してフキダシが出る・伸びるときに、横書きのフキダシが隣の人のほうへ寄ったり重なったりするのを直しました。","バックパック遠征隊で、持ち物を残したまま前の段に戻って遠征できるようにしました（段の表示の ◀ ▶ で選べます）。ボスに勝てないときも、倒せる敵からアイテムを集め直して強くなれます。","バックパック遠征隊の「最初から」でもらうはじめの持ち物を売れないようにし、くり返してもコインが増えないようにしました。","バックパック遠征隊で、木の剣より強い攻撃アイテムを持っていないうちは第 3 段からのたからで必ず手に入るようにし、攻撃アイテムが引けずに詰むことがないようにしました。","ホームのサーバーのチャット欄で、添付ボタン・貼り付け（Ctrl+V）・ドロップから画像や動画を送れるようにしました。","開発チームへの DM に、使っているアプリのバージョンと OS が自動で添えられるようにしました（お客様が書き足さなくても、チームが版を確かめられます）。","バックパック遠征隊で、木の剣より強い攻撃アイテムを持っていないうちは第 3 段からのたからで必ず攻撃アイテムが手に入るようにし、攻撃アイテムが引けずに詰むことがないようにしました。","すすめドリル隊で「地上に戻る」と、次は 0 m から新しい地下を掘り直すようにしました（鉱石・強化・図鑑・最深記録はそのまま。最深記録より浅くても 100 m ごとに少しコインがもらえます）。"]},{"version":"0.1.965","items":["おたのしみの窓から開く「じゃんけん」「決闘」「サイコロ」「回転ずし」「ショップ」も別の窓で開くようにし、おたのしみの窓は一覧のまま並べて使えるようにしました。","「自動化」と「記録」を、おたのしみの窓とは別の窓で開くようにしました。おたのしみを開いたまま、自動化と並べて使えます。"]},{"version":"0.1.964","items":["サーバーに入っていなくても、一人でオート釣りができるようにしました（釣れた魚はインベントリに入り、自動化の「魚が釣れたとき」も動きます。竿や釣果が部屋の人に見えるのはサーバーにいるときだけです）。","開発チームへの DM に、お使いのアプリの版と OS を自動で添えるようにしました（ほかの方への DM やチャットには付きません）。"]},{"version":"0.1.963","items":["「ドックの分の場所をいつも空けておく」をオンにしても、通知が未読のときや着信中に効かず、ドックの出入りでアバターの列がずれていたのを直しました。並べ方を左寄せ／右寄せにして縁取りをオンにしたとき、どちらも効かなかったのもあわせて直しました。"]},{"version":"0.1.962","items":["診断用の記録を足しただけで、見た目や動きは変わりません（音声認識の読み込みの途中のメモリの記録を増やしました）。"]},{"version":"0.1.961","items":["通話中のメモリ使用量を調べるため、自分のアバターを読み込み始めたときの記録を診断ログに足しました（見た目や動きは変わりません）。"]},{"version":"0.1.960","items":["テストモード中、ダミーのアバターをクリックして Boop を自分の画面だけで試せるようにしました（ほかの人には届かず、Boop の回数にも入りません）。"]},{"version":"0.1.959","items":["設定の「好きな色を選ぶ」で色を動かしている間、パネルの色や見本がもたつかずに追いつくようにしました。","設定の「表示 › スキン」で、ドックの色をテーマの色とは別に選べるようにしました（「いつもの色」ならこれまでどおりです）。"]},{"version":"0.1.958","items":["テストモード中は、サーバーに入っていなくても、おたのしみのサイコロ・回転ずし・早押し・FEVER・ブラックジャック・タイピングダンジョン・みんなのキャンバスを自分の画面だけで試せるようにしました（コインや記録には入りません）。"]},{"version":"0.1.957","items":["ドックの「声を聞く」「マイク」の横に出る「全員をもぐもぐ化」などのボタンが、押したあとでもカーソルを離せば少しして消えるようにしました。"]},{"version":"0.1.956","items":["ホームの右端のメンバー一覧で、「通話中」「オンライン」「オフライン」の見出しを押すとその欄をたたんだり開いたりできるようにしました（たたんだ状態は次に開いたときも覚えています）。"]},{"version":"0.1.955","items":["ホームの左の列で、いま通話中のサーバーのアイコンを右クリックしたときの小窓からも「通話から退出」できるようにしました（「サーバーから脱退」はいまどおり別の行の「…」の奥です）。"]},{"version":"0.1.954","items":["ドックのボタンにカーソルを合わせたときの説明を、ボタンの名前（とオン／オフ）だけにして、「おたのしみメニュー」の名前を「おたのしみ（メニュー）」に変えました。"]},{"version":"0.1.953","items":["設定（表示 › 演出）の「自分の登場の動き」の名前を「入場モーション」に変え、ショップの見出し・買ったときのお知らせ・自動化の名前も同じ呼び名にそろえました。"]},{"version":"0.1.952","items":["おたのしみウィンドウの「出しっぱなし」（ピン）をオンにしたとき、背景が塗りつぶされず、ピンのアイコンの色が変わるだけにしました。"]},{"version":"0.1.951","items":["チャットログで「直打ちだけ」をオンにすると、日付のタブが自動で「すべて」になり、全部の直打ちの投稿が出るようにしました。"]},{"version":"0.1.950","items":["「通話から退出」がある管理欄などで「…」を押すと、押した場所に「サーバーから脱退」が来てしまうのを直しました（「…」は動かず、脱退はその左に出ます）。"]},{"version":"0.1.949","items":["ドックの「ホーム」「なかま」「更新履歴」で開いたホームウィンドウを、もう一度同じボタンを押すと閉じられるようにしました（ほかのドックのボタンと同じ、開く/閉じるの切り替えです）。"]},{"version":"0.1.948","items":["サーバーの「…」（その他の操作）を右端に置き、押したときの「脱退」は「…」の下に出るようにしました。続けて 2 回押しても脱退を押してしまわなくなります（3 か所とも同じ）。"]},{"version":"0.1.947","items":["サーバーの「脱退」ボタンを、「入る」などよく使うボタンの隣から離し、端の「…」を押したときだけ出るようにしました（右クリックの小窓・サーバーの管理・なかまの参加しているサーバー）。"]},{"version":"0.1.946","items":["自動化のボードで、ブロックをドラッグで囲む／クリックで選んでコピー（Ctrl+C）し、自分の自動化に貼り付け（Ctrl+V）できるようにしました。ほかの人が「見せる」にしている自動化からもコピーでき、貼ったきっかけはオフで入ります。"]},{"version":"0.1.945","items":["自動化で ● や ◆ から伸ばした線を何もない所で離すと、つなげられるブロックが輪のメニュー（分類ごと・よく使う物が先・ことばで絞り込み）で出て、選ぶとその場所に線がつながった状態で置けるようにしました。"]},{"version":"0.1.944","items":["自動化に名前を付けて何個も保存し、一覧から選んで編集・名前変更・複製・削除できるようにしました（「動かす」がオンのものは同時に動き、今までの自動化は「自動化 1」として残ります）。"]},{"version":"0.1.943","items":["贈ったドリンクが画面の下の端ぎりぎりを、ゆっくり動き出してどんどん速く（スピード線付きで）流れ、相手の前で「キキーッ」と急ブレーキで止まって上の部分がしなって揺れ戻るようにしました。届いたときの吹き出しには「あちらのお客様からです」の一言も出ます。"]},{"version":"0.1.942","items":["自動化に「けいさん」の「鑑定」ブロックを足しました。釣れた魚のレアリティ・値段・大きさ・強化の段階を出せます。「もし」の「◆ 値が○以上／以下／○と同じ」にその値をつなぐと、「値段が 10 以上の魚は売らずに残す」のような決まりを自分で組めます（使い方ガイドにお手本があります）。"]},{"version":"0.1.941","items":["自動化の「アイテムを売る」「鉱石・魚を売る」で、大物・ヌシ・強くした魚を残すか（初期値・今までどおり）売るかを選べるようにしました。"]},{"version":"0.1.940","items":["「ドなでる」（と暗殺）で自分のアバターが歩いていくとき、途中にいるほかの人のアバターの手前ではなく、裏を通るように直しました。"]},{"version":"0.1.939","items":["自動化に「値の線」を足し、「魚が釣れたとき」の ◆ 釣れた魚 を新しいやること「アイテムを売る」の ◆ 売るもの につなぐと、釣れた魚をその場で売れるようにしました（大物・ヌシ・強くした魚は売らずに残します。食べたネタを回転ずしに流すこともできます）。"]},{"version":"0.1.938","items":["自動化のきっかけに「ボタンを押したとき」を足しました。ブロックの ▶ ボタンを押すと、つないだやること（「鉱石・魚を売る」など）を好きなときに 1 回動かせます。"]},{"version":"0.1.937","items":["なでる・贈ったドリンク・回転ずしの表のお寿司・スタンプなどの演出が、名札や扇形メニューが出ているときもアバターの裏に隠れず、いつも手前に出るようにしました（回転ずしの裏のレーンはいつもアバターの奥です）。"]},{"version":"0.1.936","items":["自動化に「まとめる・分ける」の分類を足し、線を束ねる・分けるブロック（○本そろったら、きっかけがそろったら、ぜんぶに分ける、順番に 1 本ずつ、ランダムに 1 本だけ、覚えた数をまとめる、覚えた値を配る）を使えるようにしました。使い方ガイドにも、まとめ方・分け方とお手本を載せました。"]},{"version":"0.1.935","items":["おたのしみの「釣った魚」パネルをなくし、魚を見る・売るはインベントリにまとめました（魚のタブから小魚をまとめて売れます）"]},{"version":"0.1.934","items":["釣った魚を売るときの 1 日 🪙100 の上限をなくし、何匹でもいつでも売れるようにしました"]},{"version":"0.1.933","items":["ドリンクを贈ると、回転ずしのようにアバターの並びの前を、間の人の前も通って相手の足元まで流れていくようにしました（遠い人ほど少し長く、最大でも約 4.4 秒）。"]},{"version":"0.1.932","items":["すすめドリル隊・合成工房（と 釣った魚・インベントリ）の画面が、ウィンドウを広げると中身も広がり、縦が狭くてもつぶれずスクロールで見られるようにしました（ドリルの坑道は大きさに合わせて大きくなります）"]},{"version":"0.1.931","items":["すすめドリル隊でもぐっている間、アバターの足元に出ていた深さ（〇〇 m）の札を出さないようにしました（ほかの人の画面でも出ません。深さは足元のドリルを押して開く地下の様子で見られます）。"]},{"version":"0.1.930","items":["おたのしみに「インベントリ」を追加しました。遠征隊のアイテム・釣った魚・掘った鉱石・もらったドリンクを同じ形のマスで一覧でき、絞り込み・並べ替えができ、選ぶと説明が出てそこから売れます（値段・上限はそれぞれのおたのしみと同じ）。"]},{"version":"0.1.929","items":["おたのしみの「自動化」に「鉱石・魚を売る」を追加し、「○分ごと」などのきっかけと組み合わせて、すすめドリル隊の鉱石や釣った魚を自動で売れるようにしました。"]},{"version":"0.1.928","items":["合成工房に「メイン＋サブ」を足し、好きなアイテムや釣った魚を 2 つ合わせると、メインがサブの種類の称号付きで +1・+2… と強くなり（例: 癒しのアジ+1）、枠が光る・金色・虹色と見た目も豪華になるようにしました。","合成工房で合成すると、自分のアバターの上に小さな魔法陣が出て、できた物が飛び出す様子が同じ部屋の人にも見えるようにしました（古い版の人には出ません）。"]},{"version":"0.1.927","items":["ドリンクを贈ると、贈った人のアバターの前にドリンクが現れ、相手の足元までスーッと流れていって届くようにしました（同じ部屋のほかの人の画面でも同じように見えます）。"]},{"version":"0.1.926","items":["合成工房に「メイン＋サブ」を足し、好きなアイテムや釣った魚を 2 つ合わせると、メインがサブの種類の称号付きで +1・+2… と強くなり（例: 癒しのアジ+1）、枠が光る・金色・虹色と見た目も豪華になるようにしました。"]},{"version":"0.1.925","items":["すすめドリル隊でもぐっている間もアバターが消えずに並びに出たままになり、足元で回るドリルと土ぼこり、深さの小さな札で「掘っている」とわかるようにしました（札やドリルを押すと、これまでどおり地下の様子が見られます）。"]},{"version":"0.1.924","items":["釣った魚を売ってコインにできるようにしました（おたのしみ › そのほか の「釣った魚」から、1 匹ずつ・小魚をまとめて売れます。大物とヌシは確かめてから売ります。1 日 🪙100 まで）"]},{"version":"0.1.923","items":["すすめドリル隊の強化を割に合うようにし（ドリルの刃・モーター・ふるい・自動売却の 4 種類、強化したあとの稼ぎの目安を表示、深い鉱石ほど高く売れる）、地層・鉱脈・化石・図鑑・到達ボーナスを足しました。"]},{"version":"0.1.922","items":["「💢 暗転ラッシュ」の暗転をさらに暗く、ほぼ真っ暗にしました（真ん中の 2 人と連打のエフェクトは見えます）。"]},{"version":"0.1.921","items":["おたのしみに「合成工房」を追加しました。バックパック遠征隊の持ち物・すすめドリル隊の鉱石・釣った魚をまぜて、遠征隊で使える強い装備（炎の剣・星の杖・竜のうろこなど 9 種）を、光って回ってはじける合成アニメーション付きで作れます。"]},{"version":"0.1.920","items":["バックパック遠征隊の持ち物を、1 つずつ、またはまとめて売ってコイン（ショップと同じ）にできるようにしました。強い物とまとめ売りは、もう一度押して確かめてから売ります。"]},{"version":"0.1.919","items":["すすめドリル隊の地下を横 3 列から 5 列に広げました（途中まで掘った深さ・鉱石・強化はそのまま続きから掘れます）。"]},{"version":"0.1.918","items":["必殺エモート「💢 暗転ラッシュ」で 2 人のまわりが暗くなる演出を、ひと目で暗転とわかる濃さにしました。"]},{"version":"0.1.917","items":["おたのしみに新しい放置ゲーム「すすめドリル隊」を足しました。「もぐる」とアバターがドリルで地下を自動で掘り進み、鉱石を集めて売ったコインでドリルを強くできます。もぐっている間はアバターの代わりに大きな下向きの矢印が出て、押すと地下の様子が見られます（ほかの人の画面に出すのは次の更新で）。","すすめドリル隊でもぐっている人は、ほかの人の画面でもアバターの代わりに大きな下向きの矢印になり、矢印を押すとその人の地下の様子が見られるようにしました（#1543 の続き。先に #1543 を取り込んでください）。"]},{"version":"0.1.916","items":["おたのしみに新しい放置ゲーム「すすめドリル隊」を足しました。「もぐる」とアバターがドリルで地下を自動で掘り進み、鉱石を集めて売ったコインでドリルを強くできます。もぐっている間はアバターの代わりに大きな下向きの矢印が出て、押すと地下の様子が見られます（ほかの人の画面に出すのは次の更新で）。"]},{"version":"0.1.915","items":["相手のアバターのメニューの「攻撃」に、近づいて 2 人のまわりが暗くなり連打が入る必殺エモート「💢 暗転ラッシュ」を追加しました（受けた人は HP 0 でダウン。🛡 で防げ、暗殺と合わせて 3 分に 1 回）。"]},{"version":"0.1.914","items":["ホームウィンドウでフレンドを押すと、左にフレンド一覧を残したまま右にその人とのメッセージが出るようにしました（別のフレンドを押すと右が切り替わります）。"]},{"version":"0.1.913","items":["設定の「参加者の並び」に「並べ方（均等／左寄せ／右寄せ）」を足し、横に並べるとき、アバターを前のように画面の左端・右端へ詰めて並べられるようにしました（既定は今の均等のままです）。"]},{"version":"0.1.912","items":["みんなのキャンバスで、「動かす」でつかんだ（または「選ぶ」で 1 つ選んだ）文字・メモ・画像・スタンプの大きさを角のつまみで、向きを上の丸いつまみで変えられるようにしました（ほかの人の画面と保存した画像にも同じ大きさ・向きで出ます）。"]},{"version":"0.1.911","items":["相手のアバターの 👊 攻撃 に 🔪 暗殺 を追加しました。自分のアバターが相手の背後に回り込んでナイフで切り、受けた人は HP 0 でダウンします（戦闘に参加している人どうしで、🛡 で防げます。1 回使うと 3 分待ち）。"]},{"version":"0.1.910","items":["設定の「全体」で画像の保存先のフォルダを選べるようにしました。みんなのキャンバスの「画像で保存」とフォトブースの写真がそこに保存されます（選ばなければこれまでどおりピクチャ。フォルダが見つからないときはピクチャに保存してお知らせします）"]},{"version":"0.1.909","items":["ホームウィンドウのフレンド一覧でフレンドを押すと、別のウィンドウを開かずに、ホームウィンドウの中にその人とのメッセージの履歴と入力欄が出るようにしました（「‹ もどる」でフレンド一覧に戻ります）。"]},{"version":"0.1.908","items":["みんなのキャンバスの「文字」で、書体（ゴシック・明朝・教科書体・等幅）と太字を選べるようにし、大きさも小・中・大のほかにスライダーで細かく選べるようにしました。"]},{"version":"0.1.907","items":["バックパック遠征隊で、バックパックが満杯のまま遠征に出ても 1 戦で終わらず、戦い続けられるようにしました（見つけた物は持ち物へ入り、持ち物もいっぱいのときは持ち帰れなかった数を結果に出します）"]},{"version":"0.1.906","items":["フォトブースを「おたのしみ」の一覧（そのほか）から開けるようにし、じぶんからの入り口はなくしました（ほかの人のフォトブースをクリックして一緒に入るのは今までどおりです）。"]},{"version":"0.1.905","items":["ホームウィンドウでサーバーを開いたまま「フレンド」を押すと、サーバーの選択が外れ、通話・メンバーの列が消えてフレンド一覧が全体に出るようにしました（通話中なら通話はそのまま続きます）。"]},{"version":"0.1.904","items":["通知のボタンをドックの「ホーム」と「設定」の間に固定し、ほかのものをよけて動いたり重なったりしないようにしました。押すと通知の画面が開き、届いている通知に加えて、この 7 日間の通知の履歴も見られます（履歴はこの PC の中にだけ残り、「履歴を消す」で消せます）。"]},{"version":"0.1.903","items":["みんなのキャンバスに「選ぶ」を追加し、クリックで 1 つ・ドラッグで囲んで複数を選んで、まとめて動かしたり、コピー・貼り付け（ボタンと Ctrl+C / Ctrl+V）で少しずらした所に複製し、貼ったものをそのまままとめて動かしたりできるようにしました。"]},{"version":"0.1.902","items":["みんなのキャンバスに「アバタースタンプ」を足しました。今の自分のアバターの絵（背景は透明）を、クリックした所に何個でも押せます（大きさは小・中・大、「撮り直す」で今の見た目に）。ほかの人のキャンバスにも出て、「動かす」で移動もできます。"]},{"version":"0.1.901","items":["ホームウィンドウで左のサーバーを押しただけでは通話に入らず、中を見るだけになりました。2 列目の「通話」を押したときに通話に入ります（通話中のサーバーには小さな印が付きます）。","ホームウィンドウで左のサーバーを押しただけでは通話に入らず、中を見るだけになりました。2 列目の「通話」を押したときに通話に入ります"]},{"version":"0.1.900","items":["登場の動き「風船で降りてくる」の風船を 3 個から 9 個に増やしました。"]},{"version":"0.1.899","items":["ホームウィンドウのレイヤーの列とメンバーの列の幅を、チャットとの境目をドラッグして変えられるようにしました（変えた幅は次に開いたときも残ります。ダブルクリックで元の幅）。"]},{"version":"0.1.898","items":["アプリを起動したとき、ゲームのキャプチャーボードを顔トラッキングのカメラとして勝手に開いてしまい、OBS の映像が真っ黒になる不具合を直しました。カメラを「既定」にしているときは普通の Web カメラを選び、キャプチャーボードしか無いときは開かずに知らせます（設定 → カメラで選べば使えます）。"]},{"version":"0.1.897","items":["ホームウィンドウを、上の帯と 4 つの列（サーバー／通話の部屋と中にいる人／チャット／メンバー）の並びにしました。メンバーは名前で絞り込めます。ウィンドウが狭いときは、メンバーなどの列を上の帯のボタンから開けます。"]},{"version":"0.1.896","items":["アップデートを入れるところで Windows やセキュリティソフトに止められたとき、「アップデート中 0%」のまま固まらず案内が出るようにし、「もう一度」でダウンロードし直さずに入れ直せるようにしました。"]},{"version":"0.1.895","items":["設定 › 全体 のバージョン番号を、ドラッグで選んでコピーしたり、「コピー」ボタンでコピーしたりできるようにしました。"]},{"version":"0.1.894","items":["アップデートのダウンロードが途中で止まったとき、「アップデート中 0%」のまま動かなくなる不具合を直しました。一定時間データが届かなければ失敗として知らせ、「もう一度」か配布ページから最新版を手動で入れる方法を案内します。","アップデートが「アップデート中 0%」のまま止まったときに、あきらめて手でのインストール方法を案内するようにしました"]},{"version":"0.1.893","items":["通話中のメモリが多い件の調べとして、アバターを読み込んだときに、形とブレンドシェイプ（表情の形）がどれだけメモリを使うかをログに残すようにしました（アプリの動きは変わりません）。"]},{"version":"0.1.892","items":["自動化のやることを 15 種類足しました（文の読み上げ、音量、ゲーム・曲の表示をやめる、攻撃・なでるの演出、アバターの表情・大きさ・奥行き、窓や大きくした画面共有を閉じる、サイコロ、リアクション、覚えた値の通知・読み上げ・一覧）。「🔍 ブロックをさがす」からも置けます。","自動化のきっかけを 15 種類足しました（カメラ・ゲーム・再生中の曲が変わったとき、倒れたとき、必殺技ゲージがたまったとき、DM が届いたとき、部屋の人の絵文字・倒れた・しばらく静か・部屋の動画、スタンプを飛ばしたとき、起動して／部屋に入って／離席して○分、毎月○日の時刻）。「🔍 ブロックをさがす」からも置けます。","自動化の流れ・条件・値を 35 種類足しました（メモ・つなぎ、覚えた数やランダムな回数のくり返し、時間帯・月・日にち・回数・人数・HP などで分ける条件、最高記録・ストップウォッチ・くじ引き・スイッチなどの値）。「🔍 ブロックをさがす」からも置けます。","自動化のきっかけ「自分のゲームが変わったとき」の説明に、Steam で非表示・非公開にしたゲームでは動かないことを書き足しました。"]},{"version":"0.1.891","items":["自動化のやることを 15 種類足しました（文の読み上げ、音量、ゲーム・曲の表示をやめる、攻撃・なでるの演出、アバターの表情・大きさ・奥行き、窓や大きくした画面共有を閉じる、サイコロ、リアクション、覚えた値の通知・読み上げ・一覧）。「🔍 ブロックをさがす」からも置けます。","自動化のきっかけを 15 種類足しました（カメラ・ゲーム・再生中の曲が変わったとき、倒れたとき、必殺技ゲージがたまったとき、DM が届いたとき、部屋の人の絵文字・倒れた・しばらく静か・部屋の動画、スタンプを飛ばしたとき、起動して／部屋に入って／離席して○分、毎月○日の時刻）。「🔍 ブロックをさがす」からも置けます。","自動化の流れ・条件・値を 35 種類足しました（メモ・つなぎ、覚えた数やランダムな回数のくり返し、時間帯・月・日にち・回数・人数・HP などで分ける条件、最高記録・ストップウォッチ・くじ引き・スイッチなどの値）。「🔍 ブロックをさがす」からも置けます。"]},{"version":"0.1.890","items":["自動化に「📘 使い方ガイド」を追加しました。何を自動化すると便利か（役に立つ 4 つの条件、きっかけの 3 つの型）を順に説明し、お手本をボタン 1 つでボードに置いて試せます。"]},{"version":"0.1.889","items":["ショップで登場の動きを 4 種類（ロケットで飛んでくる・ワープで現れる・くるくる回って登場・ドロンと登場、各 30 コイン）買えるようにし、買ったものを「自分の登場の動き」で選ぶと、あとから通話に入ったときにほかの人の画面でもその動きで出るようにしました。"]},{"version":"0.1.888","items":["フォトブースに 2 人で入って撮った写真が、撮らなかった人の手元にも届き、スタンプを貼る・アイコンに使う・保存ができるようにしました。"]},{"version":"0.1.887","items":["フォトブースに一緒に入った人も、写真の上をドラッグ・ホイールして自分のアバターを動かせるようにし、入った直後から 2 人の画面と写真で写り方がそろうように直しました"]},{"version":"0.1.886","items":["通話中に相手のアバターが透明になることがある問題で、映像が空になったときに画面の内容を直接読み直して送れるようにしました","通話中に相手から自分のアバターが透明に見えてしまう件で、送る絵が空になっていると気づいたら、別の読み方で絵を取り直して送るようにしました"]},{"version":"0.1.885","items":["相手からアバターが透明に見えるとき、送る側が自分の絵を別の読み方で取り直して送るようにしました。","通話中に相手から自分のアバターが透明に見えてしまう件で、送る絵が空になっていると気づいたら、別の読み方で絵を取り直して送るようにしました。"]},{"version":"0.1.884","items":["パソコンの描画（GPU）が一時的に落ちて戻ったとき、顔トラッキングも待たずにすぐ立て直すようにしました。画面を隠していた間を「顔が見つからない時間」に数えないようにしました（カメラが止まって離席中のままになる件の調査と対策の続きです）。"]},{"version":"0.1.883","items":["顔トラッキングが動いているのに顔が見つからない状態が続いたとき、カメラのオン・オフと同じ立て直しを自動で行うようにしました（30 秒後から、間をあけて）。そのときの映像の様子も診断ログに残します。"]},{"version":"0.1.882","items":["カメラ（顔トラッキング）が止まって「離席中」のまま戻らなくなったとき、アプリが自分で気づいてカメラと検出を立て直すようにし、何が止まったかを診断ログに残すようにしました。"]},{"version":"0.1.881","items":["顔トラッキングが止まったとき、アプリが自分で気づいてカメラや検出を立て直すようにしました（T-1208 にまとめて報告）。"]},{"version":"0.1.880","items":["フォトブースで、明るさ・光の色・光の向き・スポットライトなどの演出を選んで撮れるようにしました（撮った写真にも入ります）。"]},{"version":"0.1.879","items":["設定の「表示」のドックに「ドックの分の場所をいつも空けておく」を足し、オンにするとドックが出たり引っこんだりしてもアバターとそのボタンの位置が変わらないようにしました。"]},{"version":"0.1.878","items":["おたのしみのタイルで、アイコンと名前のまとまりがタイルの真ん中にそろい、アイコンと名前の間を少しあけました。"]},{"version":"0.1.877","items":["不具合の報告に付くログで、アバターのテクスチャをどれだけ縮めたかの記録が、長い通話のあとでも消えずに残るようにしました（アプリの動きは変わりません）。"]},{"version":"0.1.876","items":["回転ずしに「モザイク寿司」を追加しました。食べると 15 秒間、アバターの顔にモザイクがかかり、声がかなり低くなります。"]},{"version":"0.1.875","items":["「おたのしみ」の窓を小さくし、項目をアイコンと名前のタイルに詰めて、短い距離で選べるようにしました。それぞれの説明と今の状態は、タイルにマウスをのせると窓の下に出ます。"]},{"version":"0.1.874","items":["フォトブースの背景に、色（ピンク・きいろ・みずいろ・むらさき・くろ・しろ）、柄（みずたま・しましま・チェック・ハート）、風景（あおぞら・ゆうやけ・よぞら・もり）を足し、19 種類から無料で選べるようにしました。"]},{"version":"0.1.873","items":["「Steam で遊んでいるゲームを表示」がオンでも、Steam のライブラリで非表示にしたゲームは、部屋のみんなに名前が出ないようにしました。","「Steam で遊んでいるゲームを表示」がオンでも、Steam で「ゲームを非公開にする」にしたゲームは、部屋のみんなに名前が出ないようにしました。"]},{"version":"0.1.872","items":["「Steam で遊んでいるゲームを表示」がオンでも、Steam のライブラリで非表示にしたゲームは、部屋のみんなに名前が出ないようにしました。"]},{"version":"0.1.871","items":["「コントローラーの手」の「手だけの間隔」を、これまでより広く（上限 0.5 → 1.2、片手あたり約 18cm まで）設定できるようにしました。"]},{"version":"0.1.870","items":["「コントローラーの手」に「手だけの間隔」を足し、コントローラーの幅はそのままで手の間隔だけを広げられるようにしました。"]},{"version":"0.1.869","items":["みんなのキャンバスで、中を塗った四角・丸を描けるようにし、ペンと蛍光ペンに手ぶれ補正（なし／弱／中／強）を付けました。"]},{"version":"0.1.868","items":["みんなのキャンバスで、好きな色を選んだり描いたものから色を取ったり（スポイト）、太さを細かく選んだり、下が透ける蛍光ペンで描いたり、「元に戻す」で消したものを「やり直し」で戻したりできるようにしました。"]},{"version":"0.1.867","items":["みんなのキャンバスに画像を貼れるようにしました（「画像を貼る」でファイルを選ぶか、Ctrl+V で貼り付け。10 枚まで。部屋にいる人に見え、保存はされません）。"]},{"version":"0.1.866","items":["みんなのキャンバスで、開いているほかの人のカーソルが名前付きで見えるようにし、右上のアイコンを押すとその人の見ている所へ飛んで、そのまま追いかけられるようにしました。"]},{"version":"0.1.865","items":["みんなのキャンバスの「動かす」で、自分が描いた線・図形・文字・メモ（と、部屋を出た人が描いたもの）をドラッグして移動できるようにしました。移動は部屋のみんなの画面にそろい、何もない所をドラッグすると今までどおり表示が動きます。"]},{"version":"0.1.864","items":["みんなのキャンバスの消しゴムで消せるのを、自分が描いたものと部屋を出た人が描いたものだけにしました。また、だれかが「すべて消す」を使ったときは、ほかの人の画面にだれが消したかを出すようにしました。"]},{"version":"0.1.863","items":["アバターが透明になる不具合を調べるため、映像が途切れた時刻をログに残すようにしました。"]},{"version":"0.1.862","items":["通話中にほかの人から自分のアバターが空に見えているとき、送る側のアプリが自分の映像を確かめて、映像を作り直すようにしました。"]},{"version":"0.1.861","items":["「おたのしみ」のウィンドウを一新し、各項目を押せる範囲の広いカードにして種類ごとに色分けし、オート釣りなどはオン／オフがひと目でわかるスイッチにしました（少し手が動いたクリックも、押したことになるようにしました）。"]},{"version":"0.1.860","items":["透明の部分がある大きいアバターの画像も小さくして読み込むようにし、通話中のメモリの使用量を減らしました。"]},{"version":"0.1.859","items":["画面と動きは変わりません。設定のアバターのプレビュー・フォトブース・ホームウィンドウを開いたときのメモリの量を、診断用のログに残すようにしました。"]},{"version":"0.1.858","items":["（AI に聞くの答えは、この更新だけでは変わりません）よくある質問を、初めての人がつまずく順に並べ替え、短くわかりやすい言葉に書き直しました（アバター・音とマイク・サーバーへの入り方・フレンド追加・パスワードを忘れたときの質問を足しました）。"]},{"version":"0.1.857","items":["チュートリアルで、アバターに VRM だけでなく UnityPackage も読み込めることと、サーバーへの入り方（招待・招待コード・自分で作る）がわかるようにしました。"]},{"version":"0.1.856","items":["はじめてアカウントを作ってログインした方に、ふだんの画面が出たあとでチュートリアルが自動で 1 回だけ表示されるようにしました（作成から 24 時間以内のアカウント、そのパソコンで 1 回だけ。今お使いの方には出ません）。"]},{"version":"0.1.855","items":["チュートリアルに「まずアバターを選ぶ」「音とマイクを確かめる」「復旧コードを控えておく」（ユーザー名でログインしている方のみ）の案内を足し、初めての方が最初の準備をしやすくしました。"]},{"version":"0.1.854","items":["バックパック遠征隊のアイテムを、通話中の人のアバターにドラッグして渡せるようにしました（相手が受け取ると、自分の持ち物から消えます）。"]},{"version":"0.1.853","items":["フォトブースに入っている人の奥の小さなブースをクリックすると、一緒に入っていいか聞けるようにしました。入っている人が「入れる」を押すと 2 人で写れます（写真はシャッターを押した人の手元にだけ残ります）。"]},{"version":"0.1.852","items":["フィードバックに付く調査用のログで、メモリの記録が長い通話のあとでも消えずに残るようにしました（画面や動きは変わりません）。"]},{"version":"0.1.851","items":["友達リンクの公開プロフィールを仕上げました。本人が「プロフィールを公開する」をオンにしているときだけ、ログインしていない人にもアイコンと表示名が見えます。"]},{"version":"0.1.850","items":["通話中に相手のアバターが透明になったときの原因を調べやすいよう、記録に残す情報を増やしました（見た目と動きは変わりません）。"]},{"version":"0.1.849","items":["通話中に特定の人のアバターが透明になる件で、次に起きたときに原因を調べられる記録を増やしました（原因は調査中で、これで戻らない場合があります）。"]},{"version":"0.1.848","items":["相手のアバターが透明のままのとき、相手のアプリへ映像の送り直しを自動で頼むようにしました。","通話中に相手のアバターの映像が描けず透明のままのとき、何も見えないままにせず名前の枠を出して、映像をつなぎ直すようにしました。"]},{"version":"0.1.847","items":["通話の相手から自分のアバターの映像が止まって見えているとき、送っている映像が切れていれば自動で取り直すようにしました。"]},{"version":"0.1.846","items":["もらったドリンクが、アプリを再起動（アップデートの入り直しも含む）しても、同じサーバーに戻れば足元に残り、続きから飲めるようにしました。部屋のほかの人の画面にも戻り、減り具合もそろいます。"]},{"version":"0.1.845","items":["自動化に「🔍 ブロックをさがす」を足し、分類やことばでブロックを見つけて置けるようにしました。あわせて、きっかけを 21 種類（話し始めたとき、スタンプやドリンクが届いたとき、だれかが離席したとき、部屋の人数、○分ごと、曜日と時刻 など）足しました。","自動化のやることを 12 種類足しました（「声を聞く」をオフ、もぐもぐを終える、映画・読書中にする、窓を開く・閉じる、ズーム、チャットの読み上げ、覚えた値を自分に見せる など）。","自動化に流れ・条件・値のブロックを 17 種類（ランダムに分ける、かわりばんこ、1 日に 1 回だけ、ぜんぶそろったら、ここで終わる、ランダムに待つ、部屋のようすで分ける、ランダムな数を覚える など）足し、T-1166 の合計 50 種類がそろいました。"]},{"version":"0.1.844","items":["自動化に「🔍 ブロックをさがす」を足し、分類やことばでブロックを見つけて置けるようにしました。あわせて、きっかけを 21 種類（話し始めたとき、スタンプやドリンクが届いたとき、だれかが離席したとき、部屋の人数、○分ごと、曜日と時刻 など）足しました。","自動化のやることを 12 種類足しました（「声を聞く」をオフ、もぐもぐを終える、映画・読書中にする、窓を開く・閉じる、ズーム、チャットの読み上げ、覚えた値を自分に見せる など）。"]},{"version":"0.1.843","items":["自動化に「🔍 ブロックをさがす」を足し、分類やことばでブロックを見つけて置けるようにしました。あわせて、きっかけを 21 種類（話し始めたとき、スタンプやドリンクが届いたとき、だれかが離席したとき、部屋の人数、○分ごと、曜日と時刻 など）足しました。"]},{"version":"0.1.842","items":["バックパック遠征隊で満杯になって遠征を終えたとき、そのお知らせを自分のアバターの上に出すようにしました（「遠征を見せる」がオンなら、同じ部屋のみんなにも見えます）。","バックパック遠征隊で遠征に負けたときも、満杯のときと同じく自分のアバターの上にお知らせが出るようにしました（「遠征を見せる」がオンなら同じ部屋のほかの人にも見えます）。"]},{"version":"0.1.841","items":["バックパック遠征隊で満杯になって遠征を終えたとき、そのお知らせを自分のアバターの上に出すようにしました（「遠征を見せる」がオンなら、同じ部屋のみんなにも見えます）。"]},{"version":"0.1.840","items":["バックパック遠征隊の遠征中は、アバターの上に「遠征中…」と出るようにし、ほかの人がクリックすると、その人の戦いとバックパックの中身をリアルタイムで見られるようにしました（見るだけです。遠征隊の画面の「遠征を見せる」でオフにできます）。"]},{"version":"0.1.839","items":["オート釣りとオート猫じゃらしのオンオフを、アプリの再起動やアップデートのあとも引き継ぐようにしました（オート釣りはサーバーに入ってから少しして再開します）。"]},{"version":"0.1.838","items":["（調べるための記録の追加で、見た目は変わりません）文字起こしや顔と手の追跡を読み込んだ前後、通話の入退室のときのメモリの量を、アプリの記録に残すようにしました。メモリを使いすぎる件の原因を調べやすくなります。"]},{"version":"0.1.837","items":["フキダシが横書きになる人数のときは、アバターどうしの間をあけて、フキダシが自分のアバターの上に収まるようにしました。"]},{"version":"0.1.836","items":["「ドなでる」をオン／オフできるスイッチを 設定 › 扇形メニュー に付け、既定をオフにしました（オフのときは、なでる 🤚 が以前と同じ 1 つのボタンに戻ります）。"]},{"version":"0.1.835","items":["「アップデートを郵便屋さんが届けにくる」と「ゲームの招待をアロハのくまが届けにくる」の設定を、設定の「全体」から「表示」›「演出」に移しました（よくある質問の案内も新しい場所に合わせました）。"]},{"version":"0.1.834","items":["回転ずしにたまにわさび入りのおすしが混ざるようにしました。見た目ではわからず、食べた人の頭の上に「つーん！」が通話のみんなの画面に出ます。"]},{"version":"0.1.833","items":["ホームウィンドウでフレンド一覧や更新履歴を開いているとき、左の列のサーバーのアイコンを押すだけで、「もどる」を押さなくてもチャットの画面に戻れるようにしました。"]},{"version":"0.1.832","items":["アバターの登場の演出の設定（「入ってきた人のアバターに登場の演出を出す」と「自分の登場の動き」）を、音・SE から 表示 › 演出 の欄に移しました。"]},{"version":"0.1.831","items":["みんなのキャンバスを 0.001〜1000 倍まで拡大・縮小できるようにし、どの倍率で描いた線・文字・メモも、そのあとの拡大・縮小で絵と一緒に大きさが変わるようにしました。","みんなのキャンバスを開いている間、アバターの上に「キャンバス中…」が出るようにし、ほかの人はそれをクリックするとキャンバスを開いて一緒に描けるようにしました。"]},{"version":"0.1.830","items":["バックパック遠征隊の遠征が自動で戦い続けるようになり、バックパックが満杯になると通知を出して終わるようにしました（負けたとき・撤退したときも終わります）。遠征に出る前に、パネルを閉じている間も進めるか、閉じたら止めるかを選べます。"]},{"version":"0.1.829","items":["自分が通話に入ったとき、自分の画面でも自分のアバターが選んだ登場の動きで出てくるようにしました（登場の演出がオンのとき）。また、設定の「自分の入場音」「自分の登場の動き」の選ぶ欄を「テスト」「見てみる」の横に並べ、選ぶ欄には ▾ と枠線を付けて、選べることがすぐわかるようにしました。"]},{"version":"0.1.828","items":["アバターどうしが近くても、となりの人のフキダシとの間があくようにし、くっついて窮屈に見えないようにしました。"]},{"version":"0.1.827","items":["相手のアバターの扇メニューの「なでる」にマウスを乗せると「なでる」と「ドなでる」が出て選べるようにしました（なでるボタンを押せば、今までどおりすぐなでます）。"]},{"version":"0.1.826","items":["バックパック遠征隊で、遠征中・戦闘中もバックパックが見えたままになり、アイテムを詰め替えたり持ち物へ移したりすると、その場で戦いに効くようにしました。"]},{"version":"0.1.825","items":["設定の「自分の登場の動き」で、あとから部屋に入ったときにほかの人の画面で自分のアバターがどう登場するか（歩いて来る・上から着地・風船で降りてくる）を選べるようにしました。「見てみる」で自分のアバターに試せます。"]},{"version":"0.1.824","items":["相手のアバターの扇メニューに「ドなでる」🚶を足しました。押すと自分のアバターが奥へ下がって相手の後ろまで歩いて行き、手で頭をなでて、また歩いて戻ります（ほかの人の画面にも出ます）。"]},{"version":"0.1.823","items":["おたのしみに「みんなのキャンバス」を追加しました。同じ部屋にいる人どうしで、ペン・四角・丸・直線・矢印・文字・メモ・消しゴムを使って 1 枚の大きなキャンバスにいっしょに描け、いつでも画像で保存できます。"]},{"version":"0.1.822","items":["おたのしみに新しいゲーム「バックパック遠征隊」を足しました。アイテムを回しながらバックパックに詰め、隣り合わせの組み合わせで強くして遠征に出ると、モンスターと自動で戦って戦利品が手に入ります（この PC に保存。負けても持ち物はなくなりません）。"]},{"version":"0.1.821","items":["映像を受けない設定の通話で、相手の静止画が消えたままになることがある不具合に対策しました。画面の描画がリセットされたときとつなぎ直しのときに、入り直さなくても静止画が戻るようにしました。","通話から出るボタンを「通話から退出」に、サーバーのメンバーをやめるボタンを「サーバーから脱退」にして、見分けやすくしました。"]},{"version":"0.1.820","items":["相手の映像を受けない設定で通話中につなぎ直しが起きても、相手のアバターの静止画が消えないようにしました。静止画が手元に無いときは、入り直さなくても自動で届き直します。"]},{"version":"0.1.819","items":["ゲームの招待のとき、ふみくまが郵便局ではなく、木の小さな「ふみくまのおうち」から出てきて、おうちへ帰るようにしました。"]},{"version":"0.1.818","items":["ふみくまが出てくる郵便局を、縦横それぞれ今の半分以下の大きさにしました（更新の手紙のときも、ゲームの招待のときも）。"]},{"version":"0.1.817","items":["ふみくまが歩くとき、一歩ごとに止まらず続けて進むようにし、体の左右・上下の揺れも小さくしました。"]},{"version":"0.1.816","items":["自動化のブロックの文字を入れる欄を大きく（折り返して伸びるように）し、貼り付けや {名前} などのボタンがカーソルの位置に入るように、また最初から入っている例の文は打てばそのまま置き換わるようにしました。"]},{"version":"0.1.815","items":["自動化の「見せる」をオンにしている間、アバターの上に「自動化を見せています…」と出るようにし、ほかの人がそれをクリックすると、その人の自動化を見られるようにしました。"]},{"version":"0.1.814","items":["ふみくまが歩くときのカバンの揺れを小さくし、体より少し遅れてなめらかに揺れるようにしました。"]},{"version":"0.1.813","items":["おたのしみの「自動化」で、窓の右下や端をドラッグして大きさを変えると、ブロックを置くボードも一緒に大きく・小さくなるようにしました。"]},{"version":"0.1.812","items":["（調べるための記録の追加で、見た目は変わりません）アプリの記録に、メモリがアプリのどの部分で使われているかの内訳を残すようにしました。メモリを使いすぎる件の原因を調べやすくなります。"]},{"version":"0.1.811","items":["お知らせとゲームの招待を届けに来るふみくまを、ドットの粗い見た目から、やわらかい色とこげ茶の線の、なめらかな見た目に変えました（帽子や上着の色、縫い目、アロハの服などの印と笑顔はそのままです）。"]},{"version":"0.1.810","items":["ドックの「なかま」やホームウィンドウの左の列の「フレンド」を押すと、別のパネルではなくホームウィンドウの中にフレンド一覧が出るようにしました（DM から「もどる」でもここにもどります）。"]},{"version":"0.1.809","items":["フォトブースで撮った写真を、貼ったスタンプや透明の背景もそのままに、画像（PNG）としてピクチャ フォルダに保存できるようにしました。"]},{"version":"0.1.808","items":["見た目は変わりません。ふみくまが見えなかったときの原因を調べられるよう、ふみくまが来た場所や来なかった理由を、フィードバックのログに残すようにしました。"]},{"version":"0.1.807","items":["ドックの「ホーム」でホームウィンドウが開くようにしました。サーバーにカーソルを合わせると入らずにいる人が見られ、右クリックで入らずに退出もできます。"]},{"version":"0.1.806","items":["頭のかざりのパトランプがしゃべっている間に強く光り、回転灯のように左右に光の帯が出るようにしました（演出 控えめや動きを減らす設定のときは、これまでどおり弱く点くだけです）。"]},{"version":"0.1.805","items":["頭のかざり「プロペラ帽子」を、帽子のない「プロペラ」（頭に立てた棒の先でプロペラが回る形）に変えました。すでに持っている人・付けている人もそのまま新しい形になり、しゃべっている間だけ回る動きは今までどおりです。"]},{"version":"0.1.804","items":["ホームウィンドウの左の列の一番上に「フレンド」を置き、フレンド一覧・申請・メッセージをそこから開けるようにしました。"]},{"version":"0.1.803","items":["頭のかざりに「パトランプ」を足し、ショップで 30 コインで買えるようにしました。しゃべっている間だけ赤く光って光がゆっくり回り、やめると消えます（演出を控えめにしているときは、回らずに弱く点くだけです）。"]},{"version":"0.1.802","items":["お知らせとゲームの招待を届けるふみくまが、いつも笑った顔になりました。奥の小さな郵便局から歩いて来て、近くでにこっと笑ってから手紙を出し、帰りは郵便局へ戻ります（演出を控えめにする設定でも笑顔です）"]},{"version":"0.1.801","items":["なでられたとき、誰がなでてくれたかを 1 つのお知らせにまとめて 20 秒ほど残すようにしました（同じ人は 1 つにまとめて回数を表示）。"]},{"version":"0.1.800","items":["ホームウィンドウの左の列のいちばん下に「じぶん」のボタンを置き、プロフィールの確認やフレンドコードのコピー、プロフィール・アカウントの変更、フォトブースをそこから開けるようにしました（ログインしていないときは上の帯の「ログイン」から）。"]},{"version":"0.1.799","items":["頭のかざりに「プロペラ帽子」を足し、ショップで売るようにしました。しゃべっている間だけプロペラが回り、やめるとゆっくり止まります。","自動化のやることに「かざりをぶるぶるさせる」を足しました。自分の頭（目・口・ぜんぶも選べます）のかざりを揺らせます（みんなに見えるので 10 秒に 1 回まで）。"]},{"version":"0.1.798","items":["釣った魚が、アプリの再起動やアップデートのあとも回転ずしの「釣った魚」の一覧に残るようにし、たくさん釣っても古い魚が消えにくくしました（12 匹まで → 200 匹まで）。それまでに消えた魚は記録が残っていないため、戻せません。","釣った魚の一覧が、アプリの再起動やアップデートのあとも残るようになりました。一覧は 1000 匹まで（オート釣りで約 3〜4 時間ぶん）で、それをこえると古い魚から消え、そのときは 1 回お知らせします。"]},{"version":"0.1.797","items":["回転ずしで、カーソルがアバターに近づいたとき（名札やメニューが出ている間）に、表のレーンを流れているお寿司がアバターの裏に隠れてしまうのを直しました。"]},{"version":"0.1.796","items":["ホームウィンドウの上の帯に「その他」「終了」「設定」を置き、ホームの「その他」（開発チーム(AI)に聞く・ショートカット・更新履歴・フィードバック）をホームウィンドウからも開けるようにしました。更新履歴はホームウィンドウの中で読めます。"]},{"version":"0.1.795","items":["釣った魚が、アプリの再起動やアップデートのあとも回転ずしの「釣った魚」の一覧に残るようにし、たくさん釣っても古い魚が消えにくくしました（12 匹まで → 200 匹まで）。それまでに消えた魚は記録が残っていないため、戻せません。"]},{"version":"0.1.794","items":["自動化に「覚えておく」のブロックを足しました。名前を付けて数を足したり引いたり、自分で書いた文字を覚えたりでき、「もし」で「覚えた数が○以上」「覚えた値が○と同じ」と分けられます（覚えた値はアプリの中だけで、閉じると忘れます）。"]},{"version":"0.1.793","items":["「全員をもぐもぐ化」が有効な間に通話へ入ってきた人も、自動でもぐもぐ化されるようにしました（「もぐもぐ化を全部解除」でその人も元に戻ります）。"]},{"version":"0.1.792","items":["自動化に「もし」のブロックを足しました。自分のマイク・離席・画面共有、同じ部屋の人数やだれかのマイク・画面共有、時刻を見て、「はい」と「いいえ」のどちらかへ進めるようにしました。"]},{"version":"0.1.791","items":["画面共有のコマ数が低いときに、送る・受け取る・画面に出すのどこで落ちているかを調査用ログで確かめられるようにしました。原因の直しはこれからです。","画面共有の映像が実際に画面に出た回数を調査用ログに残すようにしました（見た目は変わりません）。","画面共有の FPS の「自動」に、今の画質での毎秒のコマ数を「自動（15）」のように出すようにしました。説明には、動きの多い画面は 30 がなめらかなことと、その分だけ通信が増えることを足しました。","画面共有のお絵描きで、離して置いた吹き出しどうしが重ならず別々に出るように直し、吹き出しのボタンをとなりのペンと同じ線のアイコンにしました。"]},{"version":"0.1.790","items":["ほかの人の画面共有を見ている窓があるとき、アップデートの手紙やゲームの招待を届けに来るふみくまが、その窓に重ならない場所に来て、窓の上を横切らずに歩くようにしました（窓が画面いっぱいで離れた場所がないときは、重なりのいちばん少ない、いつもの場所に来ます）。"]},{"version":"0.1.789","items":["ゲームに誘われると、星形サングラスとアロハシャツのふみくまが、招待を届けに来るようにしました（招待はいつもどおりすぐに出て、答えられる時間も変わりません。画面共有中と入力中は来ず、設定の「全体」でオフにできます）。","ゲームの招待を届けるアロハのくまが、画面共有中にも来るようにしました（入力中は今までどおり来ません）。"]},{"version":"0.1.788","items":["よくある質問に、ふみくまを出さないようにする方法・いつ来るか・ふみくまの生態（アプリのなかのお話）を足しました。"]},{"version":"0.1.787","items":["自動化に「くり返し」のブロックを足しました。中身につないだやることを 1〜10 回くり返してから、次へ進みます（入れ子にもできます）。"]},{"version":"0.1.786","items":["画面共有のフレームレートが低いときの原因を調べやすいよう、見ている側の記録を増やしました（画面の見た目は変わりません）。"]},{"version":"0.1.785","items":["自分の画面を共有している間も、郵便屋さんのくま「ふみくま」がアップデートの手紙を届けに来るようにしました（入力中は今までどおり来ません。共有の映像に映ることがあります）。"]},{"version":"0.1.784","items":["画面共有のフレームレートが低いときの原因を調べやすいよう、送る側の記録を増やしました（画面の見た目は変わりません）。"]},{"version":"0.1.783","items":["ゲームに誘われると、星形サングラスとアロハシャツのふみくまが、招待を届けに来るようにしました（招待はいつもどおりすぐに出て、答えられる時間も変わりません。画面共有中と入力中は来ず、設定の「全体」でオフにできます）。"]},{"version":"0.1.782","items":["自動化に「待つ」ブロック（1 秒〜10 分）を足し、回数の制限があるやることに「制限で出せなかったら」の出口を付けました。待つを通して、制限で出せなかったやることをもう一度やれます。"]},{"version":"0.1.781","items":["オート猫じゃらしの最中に、ときどき猫がアバターの頭の上に乗って、うとうと・顔を洗う・ふみふみのどれかをするようにしました（同じ部屋の人の画面にも出ます）。"]},{"version":"0.1.780","items":["UFO の演出の UFO をふみくまと同じドット調の立体にし、UFO の上に小さなふみくまの人形が座るようにしました。"]},{"version":"0.1.779","items":["にぎり屋さんを開くと、大将が朝・昼・夕方・夜・深夜に合ったひとことを吹き出しでしゃべるようにしました（20 分以内に開き直したときはしゃべりません）。"]},{"version":"0.1.778","items":["かざりの口に「吹き戻し」を追加し、ショップで 30 コインで買えるようにしました（しゃべっている間はなめらかに伸び、しゃべるのをやめるとくるくると丸まって縮みます。ほかの人の画面でも同じように動きます）。"]},{"version":"0.1.777","items":["自動化の画面に「見せる」スイッチを付けました。オンにしている間だけ、同じ部屋の人が自動化の画面のタブからあなたのボードを見られます（見るだけで、変えたり写したりはできません。起動し直すとオフに戻ります）。"]},{"version":"0.1.776","items":["ドリンクを飲み切ったときの音を、より本物らしい「ぷはっ」にし、飲んだ人の顔の横に「ぷはっ」の文字も出るようにしました（部屋のみんなに見えます）。"]},{"version":"0.1.775","items":["ほかの人から贈られて足元に置かれるドリンクを、一回り大きく表示するようにしました（クリックで飲める範囲も同じだけ広がります）。"]},{"version":"0.1.774","items":["ドリンクを一口飲むたびに、飲んだ人のアバターの横に「ゴクッ」の文字が出るようにしました（部屋のみんなに見えます）。"]},{"version":"0.1.773","items":["ホームの上の帯の「ホームウィンドウを開く」ボタンを外し、前の並びに戻しました（「その他」からは今までどおり開けます）。"]},{"version":"0.1.772","items":["自動化の通知を長めに出すようにしました。自分にだけ見えるアバターの上の通知は 9 秒間ピンクで光って目立ち、「自分の画面にお知らせ」は 12 秒（マウスを載せている間は消えません）にベルとピンクの帯を付けました。みんなに見える通知は見た目はそのままで、5 秒出るようにしました。"]},{"version":"0.1.771","items":["ホームの上の帯（終了・設定の並び）に「ホームウィンドウを開く」ボタンを出し、どのタブからでも 1 回で開けるようにしました。"]},{"version":"0.1.770","items":["自動化のブロックを増やしました。きっかけに「だれかが部屋に出入りしたとき」「だれかのマイク・画面共有が変わったとき」「チャットにだれかが書いたとき」「自分のマイク・離席が変わったとき」、やることに「自分の画面にお知らせ」「音を鳴らす」「マイクをミュート」「画面共有を止める」「離席にする／戻る」「ステータスの絵文字を変える」を足し、最初から選べるようにしました。"]},{"version":"0.1.769","items":["自動化の画面を、ブロックを自由に置いて線でつなぐノード式にし、1 つのきっかけから複数のやることへつないだり、やることを順につないだりできるようにしました（いまのルールはそのまま開けて動きます）。"]},{"version":"0.1.768","items":["更新を届けに来るふみくまが、画面の奥から小さく現れてこちらへ歩いて来るようにし、手紙を渡したあとは後ろを向いて、後ろ姿のまま奥へ小さくなって去るようにしました。"]},{"version":"0.1.767","items":["「プロフィールを公開する」をオンにすると、友達リンクをログインしていない人が開いても、アイコンと表示名のカードが見られるようにしました（初めはオフです）。"]},{"version":"0.1.766","items":["郵便屋さんのくま「ふみくま」を、ベージュの立体的なくまをドット絵のように粗く表示した見た目にしました（青緑の帽子と上着、からし色の縁、縫い目、足のつぎはぎはそのままで、歩くときは横を向きます）。"]},{"version":"0.1.765","items":["ホームの「その他」から「クリック貫通」をなくしました（ドックのボタン、Ctrl+Alt+L、タスクバーのアイコン、設定のスライダーからは今までどおり使えます）。"]},{"version":"0.1.764","items":["ブラウザ版・スマホ版で画面共有を見ているとき、上のバーのスライダーで共有の音の大きさを変えられるようにしました（iPhone・iPad はブラウザの仕組み上 音量を変えられないため、これまでどおり音のオン／オフで、オフがきちんと効くようにしました）。"]},{"version":"0.1.763","items":["（まだ画面は変わりません。公開の設定と表示は T-1075 で入ります）本人が公開をオンにした人のアイコンと表示名を、ログインなしで読める入口を足しました。"]},{"version":"0.1.762","items":["郵便屋さんのくま「ふみくま」が、1 対 1 の通話中やサーバーにほかの人がいるときにも、ふだんと同じ演出で手紙を届けに来るようにしました（画面共有中と入力中は今までどおり来ません）。"]},{"version":"0.1.761","items":["マイクの音が相手に届かない不具合を調べやすくするため、マイクの入力の大きさをログに残すようにしました。画面や動きは変わりません。"]},{"version":"0.1.760","items":["「更新履歴」を設定から外し、ホームやドックのボタンから押すと、設定を開かずにホームの中でそのまま見られるようにしました（検索もそのまま使えます）。"]},{"version":"0.1.759","items":["アップデートのあと自動で通話に入り直したときは、自分の画面でも同じ通話のほかの人の画面でも、入場音と「入ってきました」の演出が出ないようにしました（ほかの人が古い版のときは今までどおり鳴ります）。"]},{"version":"0.1.758","items":["アップデートが見つかると、郵便屋さんの格好をしたピンクのくま「ふみくま」がデスクトップに歩いて来て、カバンから手紙を取り出して開き、そこからいつものアップデートのお知らせが出るようにしました（設定の「全体」でオフにできます）。"]},{"version":"0.1.757","items":["スマホ版・ブラウザ版の通話で参加者のアイコンをタップすると「なでる」を選べるようにしました（ほかの人のアプリ版の画面にはアプリ版と同じアニメーションが出て、なでた本人の画面では相手のアイコンの上で手のマークが数秒なでるように動きます）"]},{"version":"0.1.756","items":["フォトブースで撮った写真にスタンプを貼って飾り、そのままアイコンにできるようにしました。追加のスタンプ（3 セット）はショップでコインで買えます。"]},{"version":"0.1.755","items":["自分の友達リンクをアプリからコピーできるようにしました。リンクを渡された人は、開いてログインすると、相手のアイコンと名前を確かめて友達申請を送れます。","おたのしみに「自動化」を追加しました。時刻・回転ずしを食べたとき・魚が釣れたとき・ゴールデン酢飯をきっかけに、アバターの上の通知（自分だけ／みんな）や回転ずしを流すことを自動でできるようにしました。"]},{"version":"0.1.754","items":["自分の友達リンクをアプリからコピーできるようにしました。リンクを開いてログインすると、相手のアイコンと名前を確かめて友達申請を送れます。"]},{"version":"0.1.753","items":["ブラウザで見ている X や YouTube の動画が、再生中の曲として表示されないようにしました。"]},{"version":"0.1.752","items":["iPhone のホーム画面から開いたスマホ版で、下のタブの下の余白が二重についていたのを直しました。"]},{"version":"0.1.751","items":["ダークテーマなどで「開発チームに聞く」の入力欄に打った文字が薄くて読めなかったのを直しました（YouTube の URL 欄も同様）。"]},{"version":"0.1.750","items":["使わなくなった内部の部品を整理しました（画面の変化はありません）。"]},{"version":"0.1.749","items":["ブラウザやスマホから入った人など、アバターが出ない人を、四角い枠ではなく、アカウントのアイコンを丸いリングで囲んだシンプルな表示にしました（アイコン未設定の人は頭文字の丸、話すとリングが光ります）。"]},{"version":"0.1.748","items":["通話に入っていないときも、なかまの「参加しているサーバー」に、あとからそのサーバーに入った人が出るように直しました。"]},{"version":"0.1.747","items":["（チーム内の仕組み。お客様から見た変化はありません）開発リーダーが、チームの仕組みの自己確認（selftest）を決まった形で動かせるようにしました。"]},{"version":"0.1.746","items":["【オーナー作業待ち: まだ効きません。公開ページへのコピーが済むまで、お客様には届きません】公開の「チームの様子」ページで、完了の欄を最初は閉じておき、見出しのクリックで開けるようにしました。"]},{"version":"0.1.745","items":["（まだ画面は変わりません。友達リンクの画面は T-1057 で入ります）友達リンクを作る・読む・相手を調べる部品を足しました。"]},{"version":"0.1.744","items":["【原因は未確定で、実機では未確認です。「直った」とは言わないでください】選んだマイクを開けないときは既定のマイクに切り替わるようにし、開けなかった理由がログに残るようにしました。"]},{"version":"0.1.743","items":["にぎり屋さんの Lua スクリプト（見本・スクリプトの道具・notify() を含む）と、論理回路の「にぎり入力」「にぎり出力」「通知」の部品をなくしました。スクリプトの道具を買っていた方には、その代金の貫をお返ししました（ゴールデン酢飯のお知らせと、論理回路のほかの部品はそのままです）。"]},{"version":"0.1.742","items":["Web 版のチャット入力欄でも Enter（または設定で選んだ Ctrl+Enter）で送信できるようにし、送信するキーを設定で選べるようにしました（日本語の変換を確定する Enter では送信しません）。"]},{"version":"0.1.741","items":["（チーム内の仕組み。アプリの変化はありません）協力者の方の contribute 用スクリプトの更新（PR #810）を取り入れました。"]},{"version":"0.1.740","items":["フォトブースの「アバターの位置」で、アバターを椅子の上で左右・上下・奥行き（奥へ／手前へ）にスライダーで動かし、その姿で撮れるようにしました（寄る・引く・ずらすでは、垂れ幕と椅子もいっしょに写り方が変わります）。"]},{"version":"0.1.739","items":["「わらう」のエモートのとき、アバターの顔も笑顔になるようにしました。"]},{"version":"0.1.738","items":["画像・動画を普通のウィンドウで開けるようにし、チャットの別ウィンドウでサーバーの管理もできるようにしました。"]},{"version":"0.1.737","items":["ドックと重なる位置にいる人のポップアップが、ドックの後ろに隠れないようにしました。"]},{"version":"0.1.736","items":["画面共有や論理回路のお絵描きで、吹き出しの入力欄が開いた直後に閉じてしまうことがないようにしました。"]},{"version":"0.1.735","items":["スマホ版の通話で、前面カメラで読み取った顔の動きに合わせて自分の VRM アバターを動かし、相手に見せられるようにしました（設定の「アバター」でオン・オフでき、カメラの映像そのものは送りません）。"]},{"version":"0.1.734","items":["画面共有のお絵描きに「吹き出し」ボタンを足しました。押してから画面をクリックして 1 行書いて送ると、その場所に見ている人みんなの画面で吹き出しが出ます。","画面の上のお絵描きのペンに「なめらか」のチェックボックスを足しました。オンにして描いた線は、みんなの画面でもなめらかな曲線で出ます（既定はオフで、いまの見た目のままです）。","画面共有のお絵描きに「吹き出し」ボタンと、ペンの「なめらか」チェックボックスを足しました。"]},{"version":"0.1.733","items":["通話中のサーバーに誰かが新しく入ってきたとき、その人のアバターがふわっと現れ、「入ってきました」の短い表示が数秒出るようにしました（設定でオフにもできます）。"]},{"version":"0.1.732","items":["スマホ版やブラウザから通話に入っている人の名札に、小さな印（📱 スマホ／🌐 ブラウザ）が出るようにしました。","通話中のサーバーに誰かが新しく入ってきたとき、その人のアバターがふわっと現れ、「入ってきました」の短い表示が数秒出るようにしました（設定でオフにもできます）。"]},{"version":"0.1.731","items":["スマホ版やブラウザから通話に入っている人の名札に、小さな印（📱／🌐）が出るようにしました。"]},{"version":"0.1.730","items":["フォトブースで撮る前に、表情（笑顔など）とポーズ（ピース・手をふる など）を選び、「細かく調整」で顔の向き・首のかしげ・あご・手の高さや左右を少し変えて、その姿で撮れるようにしました。"]},{"version":"0.1.729","items":["スマホ版（ホーム画面に追加した Web 版）で、ピンチや入力欄のタップで画面が拡大しなくなり、ヘッダーと下のタブが上下に固定されたままになりました（画面共有を見る画面だけは今までどおりピンチで拡大できます）。"]},{"version":"0.1.728","items":["フォトブースの垂れ幕に「とうめい」を選べるようにしました。撮ったアイコンはアバターだけで背景が透明になり、ブースの中の窓もデスクトップが透けて見えます。"]},{"version":"0.1.727","items":["ほかの人のアバターの扇形メニューが、出てすぐ消えてしまうことがあったのを直しました。"]},{"version":"0.1.726","items":["ステータスに「読書中」（📖）を追加しました。選ぶと背景がビーチ（パラソルとビーチチェア）になり、アバターがサングラスをかけて片手で本を持ち、ときどきもう片方の手でページをめくります。"]},{"version":"0.1.725","items":["画面共有をタブで見ているとき、ほかのタブに切り替えても、開いているほかの人の画面共有の音が鳴り続けるように直しました。"]},{"version":"0.1.724","items":["フォトブースの窓を看板や枠をつかんでドラッグで好きな位置に動かせるようにし、撮る前にホイールやボタン（寄る・引く）とドラッグで、写す範囲を寄せたり引いたりずらしたりできるようにしました。"]},{"version":"0.1.723","items":["（画面の T-1039 と合わせて T-1028・T-1029 で書く。これは仕組みだけで、見た目は変わらない）"]},{"version":"0.1.722","items":["（T-1024 の仕組みだけ。画面の T-1035 が入るまで見た目は変わらない。報告は親の T-1024 でまとめる）"]},{"version":"0.1.721","items":["にぎり屋さんの Lua スクリプトから notify(文, \\"みんな\\") で、論理回路の「通知」と同じようにアバターの上に文を出せるようにしました（省くと自分だけ。40 文字まで、みんなへは 5 秒に 1 回まで）。"]},{"version":"0.1.720","items":["（仕組みだけ。見た目は変わらない）スマホ版・ブラウザ版から入った人が、接続元の種類を通話のほかの人へ知らせるようにした。印の表示は画面の T-1033 で出す。"]},{"version":"0.1.719","items":["UnityPackage のアバターが、しばらくすると真っ黒なシルエットのまま戻らなくなることがある不具合を直しました（グラフィックが一度リセットされても、アバターの模様が消えないようにし、それでも黒くなったら自動で読み直します）。"]},{"version":"0.1.718","items":["ホイールで奥行きを変えている間は並びが動かなくなり、止めて約 3 秒たってから詰めるようにしました。ほかの人のアバターの上でホイールを回すだけ（Ctrl なし）で、その人と一緒に奥行きを動かせるようにしました。"]},{"version":"0.1.717","items":["フレンドが自分の入っていないサーバーにいるとき、フレンド一覧に「ほかのサーバーにいます」と出て、「招待をお願いする」ボタンで相手に DM でお願いできるようにしました。お願いを受け取った人は、DM の「今いるサーバーに招待する」ボタンで招待を送れます（サーバー名は相手に見えません）。","親の T-1011 でまとめて報告します（フレンドのいる別サーバーへの「招待をお願いする」ボタンと、届いたお願いからの招待ボタン）。"]},{"version":"0.1.716","items":["フォトブースに入ると、自分の場所の奥に小さなフォトブースが出て、アバターが歩いて入り垂れ幕が下りる様子（出るときはその逆）を部屋のみんなが見られるようにし、中の様子は自分の画面だけに、設定画面のアバター表示と同じ位置・大きさで出るようにしました。"]},{"version":"0.1.715","items":["「じぶん」の「📸 フォトブースでアイコンを撮る」から、垂れ幕の中のアバターを 3・2・1 で撮って、プレビューで確かめてそのままアカウントのアイコンにできるようにしました（入るとき・出るときは垂れ幕が上がってアバターが出入りします）。","「じぶん」の「📸 フォトブースでアイコンを撮る」から、アバターの写真を撮ってそのままアカウントのアイコンにできるようにしました。入るときは外から見たブースの垂れ幕が上がってアバターが入り、椅子に座って垂れ幕が下り、カメラがブースの中へズームインします。中ではアバターが撮影機のカメラのほうを向き、3・2・1 で撮ってプレビューで確かめられます。出るときはその逆です。","アバター（VRM・UnityPackage）のテクスチャが白や黒になったり、模様が別の場所に貼られたりする不具合を直しました。","UnityPackage から読み込んだアバターで、テクスチャ（模様）が上下逆やずれた場所に貼られて表示が崩れていたのを直しました（自分のアバターも、ほかの人の画面での見え方も）。","画面共有の「カメラ・キャプチャー」でキャプチャーボードの映像が縦長に潰れて見えることがあったのを、本来の縦横比（16:9 など）で映るように直しました。","（T-1011 の一部。画面は T-1013 で入る）フレンドに「今いるサーバーに招待してほしい」とお願いを DM で送る仕組みを入れました。","同じサーバーにいるほかの人が入り直したときなどに、その人とつながらないまま（止まる・見えない・読み込まれない）になることがあったのを直しました。","にぎり屋さんの「仕込み」を 7 段増やし、1 クリックでにぎれる量を最大 4.5 億貫（大将の好感度が最大のとき）まで伸ばせるようにしました。"]},{"version":"0.1.714","items":["奥行きが遠くて小さく表示される人の分だけ、横の並びの間隔を詰めるようにしました。","奥行きが遠い人ほど、その人の映像（カメラ・アバター）を低い画質・少ないフレームレートで受け取るようにし、通話の負荷を下げました。"]},{"version":"0.1.713","items":["「じぶん」の「📸 フォトブースでアイコンを撮る」から、垂れ幕の中のアバターを 3・2・1 で撮って、プレビューで確かめてそのままアカウントのアイコンにできるようにしました（入るとき・出るときは垂れ幕が上がってアバターが出入りします）。"]},{"version":"0.1.712","items":["論理回路に「通知」部品を足しました。信号が入ると自分のアバターの上に好きな文を出せます（自分だけ／部屋のみんなを選べ、{貫}・{毎秒}・{名前} で貫の数などを文に入れられます。みんなへは 5 秒に 1 回・40 文字まで）。"]},{"version":"0.1.711","items":["かざりに頭（リボン・ベレー帽・天使の輪）・目（スターメガネ・片メガネ・眼帯）・口（バラ・きば・風船ガム）の 9 種類を追加し、お楽しみの「ショップ」で 1 つ 30 コインで買えるようにしました（買ったものはショップか設定の「かざり」で付け外しでき、今までのかざりは無料のままです）。"]},{"version":"0.1.710","items":["レア Boop の演出中にもう一度 boop されても、レア演出が途中で終わらず最後まで再生されるようにしました。"]},{"version":"0.1.709","items":["入場音の音量の初期値を 10% にしました（100% のままだった方も 10% になります。自分で変えた音量はそのままです）。"]},{"version":"0.1.708","items":["登録したあとでも、ユーザー名（ログインやフレンド検索に使う ID）を「じぶん」のアカウント欄（スマホ版は設定の「アカウント」）から変えられるようにしました（7 日に 1 回まで）。","親の T-997 でまとめて報告します。"]},{"version":"0.1.707","items":["人数が多いときのほかの人のアバターの扇形メニューを、少し下（アバターの頭のあたり）に出すようにしました。"]},{"version":"0.1.706","items":["画面が開かない版に当たっても、アプリが起動から 2 分たって画面が出ていなければ自動で新しい版を探して入れ直すようにしました。タスクトレイのメニューにも「アップデートを確認して入れる」を足しました。"]},{"version":"0.1.705","items":["途中からサーバーに来たときに、直近の会話を AI が数行にまとめて見せるようにしました。","concrnt のアカウントでログイン・新規登録できるようにしました（今のアカウントに concrnt を紐づけることもできます）。","0.1.700 にアップデートしたあとウィンドウが何も触れなくなった件は、0.1.701 以降で直りました。0.1.700 のままの方は、最新版を入れ直してください。","0.1.700 で起動すると「asset not found: index.html」と出て動かなかった件は、0.1.701 以降で直りました。0.1.700 のままの方は、配布ページから最新版を入れ直してください。"]},{"version":"0.1.704","items":["メールアドレスを登録しておくと、パスワードを忘れてもメールに届く確認コードで設定し直せるようになりました（登録済みの方も「じぶん」のアカウント欄から後で登録できます）。"]},{"version":"0.1.703","items":["（T-997 の内部の準備。画面の T-999 と一緒に更新履歴に載せるので、これ単体では載せない）ユーザー名を変える仕組み（Edge Function change-username と CloudClient.changeUsername）を足しました。まだ画面からは呼ばれません。"]},{"version":"0.1.702","items":["チャットの別ウィンドウを「ホームウィンドウ」にしました。左のサーバーの列から入る・作る・招待コードで参加・届いた招待に答える、上の帯から招待コードや参加用 URL のコピー・ぬける・退出ができます（狭くするとチャットだけの見た目になります）。","設定の「顔」に「口の動き（顔だけ／顔＋声／声だけ）」と「声での口の開き」を足し、フェイシャルトラッキング中でもマイクの声でしっかり口が動くようにできるようにしました","論理回路に「にぎり入力」「にぎり出力」の部品を足し、回路からにぎり屋さんでにぎる・お手伝いや仕込み・腕みがきを買う・貫の数やゴールデン酢飯、買えるかどうかを見ることができるようにしました（Lua と同じ「スクリプトの道具」を買うと使えます）。","「映画を見ている」ステータスのあいだ、アバターがときどき（30〜65 秒ごと）ポップコーンをつまんで口に運び、もぐもぐ食べるようにしました。","入場音に自分の .wav を使うとき、最初の 12 秒まで鳴らせるようにしました（前に読み込んだ音は選び直すと 12 秒になります）。長い入場音が気になる方向けに、設定の「音・SE」に「ほかの人の入場音は最初の 3 秒だけ鳴らす」を追加しました。","（内部の改善）画面が組み込まれていない版を誤って公開しないよう、リリースの前に確かめるようにしました。"]},{"version":"0.1.701","items":["変わりません（チームの内部の仕組み）。データベースへ「表を足すだけ」の変更を、リリース担当が安全に適用できるスクリプトを足しました。"]},{"version":"0.1.700","items":["人数が多いとき、ほかの人のアバターの扇形メニューが、アバターの大きさにかかわらず全員同じ高さ（アバターの並びのすぐ上）に出るようにしました。","【まだ見た目は変わりません】チャットの別ウィンドウを「ホームウィンドウ」に育てる土台として、ウィンドウの題名を「DesktopChat Neo - ホーム」に、既定の大きさを 900×620 にしました（サーバーの一覧・招待・入る／ぬける等の操作は、続く画面のチケット T-987 で使えるようになります）。"]},{"version":"0.1.699","items":["自分のアバターの上で Ctrl+ホイールを回すと自分だけ、ほかの人のアバターの上で回すとその人と一緒に、奥行きを動けるようにしました。","奥行きを +16 まで深くし、いちばん奥まで行くと、手前にいる人の声がまったく聞こえなくなるくらい離れられるようにしました。","奥行きを動かしている間、手前から奥までの目盛りにみんなのアイコンを並べて出し、自分が今どのあたりにいるかが分かるようにしました（動かし終わると消えます）。"]},{"version":"0.1.698","items":["にぎり屋さんのスクリプト（Lua）欄の下に「スクリプトの道具」を置き、貫の数や値段を調べる関数と、お手伝いを雇う・仕込みや腕みがきを買う関数を、貫で買ってスクリプトから使えるようにしました（買っていない関数を呼ぶと、何を買えばよいかを知らせて止まります）。"]},{"version":"0.1.697","items":["にぎり屋さんのスクリプト（Lua）欄に、選ぶだけで使えるスクリプトの見本を 5 種類（ずっとにぎる・決まった回数だけ・間をあけてにぎる など）並べました。"]},{"version":"0.1.696","items":["入場音を選んでいると、自分が通話に入ったときに自分の画面でもその入場音が鳴るようにしました。設定の「音・SE」で入場音の音量を変えられるようにしました（ほかの人の入場音と自分の入場音の両方に効きます）。"]},{"version":"0.1.695","items":["画像や動画を開いたときのビューアが、タイトルバーつきの普通のウィンドウになり、大きさを変えたり、タスクバーから切り替えたりできるようになりました。位置と大きさも覚えます。","画像や動画を開くビューアを、タイトルバーつきの普通のウィンドウにしました。大きさを自由に変えられ、タスクバーにも出て、前回の位置と大きさで開きます（外側をクリックしても閉じなくなり、閉じるのはウィンドウの × か Esc です）。"]},{"version":"0.1.694","items":["だれかが 🔊 で特定の人に声を大きく届けている間、届け先に入っていない人にはその声が小さめ（聞こえるけれど控えめ）に聞こえるようにしました。"]},{"version":"0.1.693","items":["離席から戻ったときやスリープから戻ったときなどに、アプリが落ちることがある不具合（0xC0000005）の原因と思われる所を直しました。","にぎり屋さんに、Lua のスクリプトを書いて自動でにぎれる欄を足しました（clickNigiri() と for / while などの基本の書き方が使えます）。","チャットとDMで、自分の発言を直せるようにしました（直すと「（修正済み）」の印が付きます）。"]},{"version":"0.1.692","items":["自分がアップデートで再起動して部屋に戻ったあとも、まだ再起動中のほかの人の「アップデート中 ○秒」の表示が出続けるようにしました。","離席から戻ったときやスリープから戻ったときなどに、アプリが落ちることがある不具合（0xC0000005）の原因と思われる所を直しました。","にぎり屋さんに、Lua のスクリプトを書いて自動でにぎれる欄を足しました（clickNigiri() と for / while などの基本の書き方が使えます）。"]},{"version":"0.1.691","items":["通話中などにアプリが突然落ちる不具合の原因になりうる所（裏で常に動いているウィンドウの見張り処理）を安全な形に直しました。万一また落ちたときに、原因を突き止めやすい記録を残すようにしました。","パソコンのメモリが少ないときなどに通話中のアプリが落ちることがある不具合の原因になりうる所を直しました。","裏で動いているウィンドウの見張り処理を、落ちにくい安全な形に直しました。","アプリが落ちたときに、原因を調べやすい記録を残すようにしました。","スマホ版を閉じていても DM の通知が届くように、スマホ側の受け取りの準備を入れました（サーバー側の準備が済むまでは効きません）。"]},{"version":"0.1.690","items":["（まだ見た目は変わりません。自分の発言を直すための下準備で、画面は T-974 で付けます。報告は親 T-439 でまとめます）","【オーナー作業待ち: まだ効きません（マイグレーションの適用・VAPID のシークレット登録・dm-push のデプロイの後に効きます）】スマホ版を閉じていても DM の通知を送るためのサーバー側の準備を入れました（報告は親 T-964 でまとめます）。","（見た目は変わりません。通話中のメモリの多さを調べるため、診断ログにメモリの内訳を残すようにしました。報告は親 T-949 でまとめます）","通話中などにアプリが突然落ちる不具合の原因になりうる所（裏で常に動いているウィンドウの見張り処理）を安全な形に直しました。万一また落ちたときに、原因を突き止めやすい記録を残すようにしました。","パソコンのメモリが少ないときなどに通話中のアプリが落ちることがある不具合の原因になりうる所を直しました。","裏で動いているウィンドウの見張り処理を、落ちにくい安全な形に直しました。","アプリが落ちたときに、原因を調べやすい記録を残すようにしました。","スマホ版を閉じていても DM の通知が届くように、スマホ側の受け取りの準備を入れました（サーバー側の準備が済むまでは効きません）。"]},{"version":"0.1.689","items":["（調べるための記録の追加で、見た目は変わりません）アプリの記録に、パソコンのメモリの量とアプリ自身（中の表示部分も含む）が使っているメモリの量を残すようにしました。メモリを使いすぎる件の原因を調べやすくなります。"]},{"version":"0.1.688","items":["（チームの仕組みの直しで、アプリの見た目や動きは変わりません）もう一人のリーダーが GitHub で進めている作業を、見張りが「担当が動いていない」と誤って止めないようにしました。"]},{"version":"0.1.687","items":["設定の「表示」に「ログの背景」を追加し、チャット欄の文字はそのままで背景だけを透かせるようにしました（「常に最前面に表示する」と合わせて、後ろの作業画面を見ながらチャットを追えます）。"]},{"version":"0.1.686","items":["画面共有を見ている人も、見ている共有画面のウィンドウのバーで、自分のほかに誰がその共有を見ているかをアイコンで見られるようにしました（見るのをやめた人のアイコンは消えます）。"]},{"version":"0.1.685","items":["（チーム内の仕組み。お客様から見た変化はありません）Edge Function のデプロイをチームでできるようにしました。"]},{"version":"0.1.684","items":["画面共有の途中でも、自分の共有ウィンドウのバーから線が消えるまでの時間（10〜120 秒・無制限）を変えられるようにしました。見ている人が描く線にもすぐ効きます。"]},{"version":"0.1.683","items":["毎日の Wordle の問題が、日本時間の朝 5 時に新しくなるようにしました（これまでは 0 時）。"]},{"version":"0.1.682","items":["画面共有中、自分の共有を見ている人のアイコンが共有カードと共有画面のウィンドウに並ぶようにしました（見るのをやめると消えます）。"]},{"version":"0.1.681","items":["毎日の Wordle で、挑戦中のみんなの盤面（色だけ）を並べて同時に見られるようにしました（「部屋のみんな」の「並べて大きく見る」や、1 人の盤面を見ているときの「みんなの盤面を並べて見る」から開けます）。"]},{"version":"0.1.680","items":["戦闘モードに参加していないときは、なでられても 🛡（なでるをブロック）が出ず、そのままなでられるようにしました（戦闘中は今までどおり 🛡 で防げます）。"]},{"version":"0.1.679","items":["ほかの人のプロフィールカードがドックと重なる位置に出ても、ドックの後ろに隠れず手前に出るように直しました。"]},{"version":"0.1.678","items":["設定の「音・SE」で自分の入場音を選べるようにしました。あとから通話に入ったとき、ほかの人の画面でその音が鳴ります（「ほかの人が選んだ入場音を鳴らす」をオフにすると、いつもの参加音になります）。"]},{"version":"0.1.677","items":["設定を閉じたときに、アバターのプレビュー用の描画（WebGL）を手放すようにし、設定を何度も開け閉めしてもメモリが増えていかないようにしました。"]},{"version":"0.1.676","items":["【オーナー作業待ち: まだ効きません。ask-help の関数のデプロイと ANTHROPIC_API_KEY の登録が済むと使えます】「開発チーム(AI)に聞く」で、アプリの使い方を自由に質問すると、よくある質問と更新履歴をもとに AI がすぐ答えるようにしました（1 人 1 日 20 回まで）。","「開発チーム(AI)に聞く」のパネルで、自由に質問を入力して AI の答えを見られるようにしました（今日の残り回数も出ます）。"]},{"version":"0.1.675","items":["読み込んだアバター（VRM）の画像を 1 辺 1024px までに縮めるようにして、通話中のメモリの使用量を減らしました。"]},{"version":"0.1.674","items":["にぎり屋さんの「酢飯小僧」をなくし、寿司が持っていかれることがなくなりました（ゴールデン酢飯はそのままです）。小僧よけの「お店の守り」は売るのをやめ、すでに買っていた人には代金の貫をお返ししました。"]},{"version":"0.1.673","items":["「手をキーボードとマウスに固定」中、何も触っていないのにキーボード側の指（特に指の短いアバターの小指）が小刻みに動き続けることがあったのを直しました。"]},{"version":"0.1.672","items":["フレンドと 2 人で通話したいときの方法がわかりやすくなりました（「開発チーム(AI)に聞く」のよくある質問に「フレンドと通話するには？」を足し、フレンドの電話のボタンに「2 人で通話」と出るようにしました）。"]},{"version":"0.1.671","items":["【オーナー作業待ち: まだ効きません（関数 ask-help のデプロイと ANTHROPIC_API_KEY の設定が要ります）】「開発チーム(AI)に聞く」で、アプリの使い方を AI に自由に質問できるようにするための土台を入れました（画面は T-947 で付けます）。"]},{"version":"0.1.670","items":["スマホ版（PWA）を開いている・裏に回している間に DM が届くと、スマホの通知に出るようにしました。設定の「通知」欄でオン／オフできます（iPhone はホーム画面に追加したときに使えます。アプリを閉じているときの通知はこれから作ります）。"]},{"version":"0.1.669","items":["スマホ版の設定に「通知」の欄を足し、DM が届いたときの通知をオン／オフできるようにしました（iPhone はホーム画面に追加したときに使えます）。"]},{"version":"0.1.668","items":["おたのしみの「記録」から「回数を 0 に戻す」ボタンをなくし、回数がうっかり消えないようにしました。"]},{"version":"0.1.667","items":["チャット欄の「蝶のしおり」（しおりのボタン・飛ぶ蝶・一覧のしおり）を取り除きました。"]},{"version":"0.1.666","items":["フィードバックを送ったときの紙飛行機の演出が、サーバーに入っているときだけ出るようにしました（送信は今までどおりどこからでもできます）。"]},{"version":"0.1.665","items":["（T-847 の一部。親でまとめて報告します）スマホ版で、画面に出ていない間に届いた DM をスマホの通知に出す仕組みを入れました（設定のスイッチは T-945 で付けるまでオフのまま）。"]},{"version":"0.1.664","items":["ほかの人のアバターにカーソルを合わせたときの扇形メニューが、自分のアバターのメニューと同じように待たずに出るようにしました。"]},{"version":"0.1.663","items":["アバターの扇形メニューの分岐（攻撃の種類・スタンプ・あそぶ）が名前タグ（プロフィールのボタン）と重なっても、分岐が手前に出て押せるようにしました。"]},{"version":"0.1.662","items":["映像（カメラ）オフの人が話しているとき、「映像オフ」の文字が点滅せず、その人の枠がやわらかく明滅するようにしました（動きを減らす・演出を控えめのときは明滅せず点いたまま）"]},{"version":"0.1.661","items":["声を届けている相手に残る 🔊 の印を緑のフチの見た目にそろえ、アバターにカーソルを合わせなくても、その印を押すだけで届けるのを止められるようにしました。"]},{"version":"0.1.660","items":["欄から少しだけはみ出す曲名・ゲーム名が … で止まったままになることがあったのを直し、はみ出すタイトルはどれも流れるようにしました。"]},{"version":"0.1.659","items":["ほかの人のアバターの扇形メニューから「同じ奥行きに並ぶ」「連れてくる」「声を届ける」を外して右下の小さいボタンだけにし、小さいボタンを横一列に並べ、声を届けている相手の 🔊 の印もその 🔊 と同じ場所に残るようにしました。","ドックの「声を届ける」ボタンをなくし、声を届けるのはアバターの 🔊 だけにしました。🔊 で選んだ相手がいる間だけ届き、🔊 が光っているのに届かないことがなくなりました。"]},{"version":"0.1.658","items":["ほかの人のアバターの扇形メニューから「同じ奥行きに並ぶ」「連れてくる」「声を届ける」を外して右下の小さいボタンだけにし、小さいボタンを横一列に並べ、声を届けている相手の 🔊 の印もその 🔊 と同じ場所に残るようにしました。"]},{"version":"0.1.657","items":["はみ出す曲名・ゲーム名が、端で止まって戻るのではなく、少し間を空けて同じ文字が続く途切れないループで左へ流れるようにし（端はやわらかくぼかします）、ゲームの表示の 🎮 を曲の ♪ とそろうシンプルな単色の印にしました。"]},{"version":"0.1.656","items":["アバターの扇形メニューに「戦闘に参加する」（⚔️）が出ないようにしました（参加は左のメニューの ⚔️ やおたのしみから今までどおりできます）"]},{"version":"0.1.655","items":["設定の「大きさ・並び」に「自分のアバターの上でホイールを回して奥行きを動かす」を追加し、オフにするとホイールで奥行きが動かず、自分のアバターの上のクリックも後ろのウィンドウに届くようにしました（既定はオン）。"]},{"version":"0.1.654","items":["ドックの右クリックで出る「外したボタン」の一覧が、外をクリックしたとき・右クリックし直したとき・Esc を押したときに閉じるようにしました。"]},{"version":"0.1.653","items":["ほかの人のアバターにカーソルを重ねると、右下に「同じ奥行きに並ぶ👣」「連れてくる🧲」「声を届ける🔊」の小さいボタンが出て、すぐ押せるようにしました（声を届けている相手は 🔊 が色付きで光ります。アバターのメニューの項目もそのままです）。"]},{"version":"0.1.652","items":["自分のアバターにカーソルを合わせてマウスのホイールを回すと、奥行き（前後）を動かせるようにしました（上に回すと奥、下に回すと手前）。"]},{"version":"0.1.651","items":["曲やゲームの名前が欄に入りきらないときは、ときどき横に流れて全部読めるようにしました。ゲームの表示の「プレイ中」の文字もなくしました。"]},{"version":"0.1.650","items":["ドックの右クリックの「外したボタン」一覧を以前の形に戻し、並び順だけ「通話の操作・ホーム・おたのしみ」の順にまとめました。"]},{"version":"0.1.649","items":["ほかの人のアバターのメニューで「同じ奥行きに並ぶ」「連れてくる」「声を届ける（🔊）」を続けて並べ、「なでる」より上に出るようにしました。"]},{"version":"0.1.648","items":["ドックのボタンを長押しで並べ替えるとき、ほかのアイコンがその場で動かず、離したら入る位置を線で示すようにしました（重ねてフォルダにまとめるときは線が消えて、相手が光ります）。"]},{"version":"0.1.647","items":["今聞いている曲の表示（自分のアバターの曲のチップ、フレンドの一覧や設定の曲の表示）から「再生中」の文字を消し、♪ と曲名・アーティストだけにしました。"]},{"version":"0.1.646","items":["同じ奥行きにいても、選んだ人にだけ自分の声を大きく届けられるようにしました（アバターのメニューの 🔊 で相手を選び、マイクにマウスを乗せると出るボタンでオン／オフ。届けている相手・届けてくれている人のアバターに小さな印が出ます）。"]},{"version":"0.1.645","items":["T-921 にまとめて書きます（画面の部分）。"]},{"version":"0.1.644","items":["「オート猫じゃらし」「釣った魚を自動で流す」「記録」もドックに出せるようにし、ドックから外したボタンの一覧を「通話の操作・ホーム・おたのしみ」の分類ごとに並べました。"]},{"version":"0.1.643","items":["ドックのボタンをつかむとアイコンが浮いてカーソルについてくるようにし、ほかのボタンに重ねてフォルダになる位置では相手が光って「離すとフォルダにまとめます」と出るようにしました。開いたフォルダの中でもドラッグで並べ替えられ（順番は保存）、「フォルダを解除」は名前の横の小さな「解除」ボタンにしました。"]},{"version":"0.1.642","items":["（T-921 の仕組み。画面の子チケット T-923 と合わせて親でまとめて報告します）"]},{"version":"0.1.641","items":["concrnt の QR コードでログインするとき、送る側の画面に「サイトへの送信に失敗しました」と出てしまう不具合を直しました（サーバー側の関数を入れ直したあとに効きます）。"]},{"version":"0.1.640","items":["ドックの「開発チームに聞く」とその入力欄・よくある質問・ホームのタイルなどの表記を「開発チーム(AI)」にそろえ、入力欄には返事が少しあとに届くことを書きました。"]},{"version":"0.1.639","items":["ドックの「開発チームに聞く」を押すと、ドックの横に 1 行の入力欄と送るボタンが出て、そのまま開発チームに送れるようにしました（打った言葉に合う「よくある質問」も出ます）。"]},{"version":"0.1.638","items":["ドックに「開発チームに聞く」ボタンを置き、押すと開発チームとのメッセージが開くようにしました。あわせて、ドックのボタンは右クリックで外したり戻したりできることを、設定の「全体」とチュートリアルに書きました。","「開発チームに聞く」を押すと、まず「よくある質問」が並び、押すと答えがすぐ出るようにしました。解決しないときは、そこから開発チームへのメッセージやフィードバックに進めます。"]},{"version":"0.1.637","items":["ドックに「開発チームに聞く」ボタンを置き、押すと開発チームとのメッセージが開くようにしました。あわせて、ドックのボタンは右クリックで外したり戻したりできることを、設定の「全体」とチュートリアルに書きました。"]},{"version":"0.1.636","items":["ホームの「じぶん」を見やすく整理しました。一番上の枠にはアイコン・なまえ・フレンドコードだけを置き、ひとこと・フキダシの色・ステータス・フィールド・鳴き声の高さは、その下に「アカウント」と同じ形で見出しごとに並べました（説明は見出し右の i に）。"]},{"version":"0.1.635","items":["じぶん・なかま・ログインの画面で常に出ていた説明文を、見出しや項目名の右の i アイコンにまとめ、画面をすっきりさせました（説明は i にマウスを乗せるかクリックで読めます）。","通話の終了予約・毎日の Wordle・論理回路で常に出ていた説明文を、見出しや項目名の右の i アイコンにまとめ、画面をすっきりさせました（説明は i にマウスを乗せるかクリックで読めます）。"]},{"version":"0.1.634","items":["じぶん・なかま・ログインの画面で常に出ていた説明文を、見出しや項目名の右の i アイコンにまとめ、画面をすっきりさせました（説明は i にマウスを乗せるかクリックで読めます）。"]},{"version":"0.1.633","items":["画面共有のウィンドウにずっと出ていた説明文を、各見出しの右の i アイコンにまとめ、マウスを乗せると読めるようにしました。","設定の各項目にずっと出ていた説明文を、見出しやスイッチの右の i アイコンにまとめ、マウスを乗せると読めるようにしました。"]},{"version":"0.1.632","items":["画面共有のウィンドウにずっと出ていた説明文を、各見出しの右の i アイコンにまとめ、マウスを乗せると読めるようにしました。"]},{"version":"0.1.631","items":["回転ずしで自分が流したお寿司をほかの人が食べてくれると、しばらく（1 皿ごとに 1 分、最大 5 分）釣りが有利になるようにしました（釣れるのが早く、レアやヌシが出やすくなります。浮きのそばに「🍣ごちそう」と残り時間が出ます）。"]},{"version":"0.1.630","items":["もぐもぐモードや全員をもぐもぐ化を有効にしている間は、ドックのマイク・声を聞くの場所に有効中のアイコンを出すようにしました（押すと解除。マウスを乗せると横にマイク・声を聞くが出ます）。"]},{"version":"0.1.629","items":["「おたのしみ」のウィンドウのボタン（にぎり屋さん・論理回路・オート釣りなど）を、ドラッグしてドックの真ん中に入れられるようにしました"]},{"version":"0.1.628","items":["回転ずしが、ドック側から出てまずアバターの裏を通り（予告になります）、反対側で前に出て、前を通ってドック側へ戻るようにしました"]},{"version":"0.1.627","items":["設定の中にあった「記録」（攻撃・なでる・Boop の回数、コイン、魚の図鑑）を、おたのしみのウィンドウの「記録を見る」から見られるようにし、設定からは外しました。"]},{"version":"0.1.626","items":["回転ずしが、ドックのある側から出てきて前を流れ、反対側で裏に回り、裏を通ってドック側へ戻るようにしました（ドックが右なら右から流れます）。"]},{"version":"0.1.625","items":["設定の「全体」をドックのプリセットとアップデートまわりだけにし、ドックのボタンの出し入れは、ドックのボタンを右クリックして「ドックから外す」「外したボタン」から直接できるようにしました。"]},{"version":"0.1.624","items":["流れてくるお寿司が、まずアバターの裏を右から左へ回ってから前を左から右へ流れるようにしました。これで左端の人にも予告の時間があります。また、画面の解像度がちがっても、お寿司が全員の画面で同じ人の前に来るように直しました。"]},{"version":"0.1.623","items":["設定「全体・連携」のドックまわりを整理しました（「ドックに出すボタン」を先に置き、長かった説明を 1 つにまとめ、プリセットと「並び順を元に戻す」を下にまとめました）。"]},{"version":"0.1.622","items":["オート猫じゃらしの猫が、前足ではたく・飛びつく・立ち上がって両前足でじゃれる・ねこパンチの 4 種類の動きで遊ぶようにしました（途中で動きが変わり、ほかの人の画面でも同じ動きに見えます）。"]},{"version":"0.1.621","items":["重なって開いているウィンドウ（パネル・ホーム・おたのしみ）は、最後に開いたり触ったりしたものが一番手前に来るようにしました（おたのしみがいつも一番上に残っていたのを直しました）。"]},{"version":"0.1.620","items":["オート猫じゃらしで、マウスを動かしているほど猫が来やすくなり、ショップの「またたび」（20 コイン）を買うと次の 10 匹の猫が 3 倍早く来るようにしました。"]},{"version":"0.1.619","items":["通話の終了予約のパネルに閉じるボタン（×）を付け、予約を残したままパネルだけ閉じられるようにしました。"]},{"version":"0.1.618","items":["「自分だけ退出」の予約の残り 10 秒になると、カウントダウンに合わせて 1 秒ごとに「ピッ」と鳴り、時刻になって抜けるときに締めの音が鳴るようにしました（ほかの人の退出予約も同じように鳴ります）。"]},{"version":"0.1.617","items":["オート猫じゃらしをオンにしている人のアバターのそばに、ほかの人の画面でも猫じゃらしが出て、同じ猫が同じタイミングで遊びに来るようにしました（相手も新しい版のとき）。"]},{"version":"0.1.616","items":["ドックのヘッドホンを右クリックすると声の音量と音の出力先を、マイクを右クリックするとマイクの入力音量（感度）と使うマイクを、その場で変えられるようにしました（設定のそのタブも開けます。声の音量と入力音量は新しく設定にも入りました）。"]},{"version":"0.1.615","items":["「自分だけ退出」の予約をすると、通話のほかの人にもその人のアバターの下に「🚪 あと N 分」と残り時間が見えるようにしました（10 秒前からは目立つように点滅します）。"]},{"version":"0.1.614","items":["通話中にだれかが「自分だけ退出」を予約すると、その人のアバターの下に「🚪 あと N 分」と残り時間が出るようにしました（3 分前から色が変わり、10 秒前からは大きく点滅します）。"]},{"version":"0.1.613","items":["にぎり屋さんでゴールデン酢飯をクリックすると、アバターの上に「ゴールデン酢飯を握りました！」が出て、同じ通話のみんなの画面にも見えるようにしました。"]},{"version":"0.1.612","items":["おたのしみに「オート猫じゃらし」を追加しました。オンにすると自分のアバターのそばに猫じゃらしが出て、ときどき（25〜70 秒おき）茶トラ・黒猫・白猫・三毛猫・サバトラ・ハチワレのどれかが歩いてきて、しばらくじゃれてから去っていきます（自分の画面だけ）。"]},{"version":"0.1.611","items":["（T-888 の子・仕組み）「自分だけ退出」の予約を、通話のほかの人にも知らせるようにしました。表示は T-890 で入ります。報告は親 T-888 でまとめます。"]},{"version":"0.1.610","items":["にぎり屋さんに大将が登場しました。大将がにぎりを見ているときにクリックすると好感度が上がって 1 回でにぎれる数が増えます（最大 3 倍）。好感度は大将のほっぺの赤さで分かります。"]},{"version":"0.1.609","items":["にぎり屋さんに、クリックで 100 貫もらえる「ゴールデン酢飯」と、クリックで追い返さないとパネルを開いてからお手伝いがにぎった分を持っていく「酢飯小僧」が、画面を見ている間ときどき現れるようにしました。小僧を出にくくする「お店の守り」（招き猫・盛り塩・用心棒）も買えます（今までの進み具合はそのままです）。"]},{"version":"0.1.608","items":["にぎり屋さんに、お手伝いごとの「腕みがき」を足しました。同じお手伝いを 1・5・25・50・100 人雇うたびに 1 つずつ解放され、ためた貫で買うとそのお手伝いの増え方が 2 倍になります（買ったものも保存され、今までの進み具合はそのままです）。"]},{"version":"0.1.607","items":["通話の終了予約で「自分だけ」を選ぶと、自分ひとりが退出する時間（あと◯分／◯時◯分）を予約できるようにしました。3 分前にお知らせが出て、時刻になると自分だけ通話から抜けます。通話全体の予約と両方あるときは、両方の残り時間が見えます。","親 T-880 にまとめて報告します（終了予約のパネルの「みんな／自分だけ」の切り替えと、チップの両方の残り時間）。"]},{"version":"0.1.606","items":["おたのしみの「オート釣り」の横に「釣った魚を自動で流す」スイッチを付けました。オンにすると、オート釣りで釣れた魚が、自動でお寿司になって回転ずしに流れます（初期はオフ）。"]},{"version":"0.1.605","items":["画面共有を始めるとき、画面に描かれた線が消えるまでの時間を 10〜120 秒か無制限から選べるようにしました（既定 40 秒、見ている人が描いた線にも効きます）。"]},{"version":"0.1.604","items":["（親 T-880 でまとめて報告します。画面 T-882 の後に親を ready にします）","画面共有中、見ている人が引いたペンの線や印が、共有しているモニター／ウィンドウの上にも直接重なって見えるようにしました。","設定の画面共有の欄で、共有している画面の上に線・印を出すかどうかを切り替えられるようにしました。"]},{"version":"0.1.603","items":["設定に「ほかの人が選んだ縁取りで表示する」を追加し、オンにすると、ほかの人のアバターにその人が選んだ縁取り（色・模様）が付くようにしました（既定はオフで、今まで通り）。"]},{"version":"0.1.602","items":["画面共有を見ているとき、ホイール（タッチパッドのピンチ）や窓のバーの虫眼鏡ボタンで映像を拡大し、ドラッグで見たい所に寄れるようにしました（自分の画面だけで、ペンの線・印もずれません）。"]},{"version":"0.1.601","items":["曲の共有（Spotify・YouTube Music）で再生中の曲を、自分のアバターの「プレイ中」のゲームの表示のすぐ下にも出るようにしました。"]},{"version":"0.1.600","items":["自分の共有画面のウィンドウも、ほかの人の画面共有と同じタブに入れて、切り替え・並べて表示・別ウィンドウへの分離ができるようにしました。"]},{"version":"0.1.599","items":["おたのしみに、お皿をクリックしてお寿司をにぎり、ためた数でお手伝いを雇うと自動で増えていく遊び「にぎり屋さん」を足しました（進み具合はこの PC に保存され、閉じている間も増えます）。"]},{"version":"0.1.598","items":["自分のアバターの右上のステータスの絵文字をクリックすると、その場で絵文字を選び直せるようにしました（絵文字がないときは、アバターにマウスを乗せると点線の〇が出て、クリックで付けられます）。"]},{"version":"0.1.597","items":["画面共有（アプリの方式でモニター・ウィンドウ・範囲を共有）しているとき、見ている人が描いた線や印が、共有している本人の画面の上にも重ねて出るようにしました（クリックは下に通り、共有の映像には映りません）。"]},{"version":"0.1.596","items":["画面共有している本人も、自分の共有カードをクリックすると自分の共有画面を別ウィンドウで開けるようにし、ほかの人が引いたペンの線やクリックの印がそこに見えるようにしました（線が届くとカードにも出ます）。"]},{"version":"0.1.595","items":["設定「つくえ」で、机のマイク・観葉植物・飲み物に縁取り（色も選べます）を付けられるようにしました。ほかの人の画面にも出ます。"]},{"version":"0.1.594","items":["画面共有の窓のペンを入れてクリックすると、その場所に自分の色と名前の波紋の印が出て、部屋のみんなの画面に数秒だけ見えるようにしました（ドラッグすれば今までどおり線を引けます）。"]},{"version":"0.1.593","items":["設定の「もちもの」「つくえ」「かざり」タブを 2 段目にまとめ、かざり（頭・目・口）に回転と前後の調整を足し、ドックの「マイク」と「フキダシ」の並びを入れ替えました。"]},{"version":"0.1.592","items":["アップデートなどのお知らせ（通知）が、開いている設定やパネル、ふきだしに重ならないよう、よけて出るようにしました"]},{"version":"0.1.591","items":["「終了予約」を、ドックの「通話から出る」にマウスを乗せると横に出るボタンにまとめました（予約中は「通話から出る」に印が付きます）。"]},{"version":"0.1.590","items":["設定の「ドックに出すボタン」で、上（ホーム・設定）と下の通話の操作の「固定」のボタンも一つずつ出さないようにできるようにしました（並び順は今までどおり固定です）。"]},{"version":"0.1.589","items":["設定やほかのウィンドウを開いても、ホーム・おたのしみ・チャットなど開いているウィンドウが勝手に閉じないようにしました（閉じるのは ×・Esc・同じボタンを押したときだけ。設定にも × を付けました）"]},{"version":"0.1.588","items":["ドックの「画面共有」と「離席」を、下の通話の操作の固定のまとまりに入れました（真ん中に移っていた分は自動で外れます）。"]},{"version":"0.1.587","items":["ドックの真ん中のボタンを、右クリックの「ドックから外す」か、ドックの外へドラッグして離すだけで外せるようにしました（設定の「ドックに出すボタン」からまた出せます）。"]},{"version":"0.1.586","items":["ドックの「スタンプを贈る」ボタンをなくしました（スタンプは、相手のアバターのメニューからこれまでどおり贈れます）。"]},{"version":"0.1.585","items":["ドックの上（ホーム・設定・プリセット切り替え）と下（チャット一覧・終了予約・奥行き・カメラ・マイク・フキダシ・声を聞く・通話から出る）を固定にしました。並べ替え・追加・削除は真ん中だけでできます。上や下に置いていたほかのボタンは真ん中の最後へ移り、設定の「ドックに出すボタン」では固定のボタンに「固定」と出ます。"]},{"version":"0.1.584","items":["ホームから開いた設定でクリック貫通に入ったり、チュートリアルを始めたりしたときに、ホームがまた出てきてしまうことがないようにしました。"]},{"version":"0.1.583","items":["以前のバージョンから「すっきり」のドックを使っている方で、ドックのいちばん上が「設定」になっていたのを、「ホーム」がいちばん上になるように直しました（ご自分で並べ替えた並びはそのままです）。","ドックを「ホーム・設定・プリセット」「おたのしみなどのカスタマイズ」「通話の操作」の 3 つのまとまりに分け、間に見やすい区切り線を出すようにしました。"]},{"version":"0.1.582","items":["「おたのしみ」の中から論理回路などほかのウィンドウを開いても、おたのしみが閉じずに開いたまま残るようにしました。","「ホーム」の中から設定・ショートカット・更新履歴などほかのウィンドウを開いても、ホームが閉じずに横に開いたまま残るようにしました。"]},{"version":"0.1.581","items":["「おたのしみ」の中から論理回路などほかのウィンドウを開いても、おたのしみが閉じずに開いたまま残るようにしました。"]},{"version":"0.1.580","items":["アバターの下のマイクオフ・スピーカーオフの丸で、マークが左上に小さく寄っていたのを、丸の中央にちょうどよい大きさで出るように直しました。"]},{"version":"0.1.579","items":["かざりの「口」で、人形の形のジンジャーブレッドクッキーをくわえられるようにしました。"]},{"version":"0.1.578","items":["初めての人向けチュートリアルの素案を追加しました。設定の「全体」にある「チュートリアルを受けなおす」から、アバター・ドック・マイクと声・ホーム・通話・チャット・設定の使い方を順に案内します（途中でやめられます。自動では出ません）。"]},{"version":"0.1.577","items":["フィードバックを送ったときの郵便ポストが、ドックからうにゅっと生えて、紙飛行機をぱくっと食べるように一瞬ふくらみ、最後は生えてきたときの逆再生で引っこむようにしました。"]},{"version":"0.1.576","items":["設定の「つくえ」の観葉植物に「クリスマスツリー」、「かざり」の頭に「パーティーハット」、目に「2026メガネ」を追加しました（大きさ・位置の調整やほかの人への見え方はほかの小物と同じです）。"]},{"version":"0.1.575","items":["フィードバックを送ったときの紙飛行機の演出で、ドックから郵便ポストがうにょっと出てきて紙飛行機を受け取り、またうにょっとドックに戻るようにしました（同じ部屋のみんなの画面でも、それぞれのドックから出ます）。"]},{"version":"0.1.574","items":["設定の新しいタブ「かざり」で、アバターの頭（シルクハット・ねこみみ・王冠）、目（丸メガネ・サングラス・ハート）、口（ちょびひげ・マスク・キャンディ）に小物を付け外しできるようにしました。それぞれ大きさと上下左右の位置も調整でき、ほかの人の画面にも見えます"]},{"version":"0.1.573","items":["アップデートしても、自分で並べたドックの並び・フォルダ・プリセットが勝手に新しい並びへ切り替わらないようにしました（新しい「すっきりしたドック」はプリセットに 1 つ足されるだけです）。"]},{"version":"0.1.572","items":["アバターのメニューの「濃さ・ズーム・奥行き」に、マウスを乗せるだけで設定が出て、そのまま変えられるようにしました（設定へマウスを動かす途中で消えません）。"]},{"version":"0.1.571","items":["「つくえ」の飲み物に「缶ビール」と「醤油（卓上のしょうゆ差し）」を選べるようにしました。"]},{"version":"0.1.570","items":["ホームに含まれる「なかま」「じぶん」をドックに個別に出しているときは、その通知（未読の数や点）をホームのボタンには出さず、個別のボタンにだけ出すようにしました。"]},{"version":"0.1.569","items":["ペンタブを使っているときの作業モーションで、ペンを持つ手が前より大きく（2 倍に）動くようにし、設定 › 作業モーション の「ペンの動きの大きさ」で好みの大きさに変えられるようにしました。"]},{"version":"0.1.568","items":["ドックのボタンのツールチップと、設定の「ドックに出すボタン」「ドックのプリセット」の説明文を短くしました。"]},{"version":"0.1.567","items":["「つくえ」タブの「机のマイク」で、色や位置・大きさの小見出しをなくし、形・色・位置・大きさを 1 つの見出しの下にまとめました。"]},{"version":"0.1.566","items":["設定の「つくえ」タブで、机にマグカップ・ペットボトル・グラスのどれかを置けるようにしました（観葉植物と一緒に置けて、大きさと位置も変えられます）。"]},{"version":"0.1.565","items":["フィードバックを送ると、アバターの手元で紙飛行機が折られ、ドックへゆっくり飛んでいくようにしました（同じ部屋のみんなに見えます。送った内容はほかの人には伝わりません）。"]},{"version":"0.1.564","items":["ドックの「通話から出る」ボタンも、ほかのボタンと同じく並べ替え・フォルダに入れる・設定の「ドックに出すボタン」での出す／出さないができるようにしました（はじめの位置はこれまでどおりです）。"]},{"version":"0.1.563","items":["設定の「つくえ」タブで「机の小物」を「観葉植物」という名前にし、選択肢は観葉植物（「鉢植え」）をサボテンより先に並べました。"]},{"version":"0.1.562","items":["ドックのほかのボタン（どのボタンでも）を押したら、「おたのしみ」がほかのパネルと同じように閉じるようにしました。"]},{"version":"0.1.561","items":["設定の「アバター・動き」に「つくえ」タブを作り、机のマイク・机の小物・モニター・ヘッドホンをまとめました。「机の道具」タブは「もちもの」という名前にしました。"]},{"version":"0.1.560","items":["設定の「ドックに出すボタン」で、「ホーム」「おたのしみ（ウィンドウ）」から中に入っている機能へ矢印と枠でつなぎ、何が含まれているかわかるようにしました。"]},{"version":"0.1.559","items":["「おたのしみ」の中の各項目（Wordle・ババ抜き・サイコロなど）を、設定 › 全体 ›「ドックに出すボタン」で 1 つずつドックに出せるようにしました（はじめは今までどおり出ません）。"]},{"version":"0.1.558","items":["机のマイクの大きさを変えられるようにし、アーム式マイクを最初から大きくしました。マイクの色・位置・大きさは形ごとに覚え、ペンタブは手とペンをそのままに板だけ動かせるようにしました。","机にサボテン・観葉植物・多肉植物・花のどれか 1 つを置けるようにしました（大きさと位置も変えられます）。"]},{"version":"0.1.557","items":["ドックのほかのパネルやメニューを開いたとき、開いていた「おたのしみ」が閉じるように直しました（出しっぱなしにしているときは、今までどおり残ります）。"]},{"version":"0.1.556","items":["コントローラーを持つ作業モーションでも、設定の「コントローラーの手」で両手の間隔を変えられるようにしました（コントローラーの持ち手も一緒に広がります）。"]},{"version":"0.1.555","items":["設定画面の机の道具の「モニター（設定）」「ヘッドホン（設定）」を「モニター（設定画面）」「ヘッドホン（設定画面）」という表記にしました。"]},{"version":"0.1.554","items":["ドックの「おたのしみ」を押すと、ウィンドウが画面のいちばん上ではなく、押したボタンの脇に出るようにしました（ほかのパネルが開いているときは、その横に並びます）。"]},{"version":"0.1.553","items":["3D のマイクに「据え置き型」「アーム式」の形を足し、グレーの部分（頭）の色も別に選べるようにして、上下の位置も動かせる「机のマイク」タブにまとめました"]},{"version":"0.1.552","items":["設定 › 全体 › ドックのボタン で、ドックのプリセットの切り替えボタンを出す／出さないを選べるようにしました（消してもプリセットは残り、設定画面から切り替えられます）。"]},{"version":"0.1.551","items":["机の道具のモニター・ヘッドホンを「（設定）」付きの名前にして設定画面だけの表示とわかるようにし、作業モーションのトグルを「作業モーションのオン／オフ」と書き、ペンタブのときにも「手の間隔」（ペンを持たないほうの手の位置）を変えられるようにしました。"]},{"version":"0.1.550","items":["設定の「作業モーション」に「手の開き」を追加し、トラッキングが動いていないときの手の位置（横の開き・前後）と指の開き具合をスライダーで調整できるようにしました。"]},{"version":"0.1.549","items":["毎日の Wordle で、辞書にない英単語を入れて Enter を押すと「辞書にない単語です」と出て弾かれるようにしました（試行回数は減りません）","設定の「もぐもぐ中でない人にも」を「もぐもぐ中でない人の発言もピコピコ声で鳴らす」に改め、何がどうなるかの短い説明を添えました"]},{"version":"0.1.548","items":["「作業モーション」タブの見出しを「作業モーション」にしてオン／オフを一番上に置き、カメラの「手」にあった前後の設定を「手の前後の位置」「手の前後の動き幅」として作業モーションタブへ移しました。"]},{"version":"0.1.547","items":["設定の補足文とお気に入りスタンプの空表示を説明文の見た目にそろえ、「暗転」を「注目モード」に改名し、顔・目・手をカメラのタブにまとめ、「作業モーション」のタブを新しく作りました。","アバターの体の向き・上下の向き・大きさを名前をつけて保存し、ボタン 1 つで呼び出せる「向き・大きさのプリセット」を追加しました。"]},{"version":"0.1.546","items":["設定の補足文とお気に入りスタンプの空表示を説明文の見た目にそろえ、「暗転」を「注目モード」に改名し、顔・目・手をカメラのタブにまとめ、「作業モーション」のタブを新しく作りました。"]},{"version":"0.1.545","items":["「お楽しみ」の表記を「おたのしみ」にそろえ（メニューのほうは「おたのしみメニュー」）、設定の「ドックに出すボタン」で、いっしょに動くボタン（マイク → もぐもぐ／声を聞く → 全員をもぐもぐ化／画面共有 → いっしょに見る）を枠と矢印でつないで先に並べ、それぞれのボタンと分けて見られるようにしました。"]},{"version":"0.1.544","items":["アップデート後に一度だけ、ドックを新しい「すっきりしたドック」に切り替えるようにしました。それまでの並びはプリセット（以前の並び）に残してあり、お知らせの「前の並びに戻す」からすぐに戻せます（プリセットが 5 個ある方には、切り替えずに追加のしかたをお知らせします）。"]},{"version":"0.1.543","items":["「おたのしみ」から、通話の操作である「奥行き」「スタンプ」「全員をもぐもぐ化／もぐもぐ化を全部解除」を外し、遊びだけが並ぶようにしました（どれもドックの通話の操作から今までどおり使えます）。","すっきりしたドックを見直し、「スタンプ」「終了予約」を通話のボタンのそばに置き、「そのほか」のフォルダは遊びだけにして、ホームから開けるもの（じぶん・なかま・更新履歴など）はドックから外しました。設定の「ドックに出すボタン」も「ホーム」「通話の操作」「おたのしみ」に分けて並べました（今お使いの並びはそのままです）。"]},{"version":"0.1.542","items":["「おたのしみ」から、通話の操作である「奥行き」「スタンプ」「全員をもぐもぐ化／もぐもぐ化を全部解除」を外し、遊びだけが並ぶようにしました（どれもドックの通話の操作から今までどおり使えます）。"]},{"version":"0.1.541","items":["ドックの一番上にあった「終了」をホームの右上（設定の歯車の左）に移し、すっきりしたドックは一番上がホームに、「離席」が通話のボタンのそばに来るようにしました。"]},{"version":"0.1.540","items":["ドックの「画面共有」にマウスを乗せると「いっしょに見る（YouTube）」が横に出るようにし、すっきりしたドックでは画面共有を標準で出して、おたのしみの重複をなくしました。"]},{"version":"0.1.539","items":["ドックを「通話の操作／おたのしみ＋お気に入り／ホーム」の 3 つにまとめた「おすすめの並び」を、設定のドックのプリセットから追加できるようにしました（今の並びはそのまま残ります。新しく入れた方は初めからこの並びです）。","設定の「すっきりしたドック」で、奥の端に「お楽しみ」の代わりに「おたのしみ」（アプリとゲームをまとめたウィンドウ）のボタンが出るようにし、似ていた「おすすめの並び」のプリセットをなくしました。新しく入れた人のドックは「すっきり」の並びから始まります。"]},{"version":"0.1.538","items":["マイクと声を聞くから使えるようになった「もぐもぐモード」「全員をもぐもぐ化」の単独ボタンを、ドックのおすすめの並びとすっきりしたドックから外しました（今お使いの並びはそのままです）"]},{"version":"0.1.537","items":["ホームの中が「じぶん｜フレンド｜サーバー｜その他」のタブになり、ホームを開いたまま切り替えて見られるようにしました（設定は右上の歯車から開けます）。"]},{"version":"0.1.536","items":["ドックの「マイク」にマウスを乗せると「もぐもぐモード」、「声を聞く」に乗せると「全員をもぐもぐ化」のボタンが横に出て、そのまま押せるようにしました。"]},{"version":"0.1.535","items":["「映画を見ている」状態を選べるようにしました。ステータスの🎥を選ぶと、アバターが赤青の 3D メガネと大きいポップコーンを持ち、背景に映画館の座席が出ます。","（親 T-781 でまとめて報告します）","（親 T-798 でまとめて報告済み。この子は画面 T-800 と一緒にお客様から見える）","映画館モードに入る場所をステータスの🎥だけにしました（自分のアバターのメニューとドックの「映画を見る」ボタンをなくしました）。"]},{"version":"0.1.534","items":["ドックに「ホーム」のボタンを追加し、じぶん・なかま・設定・ショートカット一覧・更新履歴・フィードバック・クリック貫通をホームからまとめて開けるようにしました。"]},{"version":"0.1.533","items":["画面共有のタブで分割して見ているとき、境目をダブルクリックすると画面が均等な大きさに戻るようにしました。"]},{"version":"0.1.532","items":["通話の終了時刻を予約できるようにしました（「あと◯分」か「◯時◯分」で指定）。予約は通話の全員に共有されて残り時間とだれが予約したかが見え、3 分前にお知らせが出て、時刻になると自動で通話を抜けます。"]},{"version":"0.1.531","items":["通話の終了予約を入れる・変える・取り消す画面と、残り時間（だれが予約したか）の表示を付けました（親 T-798 でまとめて報告）。"]},{"version":"0.1.530","items":["たぬき寿司を食べて化けた姿が、食べた本人だけでなく部屋のみんなの画面にも出るように直しました。"]},{"version":"0.1.529","items":["お楽しみの欄にコインのショップを追加し、ヌシが釣れやすくなる「ヌシのえさ」を 20 コインで買えるようにしました（1 個でオート釣りの次の 20 回、ヌシが 4 倍かかりやすくなります）。","スパチャを投げると、おなかと同じ数のコインを使い、受け取った人のコインに貯まるようにしました（コインが足りないときは投げられません）。"]},{"version":"0.1.528","items":["画面共有をタブでまとめて見ているときに、「1 つを大きく＋ほかの人の画面を小さく並べる」「4 分割などで同時に見る」を選べるようにし、境目のドラッグで大きさを変えられるようにしました。"]},{"version":"0.1.527","items":["回転ずしに「たぬき寿司」（食べると 20 秒ほど部屋の誰かのアバターに化けます）と「きつね寿司」（食べるときつね色になって狐火が漂い、コンッと鳴きます）を追加しました。","回転ずしの「釣った魚を寿司にして流す」の欄で、同じ種類の魚を 1 つにまとめて「x3」のように個数を出すようにしました。"]},{"version":"0.1.526","items":["「かじる」の歯からピンクの歯茎をなくし、尖った牙でかみつく見た目と、牙の跡の歯形にしました。"]},{"version":"0.1.525","items":["新しいエモート「💡 ひらめき」を追加しました。アバターのメニューのハンドサインから（カメラでは人差し指を立てると）、頭上に電球がピカッと光り「ピカーン」と鳴って、部屋のみんなに見えます。"]},{"version":"0.1.524","items":["画像・動画のビューアやチャット・DM の別ウィンドウ、キャリブレーションの案内が、メインのディスプレイではなくアプリ（アバター）があるディスプレイの中央に開くようにしました。"]},{"version":"0.1.523","items":["画面共有をタブでまとめて見ているとき、タブをウィンドウの外へドラッグする（またはタブの「別ウィンドウにする」ボタン）と、その人の画面を別ウィンドウに分けられるようにしました（タブをクリックすると戻せます）。"]},{"version":"0.1.522","items":["オート釣りのヌシに、ラブカ・メガマウス・ピラルク・アカメの4種類のマニアックな魚を追加しました（魚の図鑑・回転ずしの大きいすしにも出ます）。"]},{"version":"0.1.521","items":["複数の人が同時に画面共有しているとき、1 つのウィンドウの中で、名前つきのタブで切り替えて見られるようにしました（設定でオフにすると今までどおり 1 人ずつ別のウィンドウで開きます）。"]},{"version":"0.1.520","items":["チャットの入力欄（チャットパネル・DM も）に画像や動画をドラッグ＆ドロップしても添付されなくなっていたのを直しました。"]},{"version":"0.1.519","items":["ステータスバッジの形で「三角」を選んだとき、3 つの角が少し丸くやわらかい形になるようにしました（大きさ・位置は今までどおり）。","ステータスで🎥を選ぶと「映画を見ている」状態に入り、ほかのステータスや手動の離席にすると外れるようにしました。"]},{"version":"0.1.518","items":["チャットのメッセージが並ぶ部分のどこに画像・動画をドラッグ＆ドロップしても、入力欄に添付されるようにしました（送る前に確認できます）。"]},{"version":"0.1.517","items":["iPhone のホーム画面に追加したスマホ版で concrnt ログインをしたとき、承認したあとアプリに戻ればそのままログインできるようにしました。"]},{"version":"0.1.516","items":["「映画を見ている」状態にすると、自分のアバターに赤青の 3D メガネと大きいポップコーンが出ます（報告は親 T-781 でまとめます）。"]},{"version":"0.1.515","items":["ほかの人のアバターのメニューは、アイコンにカーソルを合わせるとほかの表示より前に出て隠れなくなりました。画面共有のカードには、誰の画面かわかるように右上に名前を出すようにしました。"]},{"version":"0.1.514","items":["回転ずしに流したヌシの大きいすしは、別々の 3 人が食べるまでなくならず、食べるたびに少しずつ欠けて、3 人目で「完食！」が出るようにしました"]},{"version":"0.1.513","items":["ほかの人のアバターのメニューの 🧲（自分の奥行きに連れてくる）を押したとき、「連れてきますか？」と確認するようにしました。「連れてくる」を押したときだけ呼び寄せます。"]},{"version":"0.1.512","items":["アバターのメニューを開いたときの暗転を、「演出」とは別に 設定 › 表示 › 演出 の「メニューを開いたときの暗転」でオン・オフできるようにしました（FEVER などの演出は目立つままにできます）。","スマホ版（Web 版）で通話するとき、話していない間は音声をほとんど送らず、声の通信量も抑えるようにして、携帯の通信量を減らしました。","スマホ版の通話で、音声の通信量を減らしました（親 T-777 でまとめて報告）。"]},{"version":"0.1.511","items":["ドックのフォルダを開いて中のボタンへカーソルを動かすと、ドックが閉じてしまう不具合を直しました。"]},{"version":"0.1.510","items":["ドックの中身（並び順・出すボタン・フォルダ）をプリセットとして 5 個まで保存し、設定やドックのボタンからワンタッチで切り替えられるようにしました。"]},{"version":"0.1.509","items":["「かじる」の歯形を、丸い歯・ピンクの歯形とハート・「はむっ」の、かわいい見た目にしました。","ほかの人のアバターのメニューで、スパチャ・ドリンク・UFO・かじるを 1 つの「🎈 あそぶ」にまとめ、乗せると外側に並ぶようにしました。"]},{"version":"0.1.508","items":["自分のプロフィールとアカウントの操作（パスワード・メール・復旧コード・concrnt・ログアウト）を、ドックの新しい「じぶん」ボタンから開くパネルにまとめ、ボタンに文字を付けてわかりやすくしました。「なかま」はフレンドとサーバーの一覧に専念します。"]},{"version":"0.1.507","items":["T-747 でまとめて報告します。"]},{"version":"0.1.506","items":["自分のアカウントの欄でメールアドレスを登録・変更・外せるようにし、新規登録でもメールを任意で入れられるようにしました。パスワードを忘れたときは、メールに届く確認コードで設定し直せます（デスクトップ・スマホ版）。"]},{"version":"0.1.505","items":["スマホ版・ブラウザ版でも、設定の「アカウント」からプロフィール画像と表示名を変えられるようにしました。変えた内容は通話中のほかの人にも伝わります。"]},{"version":"0.1.504","items":["スマホ版・ブラウザ版の設定の「アカウント」から、プロフィール画像の変更・外すと表示名の変更ができるようにしました（通話中の相手にもすぐ反映されます）。"]},{"version":"0.1.503","items":["ほかの人のアバターを選んで、自分と同じ奥行きにすぐ連れてこられるようにしました。","なかま画面の自分のプロフィール欄に見出しをそろえ、色の選択を「フキダシの色」と書くようにしました。","人が多くても、だれがどのゲームをプレイ中かわかるようにしました。","毎日の Wordle で、パソコンのキーボード（英字・Backspace・Enter）でも入力できるようにしました。"]},{"version":"0.1.502","items":["（T-737 の部品。単独では変化なし）concrnt ログインの QR コードを表示するための部品を入れました。","ログイン画面で concrnt のアカウントでもログイン・新規登録できるようにし、自分のアカウントの欄から concrnt を紐づけたり外したりできるようにしました（デスクトップ・スマホ版）。"]},{"version":"0.1.501","items":["（下ごしらえのみ。画面の変化は T-767 で）スマホ版でもアイコン画像の加工が使えるようになり、プロフィールを変えたら通話中の人に知らせる仕組みを足しました。"]},{"version":"0.1.500","items":["なかま画面の鍵のボタン（パスワード・復旧コード）を押すと、ログアウトしてしまうことがある不具合を直しました。ログアウトのボタンは押すと確認が出るようにし、鍵のボタンから離しました。","なかま画面のログアウトのボタンを押したときに確認が出るようにし、鍵のボタンから離しました（スマホ版も同じ）。"]},{"version":"0.1.499","items":["なかま画面の鍵のボタン（パスワード・復旧コード）を押したときに、ログアウトしてしまうことがある不具合を直しました。"]},{"version":"0.1.498","items":["（T-752 の一部）メールでの本人確認とパスワード再設定のためのサーバー側の仕組み（表と Edge Function email-auth）を用意しました。画面は T-755 で付きます。"]},{"version":"0.1.497","items":["（T-752 の一部。画面の T-755 と一緒に出るまでお客様から見た変化はなし。報告は親の T-752 でまとめる）"]},{"version":"0.1.496","items":["スマホ版・ブラウザ版・デスクトップ版を行き来して入り直しても、ほかの人とつながらなくなることがないように直しました（ログアウトでほかの端末を切らない／相手は新しく入った方とつなぐ）。","同じアカウントで 2 か所から入っていても、相手は新しく入った方とだけつながるようにしました（T-749 の一部）。"]},{"version":"0.1.495","items":["ある端末でログアウトしても、同じアカウントでログインしているほかの端末はログインしたままになり、通話がつながらなくなることがなくなります。"]},{"version":"0.1.494","items":["毎日の Wordle を開いている人のアバターの上に「Wordle 中…」と出るようにし、押すとその人の盤面を見られるようにしました（最初は色だけ、「文字も見る」スイッチで文字も表示）。"]},{"version":"0.1.493","items":["ログイン中にパスワードを変えられるようにし、あらかじめ作っておいた「復旧コード」を使えば、パスワードを忘れてもログイン画面の「パスワードを忘れた」から新しいパスワードを設定し直せるようにしました（デスクトップ版・スマホ版）。"]},{"version":"0.1.492","items":["パスワードを忘れたときのために「復旧コード」を作っておけるようにし、ログイン画面の「パスワードを忘れた」から復旧コードで新しいパスワードを設定し直せるようにしました（デスクトップ・スマホ版）。"]},{"version":"0.1.491","items":["ログイン中に、自分のアカウントの欄から今のパスワードと新しいパスワードを入れてパスワードを変えられるようにしました（デスクトップ版・スマホ版）。"]},{"version":"0.1.490","items":["（T-737 の一部。単体ではまだ画面に出ません）concrnt でログイン・新規登録・紐づけを外すための呼び出しを用意しました。"]},{"version":"0.1.489","items":["concrnt のアカウントでログイン・新規登録・紐づけをするためのサーバー側の仕組みを用意しました（画面はこのあと）。"]},{"version":"0.1.488","items":["（画面はまだ。T-739 で設定からパスワードを変えられるようになる準備）","（画面はまだ。T-743 で、パスワードを忘れたとき復旧コードで設定し直せるようになる準備）"]},{"version":"0.1.487","items":["設定「アバター」に「上下の向き」スライダーを追加し、左右の「体の向き」と組み合わせて、アバターを上下左右いろいろな角度から見せられるようにしました。"]},{"version":"0.1.486","items":["ドリンクのメニューがほかの表示の後ろに隠れないよう最前面に出し、ほかの人のアバターにカーソルを重ねたときの集中表示（画面が暗くなる・縞）を、重ねた瞬間に出して外した瞬間に戻すようにしました。"]},{"version":"0.1.485","items":["画面共有で、画面やウィンドウの一部（四角で囲んだ範囲）だけを送れるようにしました。共有中に範囲を選び直したり、全体に戻したりもできます。"]},{"version":"0.1.484","items":["戦闘中に不参加の人に出る白旗のフキダシから「不参加」の文字を消し、旗だけにしました。"]},{"version":"0.1.483","items":["（T-690 の下準備。画面にはまだ出ないので、更新履歴は親の T-690 でまとめて書きます）"]},{"version":"0.1.482","items":["（T-690 の下準備。画面にはまだ出ないので、更新履歴は親の T-690 でまとめて書きます）"]},{"version":"0.1.481","items":["クリックのスライダーをドラッグしている途中で貫通が効いてしまう不具合を直し、離したときに確定するようにしました。貫通中は「Ctrl+Alt+L で戻す」の目印がずっと出て、ドックや設定から貫通に入る前に確認が出るので、誤って入りにくく、確実に戻せるようになりました。","クリック貫通中は「貫通中・Ctrl+Alt+L で戻す」の目印がずっと出て、ドックや設定から貫通に入る前に確認が出るようにしました。"]},{"version":"0.1.480","items":["ズーム・スケールのスライダーはドラッグ中に何度も反映されず離したときに一度だけ確定し、鳴き声の音量・高さの試し聞きもドラッグ中に何度も鳴らず離したときに一度だけ鳴るようにしました。"]},{"version":"0.1.479","items":["縁取り「炎」で白い縁が出ていたのを直し、縁取りの色だけで描くようにしました。あわせて、鳴き声（もぐもぐ）の表記、縁取りがオフのときの関係する項目の表示（半透明に）、クリック貫通中も使えるショートカットの表記をわかりやすくしました。","設定の「クリック」のスライダーを貫通側へドラッグしても、指を離すまでクリック貫通に切り替わらないようにしました。","Ctrl+Alt+L がほかのアプリに使われて効かないときは、戻し方の案内がタスクバーのメニューだけを示すようにしました。"]},{"version":"0.1.478","items":["設定の「記録」の項目も、ほかのタブと同じように「回数」「コイン」「魚の図鑑」の見出し（単色の線のアイコン付き）の下に並ぶようにしました。","縁取り「炎」で白い縁が出ていたのを直し、縁取りの色だけで描くようにしました。あわせて、鳴き声（もぐもぐ）の表記、縁取りがオフのときの関係する項目の表示（半透明に）、クリック貫通中も使えるショートカットの表記をわかりやすくしました。"]},{"version":"0.1.477","items":["スマホ版（ホーム画面に追加する Web 版）で、サーバーのチャットを読んだり書いたり、画像や動画を見たり送ったりできるようにしました（未読の数、招待コードでの参加、サーバーからの退出も）。","スマホ版で DM が使えるようにしました（会話の一覧と未読の数、フレンドや開発チームへの新しいメッセージ、文字・写真・動画のやりとり）。","スマホ版で通話（声）ができるようにしました（サーバーの通話に参加して話す・聞く、ミュート、スピーカーのオン／オフ、誰が話しているかの表示）。","スマホ版で、通話中のほかの人の画面共有（カメラの共有も）を見られるようにしました。全画面で開き、ピンチで拡大・ダブルタップで元に戻す・横向き（Android）ができます。"]},{"version":"0.1.476","items":["スマホ版（ホーム画面に追加する Web 版）で、サーバーのチャットを読んだり書いたり、画像や動画を見たり送ったりできるようにしました（未読の数、招待コードでの参加、サーバーからの退出も）。","スマホ版で DM が使えるようにしました（会話の一覧と未読の数、フレンドや開発チームへの新しいメッセージ、文字・写真・動画のやりとり）。","スマホ版で通話（声）ができるようにしました（サーバーの通話に参加して話す・聞く、ミュート、スピーカーのオン／オフ、誰が話しているかの表示）。"]},{"version":"0.1.475","items":["スマホ版（ホーム画面に追加する Web 版）で、サーバーのチャットを読んだり書いたり、画像や動画を見たり送ったりできるようにしました（未読の数、招待コードでの参加、サーバーからの退出も）。","スマホ版で DM が使えるようにしました（会話の一覧と未読の数、フレンドや開発チームへの新しいメッセージ、文字・写真・動画のやりとり）。"]},{"version":"0.1.474","items":["スマホ版（ホーム画面に追加する Web 版）で、サーバーのチャットを読んだり書いたり、画像や動画を見たり送ったりできるようにしました（未読の数、招待コードでの参加、サーバーからの退出も）。"]},{"version":"0.1.473","items":["設定の「V キーでマイクのオン／オフ」を、「声・マイク」から「全体・連携 › 操作」タブの「操作」の見出しの下へ移しました"]},{"version":"0.1.472","items":["設定の見出しのアイコンを、カラフルな絵文字からすっきりした単色の線のアイコンにそろえ、「机の道具」タブの見出し「道具」を「机の道具」にしました。"]},{"version":"0.1.471","items":["設定の「全体」タブで、テストモード・アップデート・カメラとマイクの動作チェック・再起動/アプリを終了を、ドックの操作・ドックのボタンの欄より下へ移しました（動作チェックは再起動・終了のすぐ上）。"]},{"version":"0.1.470","items":["設定の「アバター・動き」「音声・SE」「表示」で、見出しのなかった項目（アバター・カメラ・顔・手・机の道具・文字起こしのタブ）にも見出しを付けて、すべての項目がどれかの見出しの下に並ぶようにしました。"]},{"version":"0.1.469","items":["設定の「フキダシ」タブに「フキダシ」、「音・SE」タブに「音」の見出しを足し、見出しのなかった項目をその下にまとめました。"]},{"version":"0.1.468","items":["設定の「音声・SE」で「音」のタブを一番左にし、名前を「音・SE」に、「マイク・声」を「声・マイク」に変えました。"]},{"version":"0.1.467","items":["設定の表記と並びを整えました（「見た目」を「スキン」に、色の設定を「テーマ」にまとめてライト／ダークを「プリセット」に、データセーバーとアバターの描画を「アバターの見え方」の中へ、「マイク・スピーカーがオフの人の見え方」を「UI」へ。見出しと、その下の項目を見分けやすくしました）。","設定の「全体」タブで、テストモード・カメラとマイクの動作チェック・アップデート・再起動／アプリを終了を見出しなしで上から並べ、動作チェックと再起動・終了を「操作」タブから「全体」へ戻しました。"]},{"version":"0.1.466","items":["スマホ版（Web 版）がリリースのたびに公開ページ（app/）へ一緒に上がるようになり、iPhone のホーム画面に追加したときのアイコンも専用の画にしました。","設定の表記と並びを整えました（「見た目」を「スキン」に、色の設定を「テーマ」にまとめてライト／ダークを「プリセット」に、データセーバーとアバターの描画を「アバターの見え方」の中へ、「マイク・スピーカーがオフの人の見え方」を「UI」へ。見出しと、その下の項目を見分けやすくしました）。"]},{"version":"0.1.465","items":["（親 T-698 でまとめて報告します）スマホ版を iPhone のホーム画面に追加したときのアイコンを、角が透明にならない専用の画にしました。"]},{"version":"0.1.464","items":["「操作」と「データセーバー」を、全体・連携 › 操作・データセーバー の 1 つのタブにまとめ直しました（表示 › データセーバー のタブはなくなります）。","設定のデータセーバーを「表示」のタブに戻し、アップデートとテストモードを「全体」に、クリックの設定を「全体・連携 › 操作」に移しました。","リリースのたびに、スマホ版（Web 版）が公開ページの app/ に最新の中身で上がるようになりました。","開発用の改善として、テストのたびに Windows ファイアウォールの確認が出ないようにしました。iFacialMocap の使い方は変わりません。"]},{"version":"0.1.463","items":["「操作」と「データセーバー」を、全体・連携 › 操作・データセーバー の 1 つのタブにまとめ直しました（表示 › データセーバー のタブはなくなります）。"]},{"version":"0.1.462","items":["開発用の改善（テストのたびに Windows ファイアウォールの確認が出ないようにしました）。iFacialMocap の使い方は変わりません。"]},{"version":"0.1.461","items":["設定画面を整理しました。もぐもぐと読み上げを「マイク・声」へ移して「マイク」の見出しを付け、「ドック」と「クイックメニュー」を別々の欄にし、「全体・連携」に「操作・データセーバー」をまとめ、説明文でない文字の濃さをそろえました。","データセーバーの設定を「表示」のタブに戻し、「全体・連携」には入力欄のキーやアップデートなどをまとめた「操作」のタブを作りました。"]},{"version":"0.1.460","items":["設定画面を整理しました。もぐもぐと読み上げを「マイク・声」へ移して「マイク」の見出しを付け、「ドック」と「クイックメニュー」を別々の欄にし、「全体・連携」に「操作・データセーバー」をまとめ、説明文でない文字の濃さをそろえました。"]},{"version":"0.1.459","items":["起動やアップデートのあとに設定を開いたとき、設定の画面が一瞬モニターの一番上に出てから元の位置へ戻るのを直しました。"]},{"version":"0.1.458","items":["自分の画面共有のカードが小さな札になっている間やアプリが隠れている間は、自分のプレビュー映像の処理を止めるようにし、共有中のパソコンの負担を減らしました。"]},{"version":"0.1.457","items":["画面共有中、自分のプレビューを見ていない間は自分の共有映像の処理を省けるようにし、送る側のパソコンの負担を減らす準備をしました（プレビューの表示に合わせた切り替えは次の更新で入ります）。"]},{"version":"0.1.456","items":["画面共有を見ている人の回線が詰まったときに、送る画質を自動で下げてカクつきを減らし、空いたらゆっくり元に戻すようにしました（T-691 の一部）。"]},{"version":"0.1.455","items":["画面共有の「アプリの音だけ」で、音が送られないアプリがあったのを直しました（同じアプリの別プロセスが鳴らす音も取るように）。それでも取れないときは共有パネルに「このアプリの音が取れていません」と出て、「パソコン全体の音にする」ボタンで切り替えられます。取っているアプリの名前も表示します。","親 T-700 でまとめて報告します。"]},{"version":"0.1.454","items":["画面共有で、最小化されたウィンドウも一覧から選べるようにし、共有中にゲームなどが最小化されても共有が切れず、見ている人には最後の画が出続け、戻すと続きが流れるようにしました（ウィンドウが作り直されたときもつなぎ直します）。","画面共有の一覧で最小化中のウィンドウに「最小化中」の印が付き、共有中のウィンドウが最小化されたとき・探し直しているときに短い案内が出るようにしました。","（T-700 にまとめて書く）画面共有の「アプリの音だけ」で音が取れていないことをアプリが把握し、「パソコン全体の音」に切り替えて共有し直せるようにしました（画面の表示は T-703）。"]},{"version":"0.1.453","items":["画面共有の「アプリの音だけ」で、音を鳴らしているのがウィンドウとは別のプロセス（同じアプリの親や兄弟）でも、そのアプリの音を取れるようにしました。取れていないときはページに知らせます（表示は T-703）。"]},{"version":"0.1.452","items":["画面共有のとき、リフレッシュレートの高いモニターでも設定した FPS の分だけ画を取り込むようにし、送る側のパソコンの負担を減らしました。"]},{"version":"0.1.451","items":["ウィンドウを共有中にそのウィンドウを最小化しても共有が止まらず、見ている人には最後の画が残るようにしました。ゲームが画面を作り直しても、同じウィンドウにつなぎ直します。"]},{"version":"0.1.450","items":["画面共有パネルに、いま使っているエンコーダーの名前と、GPU で変換しているかどうかが出るようになりました"]},{"version":"0.1.449","items":["画面共有パネルに、送っている音の音量ゲージ（無音なら「音が来ていません」）と、送る音の音量調節（0〜200%）を付けました。"]},{"version":"0.1.448","items":["画面共有のウィンドウ一覧に、最小化中のウィンドウも出るようにしました（親 T-688 でまとめて報告します）。"]},{"version":"0.1.447","items":["ドックとクイックメニュー（自分のアバターの下のボタンの列の新しい呼び名）の設定を「UI」タブに戻し、「全体」タブのドックの操作は、ドックのボタンすべてをアイコンだけで並べて押しやすくしました（カーソルを合わせると名前が出ます）。"]},{"version":"0.1.446","items":["設定画面を整理しました。テストモード、ドックに出すボタン、ドックでできる操作（マイク・離席など）は「全体」タブにまとめました。「ゲーム・演出」タブの音は「音」タブへ、見た目は「表示」の新しい「演出」タブへ移しました。演出は「目立つ／控えめ」から選ぶ形にし、戦闘参加の音は A に揃えました。各タブの説明文も短くしました。"]},{"version":"0.1.445","items":["奥行きの表記を「奥1〜奥8」から「+1〜+8」に変えました（いちばん手前は「手前」のまま）。","ドックのボタンをつかんで別のボタンに重ねると、フォルダにまとめられるようにしました（クリックで中のボタンが開き、名前の変更・取り出し・解除もできます）。"]},{"version":"0.1.444","items":["奥行きの表記を「奥1〜奥8」から「+1〜+8」に変えました（いちばん手前は「手前」のまま）。"]},{"version":"0.1.443","items":["通知のベルを押そうとカーソルを近づけたときにドックが出てきてベルに重なり、押せなかったのを直しました（ベルはいつもドックの横に出ます）。"]},{"version":"0.1.442","items":["ドックのボタンのツールチップと、お楽しみ・YouTube のメニューの説明文を短くしました","設定の各タブの中を「もぐもぐ」「離席」「戦闘」「ドック・ボタン列」などの見出しでまとめ、もぐもぐ関連の項目を「音」タブの 1 か所に集めました"]},{"version":"0.1.441","items":["ドックのボタンのツールチップと、お楽しみ・YouTube のメニューの説明文を短くしました"]},{"version":"0.1.440","items":["アバターの大きさの表記を「ズーム」「スケール」に変え、ドックの奥行きをスライダーで選べるように、「Boop する／Boop しない／クリック貫通」を 1 本のスライダーで切り替えられるようにし、設定の説明文を短くしました。"]},{"version":"0.1.439","items":["ドックの「奥行き」ボタンを押すと、手前・奥1〜奥8 の一覧が出て、好きな奥行きを選べるようにしました。"]},{"version":"0.1.438","items":["アバターの列をつまみのドラッグで回転させる機能を取り除きました。回転させていた方も、ふつうの向きの表示に戻ります。"]},{"version":"0.1.437","items":["画面共有パネルに「カメラ・キャプチャーで共有できるようにする」の切り替えを追加しました。オフにすると共有先にカメラ・キャプチャーが出なくなり、誤って Web カメラやキャプチャーボードの映像を配信しません（最初はオンのまま）。"]},{"version":"0.1.436","items":["通話中に相手の版が「版を確認中…」のまま戻らず、画面配信を見る・遊びの申し込みができなくなることがある不具合を直しました（受け取りが止まった接続を自動で作り直します）。"]},{"version":"0.1.435","items":["サーバーに入っていない間、設定から「テストモード」をオンにすると、ダミーのアバターを増やしたり減らしたりして、なでる・攻撃などの相手向けの操作を一人で試せるようにしました（サーバーに入ると自動で解除されます）。","画面共有で「カメラ・キャプチャー」を流すとき、一緒に送る音（映像と同じ機器の音・選んだ音声入力・パソコンの音・音なし）を選べるようにしました。キャプチャーボードの音も映像と一緒に相手に届きます。","画面共有の「カメラ・キャプチャー」で一緒に送る音に、特定のスピーカーやヘッドホンで鳴っている音を選べるようにしました（その出力で鳴っている通話の声も入ります）。","長時間起動していると、最新版の相手が「版不明（古い版）」扱いになり、遊びの申し込みなどのボタンが出なくなる不具合を直しました。版がまだ届いていない間は「版を確認中…」と表示します。","画面配信を見ている途中で映像が止まったり届かなくなったりしても、数秒〜20 秒ほどで自動でつなぎ直し、再起動しなくても見え続けるようにしました。"]},{"version":"0.1.434","items":["画面共有の「カメラ・キャプチャー」で、映像と一緒に送る音（映像と同じ機器の音・選んだ音声入力・パソコンの音・音なし）を選べるようになりました。配信中の表示にも、送っている音が出ます。"]},{"version":"0.1.433","items":["戦闘に不参加の人の白旗を、ステータスのアイコンと見間違えないよう、アバターの左側に「🏳️ 不参加」のフキダシで出すようにしました。","撫でるをブロックしたとき、ブロックした人のアバターから「SORRY!」とドット文字のフキダシが出るようにしました。","設定の更新履歴に検索欄を付けて、言葉やバージョン番号で過去の更新を探せるようにしました。","ドックの「いっしょに見る（YouTube）」のメニューを、お楽しみと同じく、アイコンをクリックしたら開くようにしました。","FEVER の間、みんなのアバターの位置がくるくる入れ替わり、終わると元の並びに戻るようにしました。","自分のアバターの足元に「フィールド」（草・海・マグマ・毒・雪）を敷けるようにしました。部屋の人にも見えます。","ほかの人のアバターのメニューに「かじる」を足しました。かじると、みんなの画面で相手に歯形が付き、しばらくすると消えます。","パネルのスキン「迷彩」と「アロハ」の柄を、うっすらしたまま本物らしい形（ウッドランド迷彩のまだら・ハイビスカスと葉）にしました。"]},{"version":"0.1.432","items":["ドック（ボタンの列）に「奥行き」のボタンを足し、1 クリックで「手前」と「一個奥」を行き来できるようにしました。同じ層の人どうしはいつもどおり、違う層の人とはお互い少し小さく見え、声も少し下がります。","長時間起動していて通話の接続が自動でつなぎ直されたときに、最新版の相手が「版不明（古い版）」扱いになって遊びの申し込みなどのボタンが消えてしまうのを直しました。"]},{"version":"0.1.431","items":["（仕組みのみ。画面の子チケットと合わせて親 T-663 で報告します）サーバーに入っていない間だけ、ダミーのアバターを置いて、なでる・攻撃・スタンプを自分の画面の中だけで試せる仕組みを入れました。"]},{"version":"0.1.430","items":["ドックのボタンを、つかんでどの向きに動かし始めても並べ替えられるようにしました（ボタンのすき間をつかんでも、近いボタンを動かせます。並びは再起動後も残ります）。"]},{"version":"0.1.429","items":["（T-666 の仕組み。報告は親 T-666 でまとめます）カメラ・キャプチャーの画面共有に、選んだ音を一緒に乗せられるようにしました（選ぶ画面は T-669）。"]},{"version":"0.1.428","items":["設定でドックを「メニュー」と呼んでいた所を「ドック」にそろえ、「クリック貫通」と「アバターをクリックで Boop する」の違いを説明に書き、データ節約の設定を「表示」の「データセーバー」タブにまとめました。","ドックに出していないボタン（マイク・もぐもぐ・離席・フキダシ・全員をもぐもぐ化・オート釣り・チャット一覧・なかま・画面共有・ショートカット一覧）も、設定の画面から使えるようにしました。"]},{"version":"0.1.427","items":["毎日の Wordle で、画面のキーボードがずれて重なり押せなかったのと、ほかの人の盤面が見えなかったのを直しました。マウスだけで遊ぶ形にし、入力欄と「文字も見る」をなくしました（ほかの人の盤面は色だけ表示）。"]},{"version":"0.1.426","items":["オート釣りでマウスを動かして上がったヌシのかかりやすさ（「ヌシ↑」）が、マウスを止めると十数秒でだんだん元に戻るようにしました。動かし続けている間だけ効果が続きます。"]},{"version":"0.1.425","items":["オート釣りの間、マウスを動かしているあいだは釣り竿（糸・浮きも）が上下に動くようにしました（自分の画面だけ。止めると元に戻ります）。"]},{"version":"0.1.424","items":["論理回路で、何もない所からドラッグして囲んだり Shift / Ctrl+クリックしたりして複数の部品を選び、まとめて移動・コピー＆貼り付け（つながった線ごと）・削除できるようにしました。"]},{"version":"0.1.423","items":["毎日の Wordle の画面キーボードに「ENTER」キーを足して、マウスだけで文字を入れて確定できるようにしました。"]},{"version":"0.1.422","items":["毎日 1 問、みんな同じ英語 5 文字の単語当て「毎日の Wordle」を遊べるようにしました。同じ部屋の人の挑戦中のようすと結果も、色だけ、または文字ありで見られます。"]},{"version":"0.1.421","items":["チャット欄の蝶のボタンでしおりを挟めるようにしました（蝶がひらひら飛んで押した時刻の所にとまり、クリックでそこへ戻れます。しおりはこの PC だけに保存されます）。"]},{"version":"0.1.420","items":["論理回路のチュートリアル中の様子をほかの人も「回路設計中…」の札から見られるようにし、チュートリアルのクリア数（クリア数/総数）をプロフィールカードに出し、真理値表の行をクリックするとその入力が回路図に入って線・ランプで確かめられるようにしました。"]},{"version":"0.1.419","items":["論理回路のチュートリアルに第1章「組合せ回路」（多数決回路・全加算器・比較器・4 ビット加算器）を追加しました。前の章で作った半加算器や全加算器を部品として使えます。"]},{"version":"0.1.418","items":["回転ずしの忍者もつかまえて食べられるようにしました。食べた人には「ニンニン」の吹き出しが出て、アバターが分身しながら左右に素早く揺れます（6 秒、部屋のみんなの画面に出ます）。"]},{"version":"0.1.417","items":["オート釣りの間、マウスをよく動かしているほどヌシがかかりやすくなるようにしました（自分の浮きの横に「ヌシ↑」が出ます）。"]},{"version":"0.1.416","items":["ほかの人のアバターにカーソルを乗せたときに画面が暗くなる演出を、設定（ゲーム・演出）の「アバターにカーソルを乗せたとき画面を暗くする」でオン・オフできるようにしました。"]},{"version":"0.1.415","items":["オート釣りでヌシがかかったとき、「引け！」を押せる時間を 15 秒から 6 秒にし、かかっている間は 2 秒ごとに音でお知らせするようにしました。"]},{"version":"0.1.414","items":["オート釣りでヌシがかかったとき、「引け！」を押せる時間を 3 秒から 15 秒に延ばし、かかっている間は 5 秒ごとに音でお知らせするようにしました。"]},{"version":"0.1.413","items":["「全員をもぐもぐ化」のアイコンを、手前のおにぎりの後ろにもう 1 個が半分ほど隠れて重なった、おにぎり 2 個の絵にしました。"]},{"version":"0.1.412","items":["戦闘をオフにしている人の白旗を、その人のアバターから出た小さいフキダシの中に入れて、誰の白旗か分かるようにしました（白旗の下の名前のフキダシは外しました）。"]},{"version":"0.1.411","items":["お楽しみの「全員をもぐもぐ化」のアイコンをおにぎりが並んだ絵にし、ドックのボタンとしても出せるようにしました（設定の「メニューに出すボタン」で選べます）"]},{"version":"0.1.410","items":["ほかの人のアバターにカーソルを合わせたとき、扇形のメニューと注目の演出が前より早く出るようにし、お楽しみの「フィーバー」を「FEVER」という表記にしました。"]},{"version":"0.1.409","items":["戦闘をオフにしている人のアバターに出る白旗の下に、その人の名前を小さいフキダシで出し、誰の白旗か分かるようにしました。"]},{"version":"0.1.408","items":["釣ったヌシを寿司にして流すと、今までの約 2.5 倍の大きさで流れるようにしました。"]},{"version":"0.1.407","items":["お楽しみの「戦闘」の枠を「バトル」に改名し、早押しとじゃんけんもその枠の中から選べるようにしました。"]},{"version":"0.1.406","items":["釣りはドックのオート釣りボタンだけで始める・止める形にし、お楽しみのメニューから釣りを外しました。魚の図鑑は設定の「記録」から見られるようにしました。"]},{"version":"0.1.405","items":["お楽しみのカードのゲーム（ババ抜き・カラーカード・ブラックジャック）と戦うゲーム（決闘・ボスレイド・反射神経バトル・タイピングダンジョン）を、それぞれ「カード」「戦闘」の枠にまとめました。枠を押すと中のゲームが選べます。"]},{"version":"0.1.404","items":["魚が釣れたときの頭の上の表示を、ふだんは魚のアイコンだけにし、その魚の最大記録を更新したときだけ大きさを出すようにしました。魚の図鑑で、種類ごとの釣った数と合計の匹数を見やすくしました。"]},{"version":"0.1.403","items":["釣りに「オートで釣る」（釣れるたびに自動で糸を垂らし直し、そのあいだは音が鳴らない）と、釣った魚の種類と最大サイズを残す「魚の図鑑」を足しました。","釣りで、ときどき古代魚などの「ヌシ」がかかるようにしました。かかったら出てくる「引け！」を押さないと逃げられます。","釣った魚を回転ずしのカードから寿司にして流せるようにしました。寿司の上に釣った人の名前が出て、ヌシの寿司はふつうより大きく流れます。"]},{"version":"0.1.402","items":["釣りに「オートで釣る」（釣れるたびに自動で糸を垂らし直し、そのあいだは音が鳴らない）と、釣った魚の種類と最大サイズを残す「魚の図鑑」を足しました。","釣りで、ときどき古代魚などの「ヌシ」がかかるようにしました。かかったら出てくる「引け！」を押さないと逃げられます。"]},{"version":"0.1.401","items":["釣りに「オートで釣る」（釣れるたびに自動で糸を垂らし直し、そのあいだは音が鳴らない）と、釣った魚の種類と最大サイズを残す「魚の図鑑」を足しました。"]},{"version":"0.1.400","items":["相手のアバターの「注目」（暗くなるグラデーションとストライプ）が、まわりのボタンへカーソルを移すときにちかちかするのを直し、カーソルを合わせてから出るまでを早くしました。"]},{"version":"0.1.399","items":["相手のアバターの扇形メニューで、👊 の攻撃（と 🖼️ のスタンプ）の外側の列が開かない・すぐ閉じてしまい選べないことがあったのを直しました。"]},{"version":"0.1.398","items":["相手のアバターの扇形メニューで、スタンプを 🖼️ ひとつにまとめました。乗せると攻撃と同じように外側にお気に入りから順に並び、押すと全部の一覧が開きます。","扇形メニューが画面の端でずれたときの矢印を、太く矢じり付きにして目立たせました。扇形メニューが出ている間は、画面を上から下へ暗くし、対象のアバターの後ろにストライプが流れるようにしました（「派手な演出を控えめにする」がオンのときは控えめになります）。"]},{"version":"0.1.397","items":["ドックの YouTube ボタンにカーソルを当てたときに出るメニュー（URL から動画を共有／プレイリストを再生）が小刻みに揺れる不具合を直しました。"]},{"version":"0.1.396","items":["論理回路の画面にもペンを付け、画面共有と同じように回路の上にお絵描きできるようにしました"]},{"version":"0.1.395","items":["回転ずしに「忍者」を追加しました。お皿には乗らず、忍者そのものがみんなの前をお皿より速く走り抜けます。"]},{"version":"0.1.394","items":["通話中の CPU の負担を減らしました（顔トラッキングの処理を画面の描画と分けて動かす、空間音声で前にいる相手の声の余計な立体処理を省く、SteamVR を開いたままでもヘッドセットを外している間は読み取りを控える）。","SteamVR でヘッドセットをかぶっている間は、頭の向きに加えてコントローラーの動きでアバターの手も動くようにしました。","SteamVR を開いたまま（ヘッドセットを外して）通話していても、アプリが VR の読み取りで CPU を使い続けないようにしました。"]},{"version":"0.1.393","items":["設定の「VR ヘッドセットに自動で合わせる」の説明に、かぶっている間はコントローラーで手も動くことを書き足しました。"]},{"version":"0.1.392","items":["お楽しみに「釣り」を追加しました。「釣り糸を垂らす」を押すとアバターの横に竿と浮きが出て、しばらくするとランダムな魚が釣れ、「ピロン」と鳴って頭の上に魚と大きさが出ます（部屋のみんなの画面に出ます）。"]},{"version":"0.1.391","items":["空間音声で、同じ奥行き・前にいる相手の声に立体音響の重い処理をかけないようにし、大人数の通話で CPU の負担を減らしました。"]},{"version":"0.1.390","items":["顔と手のトラッキングの検出を画面の描画とは別の処理に移し、通話中に描画がカクつきにくく、CPU の負担が軽くなるようにしました。","SteamVR でヘッドセットをかぶっている間は、手の入力元や「机に固定」の設定にかかわらず、コントローラーでアバターの手が動くようにしました。"]},{"version":"0.1.389","items":["論理回路シミュレーターに分かりやすい「保存」ボタン（名前を付けて保存）を付け、保存した部品の一覧・名前の変更・削除・編集・お気に入りができるようにしました。置いた部品をダブルクリックすると中身を編集でき、同じ部品を置いた所すべてに反映されます。配線はゲートの図に重ならないよう、直角に曲がって避けて引くようにしました。"]},{"version":"0.1.388","items":["ほかの人の名前をクリックしたメニューの一番上に、その人のアプリの版と「最新／古い」を表示するようにしました"]},{"version":"0.1.387","items":["論理回路に初心者向けの「チュートリアル」を追加し、第0章「論理回路入門」（0 と 1、スイッチとランプ、NOT・AND・OR・XOR、真理値表、半加算器）を、部品を置いてつなぎながらヒント・動作確認・クリア判定つきで学べるようにしました（作った半加算器は部品として保存され、次の章で使えます）。"]},{"version":"0.1.386","items":["（画面は T-613。報告は親 T-610 でまとめます）通話の相手のアプリの版を受け取り、最新か古いかを判定できるようにしました。"]},{"version":"0.1.385","items":["Steam でゲームをプレイしている間、アバターの頭の上にそのゲーム名が出るようにしました（ゲームを終えると消え、ほかの人の画面にも出ます。設定でオフにできます）。"]},{"version":"0.1.384","items":["自分の奥行き（前後の位置）が再起動・アップデートのあとも前回のまま残り、入室したときにみんなの画面でも同じ位置にそろうようにしました。"]},{"version":"0.1.383","items":["論理回路を開いている人のアバターの上に「回路設計中…」と出るようにし、クリックでその人の回路を見に行けるようにしました。"]},{"version":"0.1.382","items":["論理回路の入力に、周期を ms で決められる CLK（クロック）を追加し、AND・OR・NOT などのゲートを MIL 記号の形で描くようにしました（ゲート名は記号の中にそのまま表示）。","論理回路に入力・出力の端子を置けるようにし、作った回路を名前を付けて保存・チャットに貼れる文字列で共有できるようにし、保存した回路を部品として別の回路の中で使えるようにしました。","論理回路で「見ている人も編集できる」を入れると、回路を開いて見ているほかの人も、部品を置く・つなぐ・動かすなどで一緒に回路を作れるようにしました。"]},{"version":"0.1.381","items":["論理回路の入力に、周期を ms で決められる CLK（クロック）を追加し、AND・OR・NOT などのゲートを MIL 記号の形で描くようにしました（ゲート名は記号の中にそのまま表示）。","論理回路に入力・出力の端子を置けるようにし、作った回路を名前を付けて保存・チャットに貼れる文字列で共有できるようにし、保存した回路を部品として別の回路の中で使えるようにしました。"]},{"version":"0.1.380","items":["論理回路の入力に、周期を ms で決められる CLK（クロック）を追加し、AND・OR・NOT などのゲートを MIL 記号の形で描くようにしました（ゲート名は記号の中にそのまま表示）。"]},{"version":"0.1.379","items":["SteamVR でヘッドセットをかぶっている間は、自動でアバターにヘッドセットを付け、頭の向きをヘッドセットに合わせて部屋のみんなに見えるようにしました（設定の顔トラッキングの欄でオフにできます）。"]},{"version":"0.1.378","items":["設定の顔トラッキングの欄に「VR ヘッドセットに自動で合わせる」の切り替えを足し、SteamVR でヘッドセットをかぶっている間の自動の頭の向き・ヘッドセット表示をオフにもできるようにしました。"]},{"version":"0.1.377","items":["SteamVR でヘッドセットをかぶっている間は、設定を切り替えなくても自動でアバターの頭の向きがヘッドセットに合い、アバターもヘッドセットを付けた姿になるようにしました（外すと元に戻ります）。"]},{"version":"0.1.376","items":["攻撃の一覧（👊 の外側の 2 列目）で、雷などへカーソルを動かす途中に一覧が消えてしまう不具合を直しました。"]},{"version":"0.1.375","items":["設定画面を開いたままマウスを動かしても閉じないようにしました（設定画面の外を押す・Esc・設定ボタンで閉じます）。"]},{"version":"0.1.374","items":["アバターの列の端に出る ✥ のつまみをドラッグすると、列まるごとを横に回す・前後に倒す・傾けることができるようにしました（横並び・縦並びのどちらでも同じ操作。あなたの画面だけで、ダブルクリック・↺・設定の「元に戻す」で戻せます）。"]},{"version":"0.1.373","items":["YouTube の別ウィンドウで、別の動画に変えても同じウィンドウのまま再生されるようにし、右上の×をなくし、今の動画のリンクをコピーするボタンを付けました。ほかの人が再生・一時停止・シーク・動画の切り替えをしたときは「○○さんが一時停止しました」のように数秒表示します。"]},{"version":"0.1.372","items":["YouTube の別ウィンドウで、ほかの人が再生・一時停止・シーク・別の動画への切り替えをしたとき、「○○さんが一時停止しました」のように誰が何をしたかを数秒だけ表示するようにしました。"]},{"version":"0.1.371","items":["お腹ずしを食べたときのふくらみを、もう少し下のお腹らしい位置に下げ、大きさもはっきりわかるくらいにしました（3 段の重ねがけはそのまま、どの段も大きくなります）。"]},{"version":"0.1.370","items":["画面共有を見ている窓の「ペン」で映像の上に線を描けるようにしました。線は部屋のみんなの画面（共有している人のプレビューにも）に描いた人の色と名前つきで出て、しばらくすると消えます。"]},{"version":"0.1.369","items":["YouTube の別ウィンドウで、「別の動画」を押してもウィンドウが閉じず、そのウィンドウの中でリンクを入れて次の動画を流せるようにしました。バー右端の×をなくし（ウィンドウの閉じるボタンで閉じます）、今の動画のリンクをコピーするボタンを足しました。"]},{"version":"0.1.368","items":["「いっしょに見る（YouTube）」の音が大きすぎるのを直しました。音量のつまみを小さくするとしっかり小さくなり、最大でも通話の声とつり合う大きさにしました。"]},{"version":"0.1.367","items":["子チケット T-591（ドックの YouTube メニュー・入力欄にカーソルがあるとき消えないようにした）と T-592（画面共有と YouTube をいつも別ウィンドウで開く・再生できなければ自動で重ね表示に戻す）で対応しました。更新履歴はそれぞれの子チケットの文を使ってください。"]},{"version":"0.1.366","items":["画面共有と「いっしょに見る（YouTube）」が、いつも別のウィンドウで開くようになりました（設定の切り替えと「重ね表示に戻す」ボタンはなくしました）。別のウィンドウで YouTube が再生できないときは、自動で今までの重ね表示に切り替えて再生を続けます。"]},{"version":"0.1.365","items":["ドックの YouTube ボタンから出すメニューや URL の入力欄にカーソルを置いて待ったり文字を打ったりしている間に、ドックごと消えてしまう不具合を直しました。"]},{"version":"0.1.364","items":["回転ずしの「宇宙人」と「宇宙人寿司」を「宇宙人」1 つにまとめました（食べると数秒緑色になり、声も変わります）。","回転ずしのガソスタ・ミラー・電池・ロボ・ネジを食べると、数秒アバターが燃える・ミラーボールとキラキラと歓声・回復の光と音・メタル色と金属音・ネジのように回って地面に沈む、の演出が部屋のみんなに出るようにしました。"]},{"version":"0.1.363","items":["回転ずしの「宇宙人」と「宇宙人寿司」を「宇宙人」1 つにまとめました（食べると数秒緑色になり、声も変わります）。"]},{"version":"0.1.362","items":["回転ずしのお腹ずしを効果中に続けて食べると、お腹がそのぶんさらにふくらむようにしました（3 個まで。食べるたびに効果が 15 秒にのび、吹き出しも「もっと太っちゃった...」「お腹パンパン...」に変わります）。"]},{"version":"0.1.361","items":["アプリが前回異常終了していたとき、次の起動で「前回、アプリが異常終了しました」とお知らせを出し、そこから不具合の報告を開けるようにしました。"]},{"version":"0.1.360","items":["（T-584 の下準備。画面の変化はまだなく、お知らせは T-586 で出す）前回アプリが異常終了したかを、起動時に一度だけ画面側へ伝える仕組みを足しました。"]},{"version":"0.1.359","items":["回転ずしの「お腹」を食べたときのお腹のふくらみを大きくし、15秒ほど続くようにしました。「宇宙人寿司」の声と色の変化も15秒ほど続くようにしました。"]},{"version":"0.1.358","items":["回転ずしで「お腹」を食べると、食べた人のアバターのお腹が数秒ふくらみ、「太っちゃった...」と吹き出しが出るようにしました（部屋のみんなの画面で見えます）。"]},{"version":"0.1.357","items":["回転ずしにいたずらネタ「宇宙人寿司」を足しました。食べると数秒間アバターがエメラルドグリーンになり、頭の上に「ワレワレハ…」が出ます（みんなの画面で）。","宇宙人寿司を食べると、緑になっている数秒の間だけ、声が高い宇宙人のような声になって部屋のみんなに聞こえるようにしました。"]},{"version":"0.1.356","items":["回転ずしにいたずらネタ「宇宙人寿司」を足しました。食べると数秒間アバターがエメラルドグリーンになり、頭の上に「ワレワレハ…」が出ます（みんなの画面で）。"]},{"version":"0.1.355","items":["「メニューのボタンをすべて表示する」をオンにしているとドックが縦長になり、しまわれなくなることがあったのを直しました。"]},{"version":"0.1.354","items":["回転ずしに、いたずらネタの「爆弾」と「毒マグロ」を追加しました。食べると、爆弾はアバターの上でドカーン！と爆発し、毒マグロはアバターが数秒間緑色になります（部屋のみんなに見えます。ほかのネタにまざって、ときどき流れてきます）","設定の「マイク・声」に「離席中はマイクを自動でミュートする」の切り替えを足しました。オフにすると、離席中になってもマイクはそのままになります（既定はオンで、今までどおり）。"]},{"version":"0.1.353","items":["（親 T-577 でまとめて報告）離席中にマイクを自動でミュートするかどうかの設定の仕組みを足しました（既定はこれまでどおりミュートする）。"]},{"version":"0.1.352","items":["画面の端から隣のモニターへすばやくカーソルを動かしたとき、ドック（サイドバー）が出たまましまわれなくなることがあったのを直しました。"]},{"version":"0.1.351","items":["Chrome の文字起こしが止まったとき、音声モジュールを切り替えて戻したときと同じように一から作り直して自動で復帰するようにしました（「うまく動いていません」で止まらず、間隔を空けてやり直し続けます）。"]},{"version":"0.1.350","items":["音声の文字起こし（Chrome の音声認識）が途中で止まりにくくなり、通信の失敗や結果が返らなくなったときは自動でやり直すようにしました。"]},{"version":"0.1.349","items":["いっしょに見る（YouTube）が再生できるよう「別のウィンドウで開く」の既定を元の重ねる表示に戻し、別ウィンドウでも再生できるよう直しました。ドックの YouTube ボタンからメニューへカーソルを動かす途中で消えないようにしました。"]},{"version":"0.1.348","items":["ドックの YouTube ボタンから、横に出るメニュー（URL 入力欄・プレイリスト）へカーソルを動かす途中でメニューが消えないようにしました。"]},{"version":"0.1.347","items":["「別のウィンドウで開く」をオンにしたとき、別ウィンドウの YouTube が再生されなかったのを直しました（再生できないときは理由を画面に出すようにしました）。"]},{"version":"0.1.346","items":["画面共有と「いっしょに見る（YouTube）」を、別のウィンドウではなく元どおりアバターの画面の上で開くように戻しました（別のウィンドウで YouTube が再生できない問題の応急処置。設定でオンにし直すこともできます）。"]},{"version":"0.1.345","items":["ほかの人のアバターのメニューで 👊 に乗せたときの攻撃の一覧を、1 列目の外側に扇形の 2 列目として出すようにし、カーソルを一覧へ動かす途中で消えて押せなくなる不具合を直しました。"]},{"version":"0.1.344","items":["フィーバーのとき、白っぽい・色の薄いアバターもはっきり虹色に変わるようにしました（「派手な演出を控えめにする」がオンのときも、点滅なしで色がわかるように変わります）。"]},{"version":"0.1.343","items":["中指を立てたときのモザイクを、ほかの指が少し開いていてもかかるようにし、早くかかって一瞬の揺れでは消えないようにしました。"]},{"version":"0.1.342","items":["ほかの人のアバターのメニューで、攻撃（火・氷・雷・必殺技）を 👊 ひとつにまとめ、乗せるとその上に攻撃の一覧が出るようにしました"]},{"version":"0.1.341","items":["画面の端に出たメニュー（ドック）が、カーソルを隣の画面やタスクバーへ動かしたあとも出たままになることがあったのを直しました。"]},{"version":"0.1.340","items":["アバターの手が中指だけを立てた形になると、その手にモザイクがかかるようにしました（自分の画面にも相手の画面にも出ます）。"]},{"version":"0.1.339","items":["お楽しみに「ブラックジャック」を追加しました。通話中のみんなで（1 人でも）アプリのディーラーと勝負でき、ヒット／スタンドで遊べます。","共通のおもちゃのコイン（はじめ 100、通話中 1 分ごと・なでるたびに少しずつ増える。設定の「記録」で見られる）を追加し、ブラックジャックで配る前にコインを賭けられるようにしました（勝ち 2 倍・ブラックジャック 2.5 倍・引き分けは戻る・負けは没収）。"]},{"version":"0.1.338","items":["自分のアバターの下にある離席・マイク・声を聞く・もぐもぐ・スタンプ・カメラのボタンを、左のメニューにも最初から出すようにしました（設定でオフにできます）。左のメニューから表情の項目を外しました。"]},{"version":"0.1.337","items":["ドリンクを飲んだときの音を、「ごくっ、ごくっ」と飲み込む音にし、飲み干したときは「ぷはー」が鳴るようにしました。"]},{"version":"0.1.336","items":["空間音声で、自分のアバターより左にいる人の声や読み上げが左から、右にいる人のものが右から聞こえるようにしました（これまでは並びの位置によって全員が右から聞こえることがありました）。"]},{"version":"0.1.335","items":["離席ボタンで離席中にしている間に自動アップデートが入っても、再起動して入り直したあとも離席中のままになるようにしました（マイクも離席前の状態のまま）。"]},{"version":"0.1.334","items":["「操作を受け付けない」にしている間は解除ボタンを出さず、自分のアバターの上（上に余裕がないときは下）に「解除するには Ctrl+Alt+L」と小さく薄く表示するだけにしました。Ctrl+Alt+L は設定に関係なくいつでも使えます。"]},{"version":"0.1.333","items":["画面共有といっしょに見る（YouTube）を、最初から別のウィンドウで開くようにしました（設定で今までの表示にも戻せます）。","親 T-550 でまとめて報告します。","いっしょに見る（YouTube）のボタンにカーソルを当てると「URL から動画を共有」「プレイリストを再生」を選べるようにしました（一度閉じるとリンクの入力欄が出ない不具合は先のリリースで直し済み）。"]},{"version":"0.1.332","items":["ドックの YouTube ボタンにカーソルを乗せると「URL から動画を共有」「プレイリストを再生」のメニューが出て、URL の入力欄もボタンのすぐ横に出るようにしました。"]},{"version":"0.1.331","items":["設定の「メニューのボタンをすべて表示する」を最初からオンにして、サイドバーを出すと区切り線より先のボタンも全部見えるようにしました。"]},{"version":"0.1.330","items":["「いっしょに見る（YouTube）」を一度開いて閉じたあと、ドックの YouTube ボタンを押してもリンクの入力欄が出ないことがあったのを直し、入力欄をボタンのすぐ横に出すようにしました。"]},{"version":"0.1.329","items":["ドックの電源ボタン手前の「サーバーからぬける」ボタンの呼び方を「通話から出る」に変えました（ツールチップと、押したあとの案内も合わせました）。"]},{"version":"0.1.328","items":["ドックに「クリック貫通」ボタンを付けました。押すとアバターへのクリックが下のアプリに通るようになり、その間はアバターの列が半分の濃さになります。"]},{"version":"0.1.327","items":["設定の「表示」に「画面共有と YouTube を別のウィンドウで開く」の切り替えを足し、オフにすると今までどおり重ねて表示できるようにしました。"]},{"version":"0.1.326","items":["「操作を受け付けない」のショートカット（Ctrl+Alt+L）が、解除だけでなく押すたびにオン／オフを切り替えられるようになりました。","ショートカット一覧・設定・案内の文言を、Ctrl+Alt+L が「操作を受け付けない」のオン／オフ切り替えになったことに合わせました。","カメラ（または iPhone）で顔を動かしているときは、口をパクっと開け閉めするだけで目の前の回転ずしを食べられるようにしました（MP 回復も同じく効きます）。お寿司を食べると、アバターがパクパクと口を動かすようにしました。"]},{"version":"0.1.325","items":["画面共有と「いっしょに見る（YouTube）」のバーに「別のウィンドウで開く」を足し、OS の普通のウィンドウで映像・プレイヤーを見られるようにしました（別のモニターへ動かしたり、ほかのウィンドウの下に置いたりできます。位置と大きさは次回も覚えます）。","ドックの電源ボタンのすぐ手前に「サーバーからぬける」ボタンを置き、今いるサーバーからワンクリックで抜けられるようにしました（抜けたあとの「もどる」ですぐ戻れます）。","マイクやスピーカーをオフにしたときにアバターの足元に出る札を、文字なしのアイコンだけにして小さくしました。","ブラックジャックなどのゲームのカードや札が、並びのいちばん左・右の人のときに画面の端で切れて見えなくなっていたのを直しました。","設定の「表示」に「メニューのボタンをすべて表示する」を追加しました。オンにすると、左のメニューを出したときに区切り線より先のボタンも最初から全部見えます（最初はオフ）","サイドバーの「フキダシ」ボタンを押しても音が鳴るだけでオン⇔オフが切りかわらなかったのを直しました。","自分のアバター下のボタン列の「濃さ・大きさ・奥行き」から、みんなのアバターの大きさ（設定の「画面での大きさ」）を変えられるようにしました。"]},{"version":"0.1.324","items":["ドックの電源ボタンのすぐ手前に「サーバーからぬける」ボタンを置き、今いるサーバーからワンクリックで抜けられるようにしました（抜けたあとの「もどる」ですぐ戻れます）。","画面共有と「いっしょに見る（YouTube）」のバーに「別のウィンドウで開く」を足し、OS の普通のウィンドウで映像・プレイヤーを見られるようにしました（別のモニターへ動かしたり、ほかのウィンドウの下に置いたりできます。位置と大きさは次回も覚えます）。"]},{"version":"0.1.323","items":["Ctrl+Alt+L を押すたびに「操作を受け付けない」のオン／オフを切り替えられるようにしました（設定でショートカットを有効にしている間）。"]},{"version":"0.1.322","items":["回転ずしを 1 皿食べるたびに、攻撃の MP が回復するようにしました（ふつうの皿は 15、キラキラのレア皿は 50。上限は超えません）。"]},{"version":"0.1.321","items":["空間音声をオンにしているとき、チャットや食事モードの読み上げの声も、書いた人のアバターのいる側（左右）から聞こえるようにしました。"]},{"version":"0.1.320","items":["（T-529 の土台。単体では見た目は変わりません）アバターの画面から開いた空のウィンドウを、枠つき・大きさを変えられる・タスクバーに出る普通のウィンドウとして作れるようにしました。更新履歴は親の T-529 でまとめて書きます。"]},{"version":"0.1.319","items":["キーボードショートカットの一覧を、ドックの ⌨ ボタンか、アプリを使っているときの ?（または F1）ですぐ出せるようにしました（Esc や × ですぐ閉じられます）。"]},{"version":"0.1.318","items":["自分のアバターの下のボタン列にある離席・マイク・声を聞く・もぐもぐ・スタンプ・カメラを、サイドバー（メニュー）に重ねて出さないようにしました（設定の「自分のアバターのボタン列にあるボタンを、メニューにも出す」で元に戻せます）。"]},{"version":"0.1.317","items":["なかまの「メッセージ」を「フレンド」にまとめました。フレンドの名前のところを押すとその人とのメッセージが開き、アイコンを押すとプロフィールが出ます（未読の数もフレンドの一覧に出ます）。"]},{"version":"0.1.316","items":["ひとりでに開いたアップデートなどのお知らせの一覧が、しばらく（12〜20 秒）そのままにしておくとゆっくり消えて閉じるようにしました。ボタン付きの小さな通知も、時間がたつとふわっと消えます（マウスを乗せている間は消えません）。"]},{"version":"0.1.315","items":["画面共有と「いっしょに見る（YouTube）」をお楽しみから出して、ドックの独立したボタンにしました（設定で出す・出さないも選べます）。お楽しみの中は「ゲーム」「演出」「そのほか」の見出しで整理しました。"]},{"version":"0.1.314","items":["通話中に、話し声の大きさが変わるたびに参加者全員の表示が描き直されていたのを、話し始め・話し終わりのときだけにして、大人数の通話の負担を減らしました。あわせて、重さの原因を調べるための記録を詳しくしました。"]},{"version":"0.1.313","items":["ほかの人のアバターのメニューの 🛸 で、その人を UFO で少しのあいださらえるようにしました（自分の上に UFO が出て相手の上へ飛び、相手が吸い込まれるように消えて、3 秒ほどで戻ります。部屋の全員に見えます）"]},{"version":"0.1.312","items":["ボスレイドを「ロールあり」で募集できるようにしました。参加するときにアタッカー／タンク／ヒーラー／エンハンサーから選ぶと、ロールごとの能力と専用スキル 3 つで戦えます（「ロールなし」は今までどおり）。"]},{"version":"0.1.311","items":["お楽しみに「フィーバー」を追加しました。押すと部屋のみんなのアバターが数秒間、虹色に光って激しく揺れます（設定「フィーバーの演出」でオフにでき、「派手な演出を控えめにする」ではゆっくりした虹色だけになります）。"]},{"version":"0.1.310","items":["スパチャのカードと演出が、投げた人の画面だけでなく、部屋のみんなの画面（贈られた人も）に出るように直しました。古い版の人がいるときは、投げた人に「N 人は古い版のため見えていません」と出します。"]},{"version":"0.1.309","items":["お楽しみに「論理回路」を追加しました。0・1・スイッチと AND / OR / NOT などのゲートを置いて線でつなぐと、結果が出力ランプに 1 / 0 で光って表示され、作っている回路は部屋の人がクリックして開いたときだけ見られます。"]},{"version":"0.1.308","items":["画面の端のボタン列で、ボタンとボタンのすき間や、列から少しはみ出した所・画面の端に押し付けた所を押しても、いちばん近いボタンが反応するようにしました（ボタンの見た目は変わりません）。"]},{"version":"0.1.307","items":["アバターの奥行き（奥・手前）を、マウスだけでも変えられるようにしました（自分のボタン列の「濃さ・奥行き」と設定のスライダー、相手のメニューの 👣 でその人と同じ奥行きに並べます。Ctrl+Shift+Alt の操作はそのままです）"]},{"version":"0.1.306","items":["（T-502 の部品。まだ画面には出ません）ボスレイドのロール（アタッカー／タンク／ヒーラー／エンハンサー）と専用スキルの計算を用意しました。"]},{"version":"0.1.305","items":["通話中の重さを調べるための記録に、映像の圧縮・展開やアバターの描画・顔と手の認識にかかった時間を 1 分ごとに足しました（画面や動きは変わりません）。"]},{"version":"0.1.304","items":["ボスレイドに 12 人まで参加できるようにしました（ボスの HP は人数に合わせて増えます。7 人以上のときは参加者の HP を 2 列で表示します）。"]},{"version":"0.1.303","items":["ボスレイドに 7 人以上で参加したとき、参加者の HP を 2 列に並べてカードが縦に伸びすぎないようにし、お楽しみの説明を「2〜12 人」にしました。"]},{"version":"0.1.302","items":["大人数の通話で、話し声に合わせて全員のアバターの枠が何度も描き直されていたのを、話し始め・話し終わりのときだけにして、CPU の負担を減らしました。"]},{"version":"0.1.301","items":["回転ずしのメニューに「お腹」「ミラーボール」「ミートボール」「サッカーボール」「ラグビーボール」の 5 つを追加しました。"]},{"version":"0.1.300","items":["通話中、相手から同じ内容の状態が届き直したときは画面を描き直さないようにし、動作の重さを調べるための記録を詳しくしました。"]},{"version":"0.1.299","items":["自分のアバターの下のボタン列（マイク・離席など）を、左端のつまみをドラッグして好きな位置に動かせるようにしました。位置は次の起動でも残り、つまみのダブルクリックか設定の「ボタン列の位置を元に戻す」で元に戻せます。"]},{"version":"0.1.298","items":["マイクオフ・スピーカーオフや「映像オフ」の表示が出ていても、足元のドリンクが隠れずに見えるようにしました（表示のすぐ上に並びます）。"]},{"version":"0.1.297","items":["ボスレイドに最大 12 人まで参加できるようにしました（古い版の人がいる卓はこれまでどおり 6 人まで）。"]},{"version":"0.1.296","items":["部屋の参加者の並びが毎朝 5 時（日本時間）に自動でランダムに席替えされるようにしました（その日の並びは全員の画面で同じです）。"]},{"version":"0.1.295","items":["通話中に使い終わった接続の情報をため込まないようにし、通信量の計測を軽くしてメモリと CPU の無駄を減らしました。あわせて、重さの原因を調べるための記録を調査用ログに残すようにしました。"]},{"version":"0.1.294","items":["贈ったドリンクと「〇〇さんから△△が届いた」が、贈った人だけでなく部屋のみんなの画面に出るように直しました。古い版の人がいるときは贈った人に「N 人は古い版のため見えていません」と出し、1 人の足元に置けるドリンクを 5 つまでに増やしました。"]},{"version":"0.1.293","items":["奥行きで後ろ（奥）に離れた人の声が、これまでよりはっきり小さく、こもって聞こえるようにしました。"]},{"version":"0.1.292","items":["ほかの人のアバターのメニュー（🥤）から 8 種類のドリンクを贈れるようにしました。贈ったドリンクは部屋のみんなの画面でその人の足元に置かれ（1 人 2 つまで、3 つ目からは古いほうと入れ替え）、「〇〇さんから△△が届いた」と表示されます。","贈られたドリンクを、クリックするたびに一口ずつ飲めるようにしました（3 回で空になり、空のグラスは 5 秒ほどで消えます。減り具合は部屋のみんなに同じように見えます）。"]},{"version":"0.1.291","items":["お楽しみと相手のメニューに「反射神経バトル」を追加しました。合図が出たらいちばん早くボタンを押した人の勝ちで、合図の前に押すとお手付きで仕切り直しになります。"]},{"version":"0.1.290","items":["通話中の相手と「反射神経バトル」で遊べるようにしました（お楽しみや相手のメニューから申し込み、合図が出たらボタンかスペースキーで押して速さを比べます）。","ボスレイドの行動に「全体回復」を追加しました。参加者全員の HP を少しずつ回復できます（1 人あたりの回復量は単体回復より控えめ）。"]},{"version":"0.1.289","items":["ほかの人のアバターのメニュー（🥤）から 8 種類のドリンクを贈れるようにしました。贈ったドリンクは部屋のみんなの画面でその人の足元に置かれ（1 人 2 つまで、3 つ目からは古いほうと入れ替え）、「〇〇さんから△△が届いた」と表示されます。","（子チケット。報告は親 T-497 でまとめます）ボスレイドの全体回復の仕組み（画面のボタンは T-501）。"]},{"version":"0.1.288","items":["回転ずしのレアすしが、ネタまで虹色に光るようにしました。食べると「確変！」の文字と紙吹雪、ファンファーレのにぎやかな演出が出ます。点滅はしません。設定の「派手な演出を控えめにする」をオンにすると、今までどおりの穏やかな光り方のままです"]},{"version":"0.1.287","items":["（親 T-493 でまとめて報告。画面 T-496 が入るまで、お客様から見える変化はない）"]},{"version":"0.1.286","items":["回転ずしでネタのボタンを続けて押したりダブルクリックしたりしたとき、押したのに寿司が流れてこない（自分の画面でもほかの人の画面でも）ことがあったのを直しました。お皿がいっぱいなどで流せないときは、カードにその理由が出るようにしました。"]},{"version":"0.1.285","items":["回転ずしのレアすしが約 100 皿に 1 皿出るようにし、光り方を金色から、色がゆっくり移り変わる穏やかな虹色にしました。"]},{"version":"0.1.284","items":["ボスレイドの募集で難易度（かんたん／ふつう／むずかしい／ゲキムズ）を選べるようにし、招待・戦闘中・頭上の表示にも難易度を出すようにしました。","回転ずしのメニューに、骨付き肉・プリン・宇宙人・ガソリンスタンド・ネジ・電池を追加しました（押すと、ほかのネタと同じようにみんなの前を流れます）。"]},{"version":"0.1.283","items":["ボスレイドの難易度（かんたん／ふつう／むずかしい／ゲキムズ）の仕組みを入れました（選ぶ画面は T-489 で付けます。今は今までどおり「かんたん」で遊べます）。"]},{"version":"0.1.282","items":["決闘で負けた人も、攻撃で HP が 0 になったときと同じようにダウンし、30 秒アバターが低画質になるようにしました（設定「HP とダウン」がオンで戦闘中の人だけ）。"]},{"version":"0.1.281","items":["回転ずしで、ごくまれに（約 300 皿に 1 皿）金色にやさしく光る「レアすし」が流れるようにしました。部屋のみんなに同じお皿がレアに見え、食べると「レア！おいしい！」が出ます。"]},{"version":"0.1.280","items":["回転ずしにオリジナルのロボット「ロボ」のネタを追加しました（ひとつ前の版の相手にはイカとして流れます）。"]},{"version":"0.1.279","items":["回転ずしのネタにサーモン・ツナマヨ・ウニ・いくら・ハンバーグ・アナゴ・ネギトロ・イカ・アジ・エンガワ・カニを追加し、14 種から選べるようにしました（古い版の相手には近いネタで流れます）。","回転ずしに、オリジナルの丸っこいロボットが乗ったお皿「ロボ」を追加しました（全部で 15 種）。"]},{"version":"0.1.278","items":["回転ずしのネタにサーモン・ツナマヨ・ウニ・いくら・ハンバーグ・アナゴ・ネギトロ・イカ・アジ・エンガワ・カニを追加し、14 種から選べるようにしました（古い版の相手には近いネタで流れます）。"]},{"version":"0.1.277","items":["参加者を縦並びにしているとき、回転ずしのお皿が一人ひとりの足元を順に横切って（折り返しながら）流れるようにしました。"]},{"version":"0.1.276","items":["回転ずしで自分の前にお皿が来ている間は、自分のアバターの下のボタンの列（離席・マイクなど）が出ないようにし、お皿を押そうとして別のボタンを押してしまわないようにしました"]},{"version":"0.1.275","items":["回転ずしで、自分の前に流れてきたお皿を押したときに、アバターの下のボタンが反応してしまうことがあったのを直しました（少し遅れて押しても、お皿が食べられます）。"]},{"version":"0.1.274","items":["お楽しみに「回転ずし」を追加しました。マグロ・えび・たまごを押した数だけ（部屋のみんなの分も合わせて）参加者の前をすしのお皿が流れ、自分の前に来たお皿を押すと食べられて、頭の上に「おいしい！」が出ます。"]},{"version":"0.1.273","items":["部屋の参加者の並び順を、表示名の順（あいうえお順・ABC 順）にしました。全員の画面で同じ並びです。"]},{"version":"0.1.272","items":["体の向きを左右だけでなく 360 度（後ろ向きまで）回せるようにしました。設定の「体の向き」スライダーが -180〜180° になります。","設定の「体の向き」スライダーを -180〜180°（後ろ向きまで）動かせるようにしました（報告は親 T-474 でまとめて）。"]},{"version":"0.1.271","items":["ほかの人のアバターのメニューの 💴 から、1〜100「おなか」のスパチャ（一言つき可）を投げられるようにしました。部屋のみんなの画面に、スーパーチャット風のカードと 💴 の演出が出ます。"]},{"version":"0.1.270","items":["設定の「アバターの見え方」で、参加者の並びを「横」に加えて「縦」（画面の端に縦一列、吹き出しは横向き）も選べるようにしました","体の向きを後ろ向き（-180〜180°）まで回しても、カメラ・ライト・プレビューが正しく回るようになりました（設定の欄は T-477 で広げます）。"]},{"version":"0.1.269","items":["サーバーにいる人数が多いと設定画面が右にずれて出ていたのを直し、人数に関係なくいつもの位置に出るようにしました。"]},{"version":"0.1.268","items":["YouTube プレイヤーの音量バーを少し外して押しても音量を操作できるようにし、押し損ねで動画が再生・停止してしまわないようにしました。"]},{"version":"0.1.267","items":["奥行きが離れた人のアバターが、ぼかし・薄さと一緒に小さく見えるようにしました（映像を受けない「映像オフ」の静止画でも同じように変わります）。"]},{"version":"0.1.266","items":["通話中に通信量が急に増えたとき、調査用のログから原因（どの相手の、どの種類の通信が増えたか）を調べられるようにしました。"]},{"version":"0.1.265","items":["サーバーを作った人は、ほかのメンバーが付けたサーバーのスタンプも削除できるようにしました（重複したスタンプを整理できます）。"]},{"version":"0.1.264","items":["通話でいちばん左の人のアバターや扇形メニューにカーソルを合わせても、左端のメニュー（サイドバー）が飛び出さず、アバターが動かなくなりました（メニューはアバターの上の空きや画面の端に寄せると出ます）。"]},{"version":"0.1.263","items":["空間音声がオンのとき、奥行きが離れた人のチャットの読み上げ（PC の声）も、鳴き声や通話の声と同じように奥からこもって聞こえるようにしました。"]},{"version":"0.1.262","items":["奥行きが離れた人ほど、その人の読み上げ音声・鳴き声が小さく（空間音声オンなら鳴き声は奥からこもって）、吹き出しが薄く小さくなるようにしました。"]},{"version":"0.1.261","items":["アバターの大きさを、アバターの上で Ctrl+Shift+Alt+PageUp（大きく）/ PageDown（小さく）で変えるようにしました（Alt+↑↓ はほかのアプリと被るので外しました）。"]},{"version":"0.1.260","items":["奥行きの操作がうまく動かなかったのを直し、アバターの上で Ctrl+Shift+Alt+ホイールで奥・手前へ、Ctrl+Shift+Alt+クリックでその人と同じ奥行きに並べるようにしました"]},{"version":"0.1.259","items":["奥行き（深さ）の仕組みを入れました。深さが違う人ほど薄く・ぼやけて見え、声も遠く（空間音声オンならこもって奥から）聞こえます（深さを変える操作は次の更新で付きます。それまでは今までと同じ見た目・声です）。","アバターの上で Alt+ホイールを回すと自分が奥・手前へ動き、Alt+相手をクリックするとその人と同じ奥行きに並び、Alt+↑↓ でみんなのアバターの大きさ（25%〜150%）を変えられるようにしました。","奥に下がっているあいだ、自分の名札に「奥3」のように今の奥行きが小さく出るようにしました","変化なし（開発用の設定の整理。リリースが未追跡ファイルで止まらないようにしました）"]},{"version":"0.1.258","items":["チャットの欄の「要約を見る」ボタンで、部屋の直近の会話の要約を数行で見られるようにしました。"]},{"version":"0.1.257","items":["ほかの人がキーボードで打ったチャットを、Windows の声で読み上げられるようにしました（設定の「音」の「チャットの読み上げ」、最初はオフ。声と速さも選べます。音声の文字起こしは読みません）"]},{"version":"0.1.256","items":["（親 T-456 でまとめて報告します。画面の T-459 と合わせて出す仕組みの部分）"]},{"version":"0.1.255","items":["設定に「チャットの画像・動画はクリックしてから読み込む（データ節約）」を追加しました。オンにすると、チャットに届いた画像・動画は名前と大きさだけ表示され、クリックしたときに読み込むので通信量を減らせます（既定はオフ、スタンプはいつもどおり表示）。"]},{"version":"0.1.254","items":["相手のアバターのメニューで、サイコロ勝負を「目の合計（n 個）」と「チンチロ」の 2 つの項目に分け、何で申し込むかをその場で選べるようにしました。"]},{"version":"0.1.253","items":["相手とのチンチロ勝負で「目なし」が出たとき、「もう一度振る（あと N 回）」のボタンで 1 人 3 回まで振り直せるようにしました。"]},{"version":"0.1.252","items":["相手の名前をクリックしたときのカードが、一瞬右に出てから真ん中に移るのを直し、最初から真ん中に出るようにしました。"]},{"version":"0.1.251","items":["お楽しみに「カラーカード」（色か数字を合わせて手札を出し切るカードゲーム、2〜6 人）を追加しました。お楽しみから募集し、誘われた人は「参加する」で加わり、自分の番に出せるカードを選ぶか 1 枚引いて遊べます。"]},{"version":"0.1.250","items":["お楽しみに、みんなで協力して挑むタイピング RPG（ダンジョン）を追加しました。攻撃・魔法・回復・パリィをタイピングで行い、5 戦目はボス。難易度も選べて、BGM や演出つきです"]},{"version":"0.1.249","items":["お楽しみに追加する新しいカードゲームの下準備を進めました（まだ遊べません）"]},{"version":"0.1.248","items":["タイピング対決で、正しく 1 文字打つたびに歯切れのいい打鍵音が鳴り、打てた文字が弾けて光るようにしました。続けて打てると「N 連続！」が出て炎が強くなり、1 文打ち切るとキラーンという音と火花で決まります。"]},{"version":"0.1.247","items":["タイピング対決の最中、対決していない人にも、2 人のアバターの上に往復回数と、いま打っている人のお題の進み具合（%）が出るようにしました（打っている文字は送りません）。"]},{"version":"0.1.246","items":["サイコロの「チンチロ」ボタンを Ctrl+Shift を押しながらクリックすると、4・5・6 の目だけが出る隠しコマンドを追加しました。"]},{"version":"0.1.245","items":["「イェーイ！」やじゃんけんのチョキ・グーで頭の上に出る手の絵を、ひと目で手に見える形（指・手のひら・親指がつながった形）に描き直しました。"]},{"version":"0.1.244","items":["タイピング攻撃の難しさを 7 段階にし、1 回跳ね返すごとに 1 段階ずつ上がって、数回で早口言葉のような長い文章を短い時間で打つ異常なレベルまで上がるようにしました（時間はローマ字で打つキーの数で決まります）。"]},{"version":"0.1.243","items":["画面共有でウィンドウを共有するとき、そのアプリの音だけを相手に届けられるようにしました（既定はアプリの音だけ、パネルで「パソコン全体」にも切り替えられます）。","画面共有のパネルで、ウィンドウを共有するときの音を「アプリの音だけ／パソコン全体」から選べるようにし、共有中の表示にどちらで共有しているかを出すようにしました。"]},{"version":"0.1.242","items":["ウィンドウを選んで画面共有するとき、そのアプリの音だけを届けられるようにしました（選べない古い Windows などではパソコン全体の音になります）。"]},{"version":"0.1.241","items":["画面共有のパネルに「カメラ・キャプチャー」を追加し、Web カメラやキャプチャーボードの映像も配信できるようにしました（映像のみ。アバターで使用中のカメラには印が出ます）。"]},{"version":"0.1.240","items":["ボスレイドで攻撃が当たったとき、炎・氷・雷それぞれの派手な演出が出るようにし、弱点を見つけた人には以降その属性のボタンが光って「弱点！」と出るようにしました。","（親 T-428 でまとめて報告）","（親 T-431 でまとめて報告。画面の T-433 が入るまでは使う入口なし）"]},{"version":"0.1.239","items":["タイピング対決で、左右 Shift を押すのは 1 戦の最初の 1 回だけになり、かなのお題をローマ字（shi/si・tsu/tu・n/nn などの表記ゆれも可）で打てるようにしました。打ち間違えると音が鳴り、その位置で止まって正しい文字を打つまで先に進めないようにしました。","タイピング対決の入力欄で、打てた所に色が付き、ローマ字のお手本が見えるようにしました。"]},{"version":"0.1.238","items":["設定の「自分の映像を送らない（データ節約）」をオンにすると、自分のアバター映像を送らずにアップロードの通信量を減らせるようにしました（相手の画面にはアバターの静止画が出て、なでる・スタンプなどはそのまま使えます）。"]},{"version":"0.1.237","items":["相手の映像を「映像なし」にしても、相手のアバターの静止画が出て、なでる・Boop・スタンプなどがそのまま使えるようにしました（映像のデータは流れません）。"]},{"version":"0.1.236","items":["タイピング対決のお題を、ローマ字（shi/si・tsu/tu・n/nn などの表記ゆれ込み）でも判定できるようにしました。（親 T-422 でまとめて報告します。画面からの呼び出しは T-425）"]},{"version":"0.1.235","items":["タイピング攻撃で、同じ対決の 2 回目からは左右 Shift を押さなくても自動で参加できるようにしました。（親 T-422 でまとめて報告します）"]},{"version":"0.1.234","items":["設定の項目を開いたときの詳細の枠が縦に狭くなっていたのを直し、大きさを変えていなければ一覧の下端にそろえたまま上に広く（最大 520px）表示するようにしました。"]},{"version":"0.1.233","items":["みんなで協力してボスと戦う「ボスレイド」を遊べるようにしました。お楽しみから募集して、参加した人で炎・氷・雷の攻撃、まもる、ちょうはつ、回復を選んでボスを倒します（弱点は毎回ランダム、長引くとボスが強い全体攻撃をしてきます）。"]},{"version":"0.1.232","items":["お楽しみに「ボスレイド」を追加しました。部屋のみんな（2〜6 人）を募って、協力してボスと戦えます（ボスと全員の HP、ボスの次の行動の予告、6 つの行動、ダメージの数字の演出）。"]},{"version":"0.1.231","items":["タイピング攻撃が相手に出ないまま終わる不具合を直しました（相手も新しい版に更新すると遊べます）。うまく始まらないときは、両方の画面に理由が表示されます。"]},{"version":"0.1.230","items":["タイピング攻撃が相手の画面に届かず成立しなかった不具合を直しました（お互いに新しい版になると遊べます）。成立しないときは、両方の画面に理由が出るようにしました。"]},{"version":"0.1.229","items":["調査用のログに、タイピング攻撃などの遊びの記録が必ず残るようにしました。"]},{"version":"0.1.228","items":["タイピング攻撃を受けたときに音が鳴って気づけるようにし、受け取れない古い版の相手には攻撃できないようにしました（「相手のアプリが古い」と案内します）。"]},{"version":"0.1.227","items":["（画面は T-417 で付きます。この段階ではお客様から見える変化はありません）ボスレイドの募集・ターンの進行・部屋の相手とのやりとりの仕組みを入れました。"]},{"version":"0.1.226","items":["（ボスレイド T-414 の内部の部品。親チケットでまとめて報告します）"]},{"version":"0.1.225","items":["設定の「表示」に「常に最前面に表示する」を追加しました。オフにすると、ほかのアプリを使っている間はアバターや画像・動画のウィンドウもそのアプリの後ろに回ります（既定はオンのままです）。"]},{"version":"0.1.224","items":["（親 T-408 でまとめて報告）設定 alwaysOnTop がオフのとき、アバターと画像・動画のウィンドウがほかのアプリの後ろに回るようにした仕組み"]},{"version":"0.1.223","items":["（T-408 の下準備。画面の欄は T-410 で入るまで見えない。既定オフで今までどおり）"]},{"version":"0.1.222","items":["設定の「画面での大きさ」で、みんなのアバターを 25% まで小さくできるようにしました。小さくしても、スタンプ・エモートの扇形メニューや読み込み前の枠がはみ出したり名前を隠したりしないように整えました。"]},{"version":"0.1.221","items":["お楽しみのメニューに「ババ抜き」を追加しました。部屋のみんなに参加を募って、2〜6 人でトランプのババ抜きを遊べます（自分の番に相手の裏向きのカードをクリックして引きます。頭の上に残りの枚数・あがり・ババが出ます）。"]},{"version":"0.1.220","items":["相手の映像が出ていないときの代わりの枠に、その人の名前をいつも表示し、話している間は枠がその人の色で光るようにしました。"]},{"version":"0.1.219","items":["名前タグの「受信画質」に「全体設定に合わせる」を追加し、人ごとに選んだ画質を全体設定に戻せるようにしました。いまの画質が個別の指定か全体設定かも表示します。"]},{"version":"0.1.218","items":["タイピング攻撃を受けた側に「対抗しろ！」の案内が出ないことがあったのを直しました。受けられないとき（別の対決中・操作を受け付けない設定中・通信が切れているとき）は、両方の画面にその理由が出るようにしました。"]},{"version":"0.1.217","items":["一部の環境で通話の相手の声とアバターが届かず「つながりません」のままになる問題を、直接つながらないときだけ中継サーバー（TURN）を使ってつなぐようにして直しました。","自動アップデートのダウンロード中は頭の上に「アップデート中 N%」のバーが出るようにし、再起動で抜けた人は戻るまで（最大 60 秒）名前と「アップデート中 N秒」の枠で場所を残すようにしました。","タイピング攻撃を「申し込み」なしの撃ち合いにし、「始めています…」のまま終わる不具合をなくしました。攻撃を受けたら左右Shift同時押し（チャットを開くキーを変えている人はそのキー）で参加して打ち返せ、頭の上の大きな「対抗しろ！」の案内と、跳ね返し・命中・勝ち負けの演出も付けました。","アップデートの後などに素早く入り直したとき、一部の人とつながらずアバターが出ないままになることがあったのを直しました。","タイピング対決を申し込みなしの撃ち合いにし、「始まるのを待っています…」のまま終わる不具合を直しました（見た目の作り込みは T-396 で）。","タイピング攻撃が飛んでくると、自分の頭の上に大きく「左右Shift同時押しで対抗しろ！」と残り時間が出るようにし、参加・跳ね返し（○往復）・命中・勝ち負けの演出を付けました。","画面共有の映像を、共有の画面を開いている人にだけ送るようにしました。ほかの人のカードは「配信中・クリックで見る」になり、開くと「つないでいます…」のあと映ります。自分の共有には「N 人が見ています」と出ます。","（見た目の変化なし）アップデートの進み具合を部屋の相手に伝える仕組みを足しました。画面は T-400 で。","親の T-380 でまとめて報告します（頭上の進み具合のバーと、アップデート中の人の代わりの枠）。","（動きの変化なし。切り替えの定数は false のまま）画面配信を開いている人にだけ送るための仕組みを足しました。有効にするのは T-402 で。","親の T-397 でまとめて報告します。","（ババ抜き T-386 の内部の部品。親チケットでまとめて報告します）","（T-386 の一部。画面 T-405 が入るまでは見た目の変化なし）ババ抜きの募集・配る・引く・終わりの進行を部屋の通信で行う仕組みを入れました。"]},{"version":"0.1.216","items":["素早く入り直した人（自動アップデートの後など）と通話がつながらず、アバターが出ないままになることがあったのを直しました。"]},{"version":"0.1.215","items":["不具合報告に付けたログやファイルから、「DOMAIN\\\\ユーザー名」の形の Windows のアカウント名も消してから送るようにしました。"]},{"version":"0.1.214","items":["不具合報告・要望を送るときと、開発チームとの DM で、Windows のエラーレポートやほかのアプリのログなどのテキストファイルを付けて送れるようにしました（5 件・1 件 2MB まで、名前やメールアドレスなどは消して送ります）。","通話の中継（TURN）の月の使用量を見張り、使いすぎる前に止められるようにしました（お客様の操作は変わりません）"]},{"version":"0.1.213","items":["（T-388 の一部。単独では見た目の変化なし）中継（TURN）の使用量が上限に近づいたとき、その月だけ中継を配らないように止められるようにしました。"]},{"version":"0.1.212","items":["通話はまず直接の接続でつなぎ、つながらないときだけ中継サーバーを使うようにしました（つながりにくい相手とも数秒でつながります）。"]},{"version":"0.1.211","items":["サーバーのスタンプやチャットの画像を毎回ダウンロードし直さないようにし、通信量を減らしました。","公開のチーム様子ページを、Supabase の Realtime ではなく GitHub の Gist から間隔を空けて読むようにしました（アプリ本体は変わりません）。"]},{"version":"0.1.210","items":["（アプリの変更なし。チームの仕組み scripts/team の変更）公開チームページの配信を、変わったときだけ・30 秒以上の間隔で送るようにして、データの送信量を約 10〜40 分の 1 にしました。"]},{"version":"0.1.209","items":["チャットの添付画像を、アプリを開き直したあとも同じものはダウンロードし直さないようにしました（表示が速くなり、通信量が減ります）。"]},{"version":"0.1.208","items":["サーバーのスタンプの画像をパソコンに保存しておき、起動やサーバーに入るたびに全部をダウンロードし直さないようにしました（表示が速くなり、通信量が減ります）。"]},{"version":"0.1.207","items":["（まだ画面がないので見た目の変化なし。添付の画面 T-378 と一緒に親 T-376 で更新履歴を書きます）"]},{"version":"0.1.206","items":["なかまの「参加しているサーバー」で、入る前にそのサーバーにいる人の顔が並んで見えるようになり、「N 人がいます」を押すと全員の名前を一覧で見られるようにしました。"]},{"version":"0.1.205","items":["アプリが突然終了したときに、原因を調べるための記録（落ちた場所・呼び出し元・動いていた処理の名前・版）を詳しく残すようにしました。"]},{"version":"0.1.204","items":["攻撃をいちばん多く止めた人の王冠が、戦闘モードの参加者全員に見えるように直しました。パネルのスキンが設定の画面にも付くようにし、なでるをブロックした人の「しょんぼり」をほかの表示に隠れず前に出してひと目でわかるようにしました。"]},{"version":"0.1.203","items":["なでるをブロックした人の「しょんぼり」が、フキダシやネームプレートに隠れず前に出て、青いどんより線・大きな💧・「しょんぼり…」の札でひと目でわかるようにしました。"]},{"version":"0.1.202","items":["パネルのスキン（迷彩・アロハなど）が、設定の項目一覧と詳細の枠にも付くようにしました。"]},{"version":"0.1.201","items":["攻撃をいちばん多く止めた人の王冠が、本人だけでなく戦闘モードの参加者全員に見えるようにしました。"]},{"version":"0.1.200","items":["設定の詳細の枠の下端が、項目一覧のいちばん下（フィードバックの行）の横にそろうようにしました。"]},{"version":"0.1.199","items":["アバターの上に出るフキダシの履歴に「🕘 さっきの発言」の見出しを付け、古い発言ほど小さく薄く表示して、今の発言と見分けやすくしました。必殺技の「必殺技！」の文字を角ばった太いフォントにし、机の道具の「ペン」の表記を「ペンタブ」に変えました。"]},{"version":"0.1.198","items":["設定・メッセージ・チャットなどのパネルの背景に、薄い柄のスキン（迷彩・アロハ・水玉・ストライプ・チェック）を選べるようにしました（設定 › 表示 › 「パネルのスキン」）。"]},{"version":"0.1.197","items":["戦闘参加のオン・オフの音を作り直し、設定の「ゲーム・演出」で 3 種類（A キレ・B 重め・C 控えめ）から選べて、オン・オフの音を試し聞きできるようにしました。"]},{"version":"0.1.196","items":["親の T-347 でまとめて報告します。"]},{"version":"0.1.195","items":["通話がつながらないときの調査用ログに、中継サーバー（TURN）の取得に失敗した理由・回数・時刻が詳しく出るようにしました。"]},{"version":"0.1.194","items":["設定で「アバター・動き」「音声・SE」「表示」などの項目にカーソルを合わせても、右の詳細の枠が上下に動いたり大きさが変わったりしないようにしました。"]},{"version":"0.1.193","items":["縁取り「毒」の泡を大きく派手にし、縁取りの色が白・黒のときもその色で毒を描くようにしました（アップデートの通知音は T-364・T-367 で先に出し済み。お客様の希望で最初の「ピンポーン」に戻しています）。","戦闘モードに参加している人のうち、部屋に入ってから攻撃をいちばん多くバリアで止めた 1 人の頭の上に、小さな王冠が出るようにしました（回数は部屋に入ってからのもので、戦闘モードの参加者どうしでだけ共有されます）。","縁取り「毒」の泡を大きく派手にし、縁取りの色が白・黒のときもその色で毒を描くようにしました。"]},{"version":"0.1.192","items":["縁取り「毒」の泡を大きく、高く立ちのぼるようにしました。白・黒の縁取りでも、紫と緑ではなくその色のまま毒を描きます。"]},{"version":"0.1.191","items":["設定「全体・連携」の「記録」から、いつから数えているかの日付の表記をなくしました。"]},{"version":"0.1.190","items":["マイクのボタンの説明から「（声で話す）」「（テキストで話す）」を消しました。また、「表示」のアバターの大きさを「画面での大きさ」、「アバター・動き」のほうを「体の大きさ」と呼び分け、違いがわかるようにしました。"]},{"version":"0.1.189","items":["人に送られたスタンプをブロックすると、はね返るだけでなく、爆発する・溶ける・ちりぢりになる演出がランダムに出るようにしました。なでるをブロックした人は、3 秒ほどしょんぼり（色がくすんで少し沈み、💧が出る）するようにしました。"]},{"version":"0.1.188","items":["アップデートの通知音を、もともとの「ピンポーン」に戻しました。"]},{"version":"0.1.187","items":["開発チームからのメッセージが届いたときの「ポロン♪」を、低めで小さく、やわらかい立ち上がりの 2 音にして、気にならない控えめな音にしました。"]},{"version":"0.1.186","items":["アバターにカーソルを合わせたときに出る名札・フキダシの履歴・感情やハンドサインのボタンが、カーソルを外したときにそろって同時に消えるようにしました。フキダシの履歴と名札（プロフィールのボタン）の間も少しあけました。"]},{"version":"0.1.185","items":["アップデートのお知らせの音を、低め・小さめ・ふわっと始まるやさしい音にしました。"]},{"version":"0.1.184","items":["開発チームからのメッセージが届いたときの効果音を、手紙が届いたような軽くてかわいい「ポロン♪」という音にしました。","（T-355 の仕組みの部分。画面の王冠は T-359 で入れるので、これだけでは見た目は変わりません）戦闘の参加者どうしで、部屋に入ってから攻撃をバリアで止めた回数を送り合うようにしました。"]},{"version":"0.1.183","items":["アバターの縁取りの色に、赤・オレンジ・緑・ミント・青・紫の 6 色を足しました。縁取りの模様「毒」が縁取りの色で描かれるようになり（白・黒のときは今までどおり紫と緑）、毒の泡が丸いぶくぶくになって、膨らみながら上っていくようにしました。"]},{"version":"0.1.182","items":["「サーバーに誰かがいる」「誰かが来た」のお知らせが、アップデートの通知と同じ「ピンポーン」ではなく、低めの短い「コンコン」という専用の音で鳴るようにしました。"]},{"version":"0.1.181","items":["設定の「表示」の UI の欄で、長い説明や選択肢が横にはみ出さず折り返して収まるようにしました。扇形メニューの感情・ハンドサインのアイコンが少し右にずれていたのを真ん中にそろえました。"]},{"version":"0.1.180","items":["アップデートのお知らせと、開発チームからのメッセージの通知音を、ふつうの通知音（ピンポーン）とは別の音にしました。"]},{"version":"0.1.179","items":["戦闘参加をオン・オフにしたときの「剣を抜く音」「剣をしまう音」を作り直しました。"]},{"version":"0.1.178","items":["人が多くて扇形メニューがアバターからずれたときは、対象のアバターへ線が出るようにしました。扇形メニューの項目は設定の「表示」で並べ替えたり、出さないようにしたりできます。お気に入りのスタンプ（一覧で ☆）だけを扇形メニューにいつも出すこともできます。"]},{"version":"0.1.177","items":["ほかの人のアバターに出る扇形メニューの項目（火・氷・雷・スタンプ・なでる）を、設定の「表示」で並べ替えたり出さないようにしたりできるようにしました。スタンプの一覧で ☆ を押したお気に入りのスタンプだけを扇形メニューにいつも出せます（ほかは「…」から送れます）。"]},{"version":"0.1.176","items":["画面の端やドックのそばで扇形のメニューがアバターからずれて出たとき、どの人あてのメニューかがわかるよう、メニューから対象のアバターへ点線を引くようにしました。"]},{"version":"0.1.175","items":["フキダシの文字の向きに「自動」を追加し、部屋が 5 人以上になると縦書きに切り替わるようにしました。アバターの角に出るステータスバッジの形を、丸・四角・三角から選べるようにしました（部屋の人にも同じ形で見えます）。","親の T-339 でまとめて報告します（フキダシの向きの「自動」とステータスバッジの形を選ぶ画面）。"]},{"version":"0.1.174","items":["アバターの縁取りの模様に、動く「毒」（紫と緑の泡が立ちのぼる）と「炎」（縁取りの色の炎がゆらめく）の 2 つを追加しました。"]},{"version":"0.1.173","items":["設定のアバター欄の左上にあった丸いバツのボタンをなくしました（Esc やドックの設定ボタン、外を押すなどで閉じられます）。机の道具を「⌨️🖱 キーボード・マウス」「🖊 ペン」「🎮 コントローラー」のように絵文字と名前で並べ、MIDI キーボードの選択も同じ枠の中にまとめました。"]},{"version":"0.1.172","items":["設定の詳細の枠で、効かなかった下からの伸ばしを外しました（上・横・上の角からは今までどおり伸ばせます）。なかまのサーバーの欄の「ぬける」ボタンの文字を大きくして読みやすくしました。"]},{"version":"0.1.171","items":["お楽しみの欄で、じゃんけん・決闘・早押し・サイコロがいつも並ぶようにしました（使えないときは薄く表示し、理由を添えます）。項目が多いときは欄の中でスクロールでき、下に続きがあることがわかるようにしました。"]},{"version":"0.1.170","items":["自分のアバターを指したときのフキダシ（最近の発言）が、名前のタグや表情のメニューと重ならないようにしました。設定の「フキダシ」で履歴の数を 0〜5 から選べるようにし、自分の頭に出るマーク（ｗｗｗ など）がメニューの後ろに隠れないようにしました。"]},{"version":"0.1.169","items":["「声を聴く」をオフにするとマイクも自動でオフになり、戻すとマイクも元に戻るようにしました（もともとマイクをオフにしていた場合は、オフのままです）。"]},{"version":"0.1.168","items":["戦闘参加をオンにしたときの剣を抜く音を控えめな音量にし、オフにしたときは剣を鞘にしまう音が鳴るようにしました。"]},{"version":"0.1.167","items":["音声会話の文字起こしでは、サイドバーのチャット一覧の未読の数が増えないようにしました（キーボードで打ったメッセージなどは今までどおり数えます）。"]},{"version":"0.1.166","items":["メッセージの一覧が、いつも「開発チーム」→「メッセージ」（やりとりのある会話）→「フレンドに送る」の順に並ぶようにしました。フレンドの会話を開いただけでは、その人が会話の側に割り込まなくなります。"]},{"version":"0.1.165","items":["フキダシの向きの「自動」と、ステータスバッジの形（四角・三角）を使えるようにするための下準備をしました（設定の画面は次の版で出ます）"]},{"version":"0.1.164","items":["戦闘モードに参加しているとき、戦闘をオフにしている人のアバターの左上に、小さく揺れる白旗が出るようにしました。"]},{"version":"0.1.163","items":["縁取りの模様の欄で、模様の名前が「…」で切れずに全部読めるようにしました（設定の欄が狭いときは 1 段に並ぶ数が減ります）。"]},{"version":"0.1.162","items":["タイピング対決に対応していない古い版のアプリを使っている相手には、メニューの「タイピング対決を申し込む」が薄く表示されて押せないようにしました（申し込んでも始まらない状態を防ぎます）。"]},{"version":"0.1.161","items":["タイピング対決で申し込まれた側に入力画面が届かなかったとき、申し込んだ側の勝ちにせず「無効（勝ち負けなし）」として終わるようにしました。始まる前に少し間を置き、入力画面が出やすくしました。"]},{"version":"0.1.160","items":["古い版のアプリの相手には、タイピング対決を申し込まないようにしました"]},{"version":"0.1.159","items":["タイピング対決で、時間切れのあと「相手が入力中…あと0秒」のまま閉じなくなることがあったのを直し、結果が届かないときも数秒でお知らせを出して終わるようにしました。"]},{"version":"0.1.158","items":["ほかの人のアバターをクリックしたまま擦ると、擦っている間なでなでが続けて送られるようにしました（なでるボタンもそのまま使えます）。"]},{"version":"0.1.157","items":["相手に「タイピング対決」を申し込めるようになりました。飛んでくる火の玉を、出てくる文章を時間内に打って交互に跳ね返し合い、打てなかったほうの負けです（2 ラウンドごとに文章が難しく・時間が短くなり、20 ラウンドで引き分け）。"]},{"version":"0.1.156","items":["相手のプロフィールメニューから「タイピング対決」を申し込めるようになりました。飛んでくる火の玉を、出てくる文章を時間内に打って跳ね返し合う 1 対 1 の遊びです。"]},{"version":"0.1.155","items":["カメラの手の認識で、手を映した直後に左右を取り違えたり、認識中に左右が一瞬入れ替わったりしにくくしました。","人に送られたスタンプも、届く前なら 🛡 でガードできるようにしました（バリアに当たって弾かれて落ちます）。🛡 のボタンはフキダシ・ネームプレートと重ならない位置に、押しやすい大きさで出るようにしました。"]},{"version":"0.1.154","items":["攻撃・なでるを防ぐ 🛡 ボタンを頭の横に移して大きくし、フキダシやネームプレートに重ならず押しやすくしました。"]},{"version":"0.1.153","items":["サイドバーの戦闘のアイコンでオンにしたとき、剣を鞘から引き抜くような「シャキーン」という音が鳴るようにしました。"]},{"version":"0.1.152","items":["人に送ったスタンプにも、届く前ならガード（🛡）できるようにしました（演出は T-319 で仕上げ）。"]},{"version":"0.1.151","items":["メニュー（サイドバー）がカーソルで出てきたときも、アバターの列がサイドバーの分だけよけるようにしました（しまうと少し遅れて元の位置に戻ります）。"]},{"version":"0.1.150","items":["画面共有で「パソコンの音も共有する」をオンにしても、新しい方式のまま映像と一緒にパソコンの音を共有できるようにしました（使えない PC では今までどおり従来の方式で共有します）。"]},{"version":"0.1.149","items":["画面共有のパネルで、共有の方式（新しい方式／従来の方式）をだれでも選べるようにしました。「パソコンの音も共有する」で従来の方式になったときは、パネルに「音を共有するため従来の方式で共有中」と出るようにしました。","画面共有のパネルで、画質とは別に FPS（毎秒のコマ数）を選べるようにしました。選んだ画質で出せない FPS は薄く表示され、選べません。","設定で「調査用のログを書き出す」を押すと、そのログがフィードバックの送信欄に自動で付き、そのまま一緒に送れるようにしました（「外す」で外せます）。"]},{"version":"0.1.148","items":["設定の項目を開いたときの詳細パネルを、上の端（と遠い側の上の角）をドラッグして上方向にも伸ばせるようにしました。","画面共有のパネルで、共有の方式（新しい方式／従来の方式）をだれでも選べるようにしました。"]},{"version":"0.1.147","items":["サイドバーの「お楽しみ」（スタンプも同じ）の欄が、サイドバーの下の方から開いても画面の外にはみ出さないように直しました。"]},{"version":"0.1.146","items":["しまわれている側のサイドバーのボタンにカーソルを合わせたときも、何のボタンかの名前が出るようにしました。","「パソコンの音も共有する」をオンにして画面共有を始めたときは、音も届くように自動で今までどおりの方式で共有するようにしました。"]},{"version":"0.1.145","items":["画面共有が、はじめから新しい軽い方式（アプリが自分で取り込み、GPU で 1 回だけ変換して送る方式）で動くようにしました。これまで従来の方式だった方も、一度だけ新しい方式にそろえます（使えない PC は自動で従来の方式になります）。"]},{"version":"0.1.144","items":["設定の「アバター・動き」「音声・SE」などを開いたとき、下の方の項目でもパネルが中身に合わせて上に伸び、縦に広く表示されるようにしました。","画面共有のパネルで、画面やウィンドウを選んだあとにもう一度画面選びが出る二度手間をなくしました。"]},{"version":"0.1.143","items":["（T-288 の一部。見た目はまだ変わらない）新しい画面共有のための、画面の取り込みと GPU での 1 回だけのエンコードの仕組みを用意しました。"]},{"version":"0.1.142","items":["（T-288 の作り直しの部品。まだ画面には出ない）共有できる画面・ウィンドウの一覧とサムネイルをアプリ自身で出す仕組みを入れました。","（画面共有の FPS を画質とは別に選べるようにする準備。まだ画面には出ない）FPS の設定と、画質ごとの上限の仕組みを入れました。"]},{"version":"0.1.141","items":["GPU で画面共有の映像を圧縮できない PC では、画質「くっきり」を 1080p までに抑えて、共有中の重さを軽くしました。"]},{"version":"0.1.140","items":["変わりません（新しい画面共有 T-288 の受け取り部品。どこからも呼ばれていません。更新履歴には載せず、親 T-288 でまとめて書きます）"]},{"version":"0.1.139","items":["GPU で H.264 を作れる PC では、画面共有も H.264 で送るようにして、共有中の重さを軽くしました（どの方式で送れるかの判定もログに出ます）。"]},{"version":"0.1.138","items":["フィードバックなどの欄を開いて閉じたときに、サイドバーが閉じて画面がリセットされてしまう不具合を直しました。"]},{"version":"0.1.137","items":["設定で「アバター・動き」「声と音」などの項目を選んだとき、メニューが上下左右にガクガク揺れないようにしました。","机の道具をペンタブやコントローラーにしたとき、設定の「机の道具」の欄にその機器の位置・大きさのスライダーが出て、プレビューにもその機器が映るようにしました（キーボードとは別に覚えます）。","アバターの縁取りの模様に「ダイヤ」「星」「グリッチ」（ときどき横にずれて動く）の 3 つを加え、10 種類の模様を 2 段 × 5 列に揃えて並べました。","設定の項目を開いたとき、詳細の欄が選んだ行の高さから下に伸びるようにし、どの項目でも右辺・下辺・角をドラッグして大きさを変えられるようにしました（大きさは覚えていて、見出しのダブルクリックで元に戻せます）。","設定の「声と音」を「音声・SE」に名前を変え、じゃんけんのファンファーレや攻撃・HP・MP などの遊びの設定を新しい「ゲーム・演出」タブに分けました。","サイドバーのフキダシ・離席・戦闘のボタンに、それぞれ別のオン／オフの効果音を付け、表情メニュー・お楽しみ・スタンプ・終了のボタンでは開いたときに共通の「開く」音が鳴るようにしました。","プロフィールの「鳴き声の高さ」のバーを動かすと、変えたあとの高さで試しの声が鳴るようにしました（離したときと、ドラッグ中に少し止めたとき。「声を聴く」がオフでも鳴ります）。","お楽しみやスタンプのメニューを開いたまま、設定・チャット・なかまなどを開くと、メニューが開いたまま残る不具合を直しました。","設定の項目の一覧と、開いたときの見出しの左のアイコンを、絵文字からサイドメニューと同じシンプルな線のアイコンに変えました。","攻撃・なでる・Boop を受けた回数とした回数を、この PC の中で数えて、設定の「全体・連携」→「記録」で見られるようにしました（炎・氷・雷・必殺技の内訳つき、0 に戻すこともできます）。","サイドバーのフキダシのオンオフのアイコンを、人と小さなフキダシの絵に変えて、チャットのアイコンと見分けやすくしました。","設定 › 表示 › フキダシ で、フキダシの形を「ふつう／漫画風／手書き風／まる」から選べるようにしました。","調査用のログの最後にも通話の要約（接続の経路・状態・直近の通話の記録）を付け、通話がつながらない不具合を調べやすくしました。","表情を固定しているあいだは自動のまばたきを止め、目のまわりが歪まないようにしました。","自分のスタンプ・サーバーのスタンプに、すでにある画像と同じ画像を追加しようとすると、追加せずに「同じ画像のスタンプがすでにあります」とお知らせするようにしました。","スタンプの選択画面で、サーバーのスタンプがあれば「編集」ボタンが出るようにし、編集中は自分が追加したものだけ × で消せること、ほかの人のスタンプは消せない理由がわかるようにしました。"]},{"version":"0.1.136","items":["画面共有の画質を「ふつう」「くっきり」にしたとき、パソコンの処理が追いつかなければ自動で解像度やコマ数を下げて重くなりにくくしました。「くっきり」は最大 1440p までにしました。"]},{"version":"0.1.135","items":["設定の「音」で、アプリの音（相手の声・画面共有の音・効果音・鳴き声・動画の音）を鳴らすスピーカー／ヘッドホンを選べるようにしました（YouTube と Windows の声での読み上げは Windows のサウンド設定に従います）。"]},{"version":"0.1.134","items":["攻撃（火の玉・氷のつぶて・雷）に MP を使うようにしました。MP は時間で少しずつ、キーボードやマウスを使っているとより早くたまり、自分のアバターの上の青いバーで見られます（設定でオフにもできます）。"]},{"version":"0.1.133","items":["画面共有中の重さの原因を調べられるよう、共有の負荷（解像度・fps・エンコーダー・制限の理由）を調査用ログに残すようにしました。"]},{"version":"0.1.132","items":["通話がつながらないときの調査用に、設定から「調査用のログを書き出す」と、開発チームとの DM から「ログを送る」ができるようにしました（名前・メールアドレス・IP アドレスは消して送ります）。","通話で声や映像が届かないときの原因を調べやすくするため、アプリが残す通話の接続の記録を詳しくしました（名前・メールアドレス・IP アドレスなどは記録から消します）。","（T-245 にまとめて報告）","決闘のバリアを 2 ターン続けては使えないようにしました（1 ターン空ければまた使えます。使えないターンはボタンが押せなくなり、理由が出ます）。","通話中にマイクの音が届かなくなったとき（USB マイクの抜け・無音のまま止まる・選んだマイクが一時的に見えなくなる）に、アプリが気づいて自動でマイクを開き直すようにしました。","攻撃や必殺技を受けると減る HP を入れました。0 になるとダウンの演出と効果音が出て、30 秒間アバターがモザイクになります（設定の「HP とダウン」でオフにできます）。","通話中にマイクの音が途中で止まってしまったとき、アプリが気づいて自動でマイクをつなぎ直すようにしました。","ゲームを起動したまま画面共有をしても PC が重くなりにくくなるよう、画面共有を軽くし、画面共有パネルで画質（軽さ優先・ふつう・くっきり）を選べるようにしました。","なでるエモートも攻撃と同じようにバリア（🛡）で防げるようにしました。防がれると、撫でようとした人が「ボカン！」と爆発します（専用の演出と効果音つき）。","攻撃（火・氷・雷・必殺技）の演出と音が、戦闘に参加している人の画面にだけ出るようにしました。左のメニューの ⚔️ と、相手のアバターのメニューの「参加する」ボタンで、参加と不参加を切り替えられます（最初は参加になっています。なでるは今までどおりです）","（T-252 にまとめて報告）"]},{"version":"0.1.131","items":["（チームの道具のみ。アプリの変化はありません）"]},{"version":"0.1.130","items":["変化なし（開発チームの道具だけの変更）。"]},{"version":"0.1.129","items":["自分のアバターの大きさを 50%〜200% の範囲で選べるようにしました（大きい人がいても、アバターの列が画面からはみ出さないようにしました）。"]},{"version":"0.1.128","items":["攻撃をガードする 🛡 のボタンが吹き出しやネームプレートの下に隠れて押せないことがあったのを直し、いつも手前に出て押せるようにしました。"]},{"version":"0.1.127","items":["ゲーム・演出の音（じゃんけんのファンファーレなど）、YouTube、画面共有のはじめの音量を、設定の「音」でそれぞれ調整できるようにしました。YouTube の画面のバーにも音量スライダーを付け、音だけ聞いているレコードプレーヤーはホイールで音量を変えられます。YouTube の音量の初期値は 50% に下げました。","攻撃（🔥火・❄️氷・⚡雷・必殺技）となでるが相手に当たったときに、種類ごとに違う効果音が鳴るようにしました（「効果音」や「攻撃・なでるの演出」がオフのときは鳴りません）","フィードバックを開くショートカットを F12 から F9 に変えました。10/25 までは F12 を押すと「F9 に変わりました」とお知らせが出ます。","相手のアバターの名前（プロフィールを開くボタン）が「もぐもぐ中」の表示やフキダシと重ならず、いつでも読めて押せるように直しました","必殺技をより派手な演出にし、氷・雷の攻撃でも、また自分の攻撃が相手に当たったときにも、必殺技ゲージが溜まるようにしました。","縦書きの吹き出しの文字が重ならず読みやすくなるようにしました。吹き出しのしっぽを長くし、吹き出しの下の角がギザギザに見えないようにしました。","必殺技ゲージが自分の画面だけでなく、部屋のほかの人の画面でもその人のアバターの頭の上に見えるようにしました。","攻撃・なでるを受けたときに頭の上に出る吹き出し（「ケホッ」「さむっ」「ビリビリ」「えへへ」など）を、その人の鳴き声（どうぶつの森風）で読み上げるようにしました。","バリアで跳ね返された攻撃を、さらにバリアで跳ね返せるようにしました（1 つの攻撃につき 5 回まで。跳ね返すたびに速くなります）。","アバターの縁取りの模様に「水玉」「市松」「ジグザグ」「格子」を足しました（全部で 7 種類から選べます）。","設定の更新履歴の欄を、チャット欄などと同じように端や角をつかんで幅と高さを変えられるようにしました（大きさは次に開いたときも残り、見出しのダブルクリックで元に戻ります）。","メニュー（ドック）のボタンを、つかんで上下に動かして好きな順に並べ替えられるようにしました。並べた順は次に起動したときも保たれ、設定 › 表示 › UI の「並び順を元に戻す」で元に戻せます。","設定やメニューなど画面に出る「吹き出し」の表記を「フキダシ」にそろえました。","設定の「吹き出し」で、アバターの上の吹き出しの文字のフォントを、この PC に入っているフォントから選べるようにしました（縦書きでも効きます。既定は今のまま）。","必殺技ゲージが放っておいても減らず、必殺技を使ったときだけ減るようにし、バリアで攻撃を跳ね返すと大きく（3 つ）溜まるようにしました。","机の道具が「自動」のとき、ペンタブで描いている途中にもう片方の手でキーを押しても、表示がキーボードに戻らずペンタブのままになるようにしました。","ドック（サイドバー）のフィードバックのボタンのすぐ下に「更新履歴」のボタンを置き、押すだけで更新履歴を開けるようにしました。","アバターにカーソルを重ねたときの扇形のメニューが、前より早く出るようにしました。","相手を 1 人選んで「決闘」を申し込み、ためる・攻撃（火・氷・雷）・バリア・必殺技の読み合いで戦えるようにしました。","設定の画面で、右のアバターのプレビューやメニューにカーソルを重ねたときに、開いている項目が勝手に切り替わってガクガクするのを直しました。","部屋で共有されたプレイリストを本棚に「アルバム」として残し、お楽しみメニューの「本棚」からいつでも開いて、丸ごと・一部をプレイリストに入れ直せるようにしました","自分のアバターに出るメニューで、下のボタン列（マイク・離席など）を出さないように、設定（アバターの見た目）で切り替えられるようにしました。","下のバーの文字起こしのボタンを「フキダシ」にし、押した瞬間にアバターの上の文字起こしのフキダシが消えたり戻ったりするようにしました（文字起こしは続きます）。","「声を聞く」をオフにしているあいだ、自分以外のアバターがグレーになり、声が聞こえていないことが一目でわかるようにしました","チャット・DM・なかまなどのポップアップや画面共有の小窓を動かしたり大きさを変えたりしたとき、一瞬消えてしまうのを直しました。","設定の「メニューに出すボタン」で、ドックに出すボタンを選べるようにし、「離席」と「スタンプを送る」もドックに出せるようにしました","マイクや「声を聞く」がオフのときの表示を、設定の「表示 › アバターの見え方」で「目立つ」（今の表示）と「控えめ」から選べるようにしました（最初は今までどおり「目立つ」です）。","通話の経路の取得に失敗したとき、裏で取り直して、つながらない相手との接続を張り直すようにしました。厳しいネットワークで相手の声やアバターが届かないことが減ります。","画面の端に近づいてサイドバー（ドック）が出ても、通知ボタンがその横へよけて押せるように直しました。","設定の「アバターの見え方」で自分のアバターの大きさ（70%〜130%）を決められ、部屋の相手の画面にもその大きさで映るようにしました（相手は「ほかの人が決めた大きさで表示する」をオフにすると、これまでどおり全員同じ大きさで見られます）。"]},{"version":"0.1.126","items":["アバターのまわりの白い縁取りを、初めて使う人や縁取りの設定がまだない人では最初からオンにしました。"]},{"version":"0.1.125","items":["自分に🔥の攻撃が当たるたびに頭の上の「必殺技ゲージ」がたまり、満タンになるとバリアの効かない大きな火の玉「必殺技」を1回撃てるようにしました。また、短い間に何度もなでられたアバターはキラキラと輝くようにしました。","（親 T-207 でまとめて報告します。この子は設定キーと音の振り分けだけで、既定値では今までと同じ音量です）"]},{"version":"0.1.124","items":["カメラで顔を動かしているとき、アバターの瞬きがときどき高速で繰り返されることがあったのを直しました。"]},{"version":"0.1.123","items":["MIDI キーボードをつないで設定の「机」で選ぶと、弾いたときにアバターの机に鍵盤が出て、押した鍵に合わせて指が動くようにしました（既定はオフ）。","アバターの上の吹き出しの文字の色・背景の濃さ・文字の大きさを、設定の「表示 › 吹き出し」で変えられるようにしました。あわせて設定の「表示」を「アバターの見え方」「UI」「吹き出し」の3つに分けて見つけやすくしました。","相手のアバターの扇に、攻撃の🔥・❄️・⚡を別々のボタンとして並べ、押した瞬間にその攻撃が飛ぶようにしました（属性を選ぶ二段階の操作をなくしました）。","アバターの上の吹き出しの文字を縦書きにできるようにしました（設定の吹き出しで「横書き／縦書き」を選べます。既定は横書きのまま）。","ドックを「常に表示」または「マイクのみ」にしているとき、アバターの列がドックに隠れず、ドックの横に並ぶようにしました。","設定の「表示 › UI」で、ドック・設定・チャット・DM・なかま・通知の配色（アクセント色・パネルの背景色・文字色）を自分で選べるようにしました。「いつもの色に戻す」で元に戻せます。","チャットログの音声（文字起こし）の投稿に「音声」の印を付け、「直打ちだけ」のタブで打った投稿だけを見られるようにしました。日付のタブを選ぶと深夜・朝・昼・夜で絞れ、画像一覧も選んだ日・時間帯の画像だけが出ます。","部屋のみんなで YouTube の共有プレイリストに曲を次々追加でき、終わると自動で次の曲へ進むようにしました。入れた曲は自分だけの「本棚」に CD ケースのように並び（アプリを閉じても残る）、ホバーでジャケットを見ながら、クリックで 1 曲、または選んでまとめてプレイリストに入れられます。","部屋で YouTube を共有している人のアバターの上に小さなレコードプレーヤーが出るようになり、クリックすると画面を出さずに音だけで一緒に聞けるようにしました（再生中は控えめに跳ねます。もう一度クリックでやめられます）。","部屋で YouTube のプレイリストが流れているとき、プレイヤーの下に曲の一覧（今の曲が先頭、追加した人の色つき）が出て、外す・飛ばす・次に追加ができるようにしました。","YouTube のプレイリストに入れた曲が「本棚」に CD ケースのように並び、ホバーでジャケットを見ながら、クリックで 1 曲、または選んでまとめてプレイリストに入れられるようにしました。","（T-185 の一部。設定で MIDI 機器を選ぶ欄 T-205 と合わせて親 T-185 でまとめて報告します）MIDI 機器がつながっている間、机の上に鍵盤が出て、弾いた音に合わせてアバターの指が動くようになります。","設定の「机」で、つないだ MIDI キーボードを選べるようにしました（既定は「使わない」）。"]},{"version":"0.1.122","items":["MIDI キーボードを使うための下準備をしました（まだ画面には出ません）","YouTube の共有プレイリストと本棚のための下準備をしました（まだ画面には出ません）"]},{"version":"0.1.121","items":["スピーカーをオフにしているとき、マイクオフと同じ赤いタグ「スピーカーオフ」がアバターの足元に出るようにし（押すとオン）、背景のスピーカーオフの印を大きく、アバターに隠れないようにしました。"]},{"version":"0.1.120","items":["更新履歴や設定・チャットなどのパネルが画面の一番上まで伸びないようにしました（画面の高さの 7 割までで、残りはパネルの中でスクロールします）。"]},{"version":"0.1.119","items":["アバターにカーソルを近づけたときに出る吹き出し・名前・メニューが、設定などのパネルやドックより手前に出て隠してしまうのを直しました。"]},{"version":"0.1.118","items":["相手の名前をクリックしてプロフィールを開いても、その人のチャットの吹き出しがプロフィールの上によけて、どちらも読めて押せるようにしました。"]},{"version":"0.1.117","items":["見た目・動きの変化はまだありません（MIDI キーボードを机に置いて指を動かすための準備です。設定は次の更新で追加します）。"]},{"version":"0.1.116","items":["チャットの履歴をさかのぼって読んでいる最中に新しい投稿が届いても一番下へ戻らなくなり、「新しい投稿があります」のボタンで知らせるようにしました（押すと一番下へ移ります）。"]},{"version":"0.1.115","items":["攻撃スタンプが飛んでくる間にバリアを張れるようにしました。着弾までに張れたら、攻撃を飛ばした人へ跳ね返ります。","文字起こしを「自動」にしていて Windows の文字起こしが声を拾えないときは、自動で Whisper に切り替えるようにしました（子チケット T-181 で対応）。","文字起こしを「自動」にしていて Windows の文字起こしが声を拾えないときは、自動で Whisper に切り替えるようにしました。","攻撃の属性（火・氷・雷）を選んでいる途中にマウスが別のアバターに重なっても、選択の表示が消えず最後まで選べるようにしました。","アプリが突然終了したあとの次の起動で、前回の終わり方と Windows が記録した異常終了の情報をフィードバックに自動で添えるようにしました（原因を突き止めるための記録の強化で、終了そのものの修正は別に進めます）。"]},{"version":"0.1.114","items":["なかまの「ステータスの絵文字」で自分で入れた絵文字が、ほかの絵文字を選んだあとも消えずに残り、クリック 1 回で戻せるようにしました。"]},{"version":"0.1.113","items":["「なかま」のステータス絵文字を Win + . の絵文字パネルで入れても、消えずに保存されるようにしました（すでに絵文字があるときに足しても、新しい絵文字に変わります）。"]},{"version":"0.1.112","items":["公開チームページへの状態の送信が上限内の大きさに収まるようになり、ページが再び毎分更新される見込み（アプリ本体の変更ではない）。","Leap Motion の手の左右・上下・前後が、Control Panel の Tracking Mode（机の上／Head Mounted／画面の上）に合わせて正しい向きになり、手首の位置を Leap の 3D の値から決めるので、手が体の前に出る。設定に「Leap の置き方」を追加（自動／机の上／頭／画面の上／首かけ・胸の前）。首かけで使う報告者は「首かけ・胸の前」を選ぶと胸の高さに出る。"]},{"version":"0.1.111","items":["攻撃エモートの種類を増やしました。相手のアバターの扇で 🔥 を押すと「🔥火・❄️氷・⚡雷」から選べ、氷なら相手が青白く凍って震え、雷なら白く光ってビリビリ震えます（火は今までどおり黒焦げです）"]},{"version":"0.1.110","items":["攻撃・なでるのエモートを何人もが同時に使っても、カクつきにくくなるよう軽くしました（見た目はほぼそのままです）","じゃんけんと同じように、相手（何人でも）を選んでサイコロ勝負を申し込めるようにしました。「目の合計が大きい方が勝ち」と「チンチロ」から選べ、全員の目が同時に出て勝ち・負け・あいこが表示されます（あいこは上位同士で振り直し）。お楽しみメニューのサイコロ、または相手のアバターのメニューから申し込めます"]},{"version":"0.1.109","items":["じゃんけんで勝つと拍手つきの勝利ファンファーレ、負けると悲しげな「ワワワワーン」が鳴るようにしました。同じ部屋でほかの人がじゃんけんを申し込まれたときも、少し控えめなファンファーレが鳴ります（設定の「サウンド」の「ほかの人が申し込まれたときのファンファーレ」でオフにできます）"]},{"version":"0.1.108","items":["手の入力元を Leap Motion にして手をかざすと、アプリが落ちてしまう問題を直しました。万一 Leap の読み取りで落ちても、次の起動では Leap を止めた状態でアプリが起動し、設定でオンにし直すと再開します","スタンプを人に送ったとき、まれに空から隕石が落ちてきてスタンプに衝突し、焦げて吹き飛ぶようにしました（部屋のみんなに同じ演出が見えます）"]},{"version":"0.1.107","items":["ほかの人のアバターのスタンプの扇に「攻撃（🔥）」と「なでる（🤚）」を加えました。押すと部屋のみんなの画面で火の玉や手が相手に飛んでいき、相手のアバターが少しのあいだ黒焦げになったり、ハートを出して喜んだりします。設定の「サウンド」の「攻撃・なでるの演出」でオフにできます"]},{"version":"0.1.106","items":["じゃんけんを申し込まれた人のアバターの周りに光と星が弾け、申し込まれた本人にはファンファーレが鳴るようにしました（設定の「サウンド」でオフにすると今までの短い音になります）。対戦中の人のアバターの後ろが光り、勝ったときは光の筋と紙吹雪で派手にお祝いします","Windows の文字起こしが、マイクの切り替えなどで止まってしまわないようにしました。途中で止まったときは一度だけ自動でやり直し、声は入っているのに文字にならないときは画面でお知らせします","Leap Motion や SteamVR の手が「机に固定」の設定のせいで使われていないとき、設定画面でお知らせするようにしました","英語の声が入っていない PC でも、笑えるモードの読み上げが高く速い声になり、標準の声と聞き分けられるようにしました。設定にもそのことを書きました"]},{"version":"0.1.105","items":["通話中（サーバーに入っているとき）にアプリが前面にあれば、V キーだけでマイクのオン／オフを切り替えられるようにしました。文字を入力している間は反応しません。設定の「マイク」でオフにもできます","アプリが突然終了してしまったとき、次に起動したときのログにその直前の様子が残るようにしました。フィードバックを送っていただくと、落ちた原因を調べやすくなります"]},{"version":"0.1.104","items":["お楽しみメニューに「サイコロ」を追加しました。1〜6 個を選んで振れて、結果は部屋のみんなの画面で、振った人の頭の上に転がって出ます。「チンチロ」で 3 個振ると役（ピンゾロ・ゾロ目・シゴロ・ヒフミ・目あり・目なし）も出ます"]},{"version":"0.1.103","items":["もぐもぐ中の人の発言の読み上げに「笑えるモード」を追加しました（設定の「音」、最初はオフ）。ひらがな・カタカナをローマ字にして英語の声で読むので、たどたどしい読み方になります（英語の声がないときは標準の声で読みます）"]},{"version":"0.1.102","items":["新しい Ultraleap のソフト（Tracking Service 5.x / 6.x）で、Leap Motion の手がアバターに反映されなかった問題を直しました。手の入力元を Leap Motion にすると、設定の Leap の行に接続の状態（接続中／サービスを待っています／デバイスが見つかりません など）が出ます"]},{"version":"0.1.101","items":["設定の「表示」の大きさを「アバター」と「文字・UI」の 2 つに分けました。アバターだけ小さくしても、文字やボタンは読みやすい大きさのままにできます（アップデート直後は今までの大きさを両方に引き継ぐので、見た目は変わりません）","もぐもぐ中の人の発言を、Windows の標準の声で読み上げられるようにしました（設定の「音」、最初はオフ。オンにすると鳴き声の代わりに読み上げます）"]},{"version":"0.1.100","items":["部屋の人（1 人でも複数人でも）とじゃんけんができるようにしました。お楽しみメニューか相手のプロフィールカードから申し込めます。みんなが手を選ぶと一斉に公開され、頭の上にグー・チョキ・パーと勝ち・負け・あいこが出ます（あいこは最大 5 回までやり直し）"]},{"version":"0.1.99","items":["鳴き声（どうぶつの森風）の高さを、自分のプロフィール（なかまの自分のカード）で決められるようにしました。部屋のみんなには、その人が決めた高さで聞こえます（設定にあった一律の高さは、自分の高さとして引き継がれます）"]},{"version":"0.1.98","items":["通知の一覧と設定のポップアップを、見出しをつかんでドラッグで好きな場所へ動かせるようにしました。動かした位置は次に起動したときも覚えています（設定は「設定」の見出しをダブルクリックすると元の位置に戻ります）"]},{"version":"0.1.97","items":["設定の「表示」で縁取りをオンにしたとき、縁取りの模様（無地・ハーフトーン・ストライプ）を選べるようにしました。点や斜線の帯が、選んだ縁取りの色でアバターのまわりに付きます（最初は今までどおり無地。自分の画面だけの設定です）"]},{"version":"0.1.96","items":["なかまパネルの自分のカードで絵文字を 1 つ選ぶと、自分のアバターの右上の角に丸いバッジで表示されるようにしました。同じ部屋の人の画面にも表示されます（最初はなし）"]},{"version":"0.1.95","items":["設定の「表示」で、アバターの縁取りの色を選べるようにしました（白・黒・ピンク・水色・黄、または好きな色。最初は今までどおり白）","縁取りをオンにすると、設定画面のキャラクターのプレビューにも同じ縁取りが付くようにしました","「左のメニュー」という表記を、右側に置いたときにも合う「メニュー」に変えました"]},{"version":"0.1.94","items":["チャット欄と DM の上に「すべて／今日／昨日／日付／もっと前」のタブを付け、1 日ずつ切り替えて見られるようにしました。「すべて」では日付の見出しを押すとその日だけを表示します"]},{"version":"0.1.93","items":["マイクがオフのあいだ、自分のアバターの足もとに赤い「マイクオフ」の札が出るようにしました。押すとマイクがオンになります","設定の「表示」に「マイクのボタンだけを常に表示する」を追加しました。オンにすると、左のメニューが隠れているときもマイクのボタンだけがその場に残ります（最初はオフ）","自分のアバターのメニューのエモートを「ハンドサイン」と「感情」の 2 つに分け、選ぶと中身が開くようにしました","通知のベル（またはお知らせ）をドラッグして、通知を好きな位置へ動かせるようにしました。位置は次の起動でも覚えていて、ダブルクリックで元の位置に戻せます"]},{"version":"0.1.92","items":["設定の「表示」に「アバターに縁取りを付ける」を追加しました。オンにすると、自分の画面のアバターの周りに白い縁が付いて、背景に溶け込みにくくなります（最初はオフ）","左のメニューの設定ボタンの上に「フィードバック・不具合の報告（F12）」ボタンを追加しました。押すと F12 と同じようにフィードバック欄が開き、すぐに書けます"]},{"version":"0.1.91","items":["チャット・DM・なかま・画面共有のパネルを、右下の角だけでなく、四辺と四隅のどこからでもドラッグして大きさを変えられるようにしました","チャットと DM の履歴に「今日」「昨日」「10月20日（月）」のような日付の見出しを入れ、日ごとに区切って見られるようにしました（各メッセージには時刻だけを表示します）"]},{"version":"0.1.90","items":["体の向きを変えたときの見え方を、0.1.86 のころと同じに戻しました（カメラを引いたり、アバターと机を横へ寄せたりしません）。正面の見え方は変わりません"]},{"version":"0.1.89","items":["「なかま」と「画面共有」のパネルも、チャット欄と同じようにドラッグで動かしたり大きさを変えたりでき、次に開いたときもその位置と大きさを覚えるようにしました","設定の「表示」に「左のメニューを常に表示する」を追加しました。オンにすると、カーソルを近づけなくても左のメニューが出たままになります（最初はオフ）","チャット欄に「画像の一覧」ボタンを追加しました。そのサーバーに投稿された画像を新しい順に並べて見られ、クリックで拡大できます","設定の「表示」に「見た目: ライト／ダーク／Windows に合わせる」を追加しました。ダークにすると、左のメニュー・設定・チャット・DM・なかま・通知の一覧と、別ウィンドウのチャット／DM が暗い色になります（最初はライト）"]},{"version":"0.1.88","items":["体の向きを変えたとき、アバターが小さくならないようにしました。代わりに、斜めに向いたアバターと机の小物（キーボード・マウス・マイク）がまとめて背中側へ寄り、画面に収まりやすくなります"]},{"version":"0.1.87","items":["アップデートのあと自動で通話に戻ったとき、更新前に大きく開いていたほかの人の配信画面を、もう一度開くようにしました（相手がまだ配信中のとき）。自分が配信していた場合は、通知から 1 クリックで配信をやり直せます","ベルの通知に、同じ投稿が二重で届くことがある問題を直しました","体の向きを変えたとき、カメラが少し引いて、キーボード・マウス・マイクなどの机の小物が画面に収まるようにしました","「体の向き」スライダーを、設定の「アバター」の大きさのすぐ下へ移しました"]},{"version":"0.1.86","items":["設定の「手・机」に「体の向き」スライダーを追加しました。自分のアバターを机ごと左右に最大 45° まで斜めに向けられ、ほかの人の画面にも同じ向きで映ります（最初は 0° の正面で、これまでどおりです。「戻す」ボタンで正面に戻せます）"]},{"version":"0.1.85","items":["いま入っていない別のサーバーの投稿（画像を送った、など）は、通知しないようにしました。自分あての @メンションはこれまでどおり通知します。設定の「サウンド」にある「ほかのサーバーのメッセージを通知」をオンにすると、元のように通知されます","なかまのサーバー一覧と、いま入っているサーバーのカードに「退出」ボタンを追加しました。確認のあと、そのサーバーから抜けられます"]},{"version":"0.1.84","items":["自分のアバターにカーソルを乗せたときのメニューに「濃さ」ボタンを追加しました。押すと、アバター・吹き出しの濃さとチャット一覧の濃さをその場で変えられます（設定の「表示」と同じ値です）"]},{"version":"0.1.83","items":["ボーダーレス全画面やウィンドウ表示のゲームを前面にしたとき、アバターやメニューがゲームの後ろに隠れてしまう問題を直しました（あとからゲームが前に出ても、2 秒ほどで手前に戻ります。排他フルスクリーンのゲームでは、表示モードを「ボーダーレス」か「ウィンドウ」にすると上に表示されます）"]},{"version":"0.1.82","items":["操作を受け付けないモードの間も、Ctrl+Alt+L か、メニューの位置にカーソルを寄せると出る「ロックを解除」ボタンで元に戻せるようにしました（どちらも設定の「表示」で個別にオフにできます）"]},{"version":"0.1.81","items":["設定の大項目から詳細へ、アバターから扇のボタンへカーソルを斜めに動かしても、途中で別の項目に切り替わったりメニューが閉じたりしにくくしました"]},{"version":"0.1.80","items":["通話中、相手のアバターが空白のまま表示されないことがある問題の対策をしました（相手の映像が届いていればアバターを表示し、届かない知らせを自動で求め直します）"]},{"version":"0.1.79","items":["リアクション（？・YES/NO・拍手・ブーイングなど）の音を、最初はオフ（音量 0%）にしました。音量を変えていなかった方は、このアップデートで一度だけ 0% になります（設定の音の欄のスライダーで、いつでも上げられます）"]},{"version":"0.1.78","items":["SteamVR で頭の動きを取り込んだとき、アバターの頭が右か左を向いたままになる問題を直しました（ヘッドセットを着けたとき・着け直したときの向きを正面として使います）"]},{"version":"0.1.77","items":["端のメニュー（ドック）が出てくるとき、アバターの列や通知が横にずれず、ドックがその上に重なって出るようにしました（ドックの上にカーソルがある間は、下に隠れたアバターは反応しません）"]},{"version":"0.1.76","items":["ほかの人のアバターにしばらくカーソルを乗せると、まわりにスタンプが扇状に出て、クリックひとつでその人にスタンプを贈れるようにしました","サーバーに入っている間、スタンプのピッカーと自分の扇に「サーバーのスタンプ」の欄が出て、メンバーみんなで使うスタンプを追加・削除できるようにしました","SteamVR を使っているとき、ヘッドセットとコントローラーの動き（頭の向き・手の位置と向き・握り）をアバターに反映できるようにしました（試験的。設定の顔・手の入力元で「SteamVR」を選びます。VR 中はアバターにヘッドセットがかぶります）"]},{"version":"0.1.75","items":["読み替え（文字起こしの辞書）を「自分だけ」と「サーバー共通（メンバー全員で編集）」の 2 つに分けました。同じ言葉は自分の辞書が優先され、共通の辞書を変えると同じ部屋の人にもすぐ反映されます"]},{"version":"0.1.74","items":["チャットにスタンプが届いたとき、画像とは違う「ポロン」という音が鳴り、スタンプがポンと弾んで出るようにしました（続けて届いたときは控えめな音になります。効果音の設定と音量に従います）"]},{"version":"0.1.73","items":["自分のアバターのメニューで、カーソルを乗せたアイコンの説明（ツールチップ）が、となりのアイコンやボタンの列に隠れずに手前に出るようにしました"]},{"version":"0.1.72","items":["自分のアバターのメニューに「スタンプを贈る」ボタンを追加しました。スタンプと相手を選ぶと、自分のアバターから相手のアバターへスタンプが飛んでいきます（自分を選ぶと自分から吹き出します）"]},{"version":"0.1.71","items":["タスクバーや通知領域のポップアップ（音量・カレンダーなど）、スタートメニューを開いたときに、アバターがその手前に出てしまう問題を直しました"]},{"version":"0.1.70","items":["ほかの人の共有画面の音は、その人の画面を開いているときだけ鳴るようにしました（設定の「音」の欄でオフにすると、今までどおりいつでも鳴ります）","ドックのおにぎりボタンをほかの人のアバターにドラッグすると、自分の画面だけでその人を「もぐもぐ化」（声を鳴らさず、話したことを文字で表示）できるようにしました。札を押すと元に戻ります。お楽しみメニューから全員まとめても切り替えられます","拍手がもっと認識されやすくなるように、判定を調整しました"]},{"version":"0.1.69","items":["リアクション（YES・NO・？・拍手など）、効果音、鳴き声の音量を、設定の「音」の欄でそれぞれ別々に調整できるようにしました"]},{"version":"0.1.68","items":["自分の画像をスタンプとして登録して、入力欄やチャット欄のスタンプボタンからすぐ送れるようにしました（PNG・GIF・WebP・JPEG、1MB・60 個まで。いまはこの PC の中に保存されます）"]},{"version":"0.1.67","items":["複数の人の共有画面を、同時に大きく表示できるようにしました（最大 4 枚。クリックした画面が手前に来て、位置と大きさは人ごとに覚えます）"]},{"version":"0.1.66","items":["「操作を受け付けないモード」の間も使いたいショートカット（両Shift の入力欄・F12 のフィードバック・Ctrl+Alt+矢印の位置の移動）を、設定の「表示」で個別に選べるようにしました（最初はすべてオフ）"]},{"version":"0.1.65","items":["文字起こしで、いま入っているサーバーのメンバーの名前（かな・カタカナ・ローマ字）を、登録しなくても表示名の書き方で出すようにしました（設定の読み替えの下でオフにもできます）"]},{"version":"0.1.64","items":["名前や吹き出しを隠して、クリックをすべてうしろのウィンドウに通す「操作を受け付けないモード」を追加しました（設定の「表示」でオン、タスクバーのアイコンのメニューでオン・オフ）"]},{"version":"0.1.63","items":["表情メニューからエモートを選ぶと、アバターの頭・上体・腕もその動きをするようにしました（手を振る・拍手・グッド・びっくり など）"]},{"version":"0.1.62","items":["ディスプレイが 2 つ以上あるとき、設定の「表示」でオーバーレイを出すディスプレイを選べるようにしました"]},{"version":"0.1.61","items":["自分のアバターにカーソルを乗せても表情メニューが出ないことがある問題を直しました。ドックにも表情メニューのボタンを追加しました","表情メニューにエモートの段を追加しました（わらう・なく・びっくり・おこる・はてな など。みんなに見えます）","タスクバーの出し入れに、パネルが滑らかについていくようにしました","設定を開いているとき、設定の外や別のアプリをクリックしたら閉じるようにしました"]},{"version":"0.1.60","items":["縦長の画像を開いたとき、画像全体が画面に収まるようにしました（クリックで拡大したときは、スクロールで全体を見られます）"]},{"version":"0.1.59","items":["設定の口・文字起こしの欄に「読み替え」を追加しました（文字起こしで間違えやすい名前などを、正しい書き方に置き換えます）"]},{"version":"0.1.58","items":["設定の手のトラッキング欄に「ひじの開き」を追加しました（ひじが体の外へ張り出す量を調整できます）"]},{"version":"0.1.57","items":["手のトラッキングに Leap Motion を使えるようにしました（設定の手のトラッキング欄の「手の入力元」）","カメラをオフにしても、自分のアバターのメニューのカメラの絵と「正面にする」ボタンが消えないようにしました"]},{"version":"0.1.56","items":["画面の右側の隅でも、設定の項目の一覧が詳細の左側に出るようにしました","うなずき（YES）と首振り（NO）の演出は、2 回くらい繰り返したときに出るようにしました"]},{"version":"0.1.55","items":["顔や手のトラッキングが一定時間止まったままのとき、マウス追従だけの動きに切り替えるオプションを追加しました（設定の顔のトラッキング、最初はオフ）","鳴き声（どうぶつの森風）の高さを、もっと低くまで下げられるようにしました"]},{"version":"0.1.54","items":["カメラの前で拍手したときの「パチパチ」の演出が出やすくなるよう、判定をゆるめました"]},{"version":"0.1.53","items":["iPhone（iFacialMocap）で顔を動かすとき、首の左右の向きを反転できるスイッチを追加しました","鳴き声（どうぶつの森風）を、もぐもぐ中でない人の発言にも付けられるようにし、声の高さも変えられるようにしました","カメラに親指を立てると「グッド！」、下に向けると「ブー」が頭の上に出るようにしました（自分のアバターのメニューからも出せます）"]},{"version":"0.1.52","items":["設定の「全体・連携」に「更新履歴」を追加し、これまでのアップデート内容をさかのぼって読めるようにしました"]},{"version":"0.1.51","items":["設定を開いたとき、一覧と自分のアバターのプレビューが、自分のアバターのすぐ上にまとまって出るようにしました","空間音声で、頭の向きを変えると端のほうの人の声の向きもなめらかに変わるようにしました"]},{"version":"0.1.50","items":["YouTube の URL を貼るウィンドウを、細い 1 行のシンプルなバーにしました（Esc で閉じられます）"]},{"version":"0.1.49","items":["笑顔で口を開けたまま少し上を向くと、頭の上に「www」が跳ねる演出が出るようにしました（首かしげなどの演出の設定でオン・オフできます）"]},{"version":"0.1.48","items":["手を振ると「バイバイ」、ピースすると「イェーイ！」、拍手すると拍手の演出が頭の上に出るようにしました（自分のアバターのメニューのボタンから、カメラなしでも出せます）","画像・動画・YouTube のリンクが投稿されたとき、ふつうのメッセージとは違う少し目立つ音が鳴るようにしました"]},{"version":"0.1.47","items":["空間音声がオンのとき、効果音や鳴き声（どうぶつの森風）も、その人のいる方向から聞こえるようにしました","鳴き声（どうぶつの森風）と、首かしげ・うなずき・首振りの演出を、最初からオンにしました（設定でオフにできます）","ごはんもぐもぐモード中にマイクをミュートしてから戻すと、もぐもぐモードのままマイクがオンに戻るようにしました","顔を追っているあいだ、自分のアバターのメニューに「いまの顔の向きを正面にする」ボタンを出すようにしました"]},{"version":"0.1.46","items":["フレンドの一覧のいちばん上に、開発チームのアカウントを出すようにしました（フレンドでなくても、不具合やご要望をメッセージで送れます）","「？」「YES」「NO」の演出が、アバターの頭のすぐ上に出るようにしました（アバターの大きさや頭の動きに合わせます）"]},{"version":"0.1.45","items":["マイク・声を聞く・カメラ・ごはんもぐもぐモードを切り替えたとき、それぞれ短く歯切れのいい効果音が鳴るようにしました（オンは上がる音、オフは下がる音。設定の「効果音」でオフにできます）"]},{"version":"0.1.44","items":["設定を 5 つのカテゴリ（アバター・動き／声と音／表示／全体・連携／フィードバック）にまとめ、カテゴリの中はタブで切り替えるようにしました（今までの設定はそのまま引き継がれます。アバターの描画 fps は「表示」の画面に移りました）","うなずくと「YES」、首を横に振ると「NO」が頭の上に出るようにしました（「？」と同じ設定でオン・オフできます）"]},{"version":"0.1.43","items":["空間音声の向きを、画面の真ん中の正面に座っている前提に直しました（左の人は左から聞こえ、その人のほうを向くと正面から聞こえます）","通知を全部読んだら、通知のベルが消えるようにしました（新しい通知が来るとまた出ます）","首をかしげたときの「？」を、ぽよんと弾んで出てくるかわいいアニメーションにしました"]},{"version":"0.1.42","items":["首をかしげると、頭の上に「？」が出て音が鳴るオプションを追加しました（設定の音の欄、最初はオフ。同じサーバーの人にも「？」が見えます）"]},{"version":"0.1.41","items":["相手の声が、その人のタイルの方向から聞こえる「空間音声」を追加しました（設定の音の欄、最初はオフ。顔トラッキング中は頭の向きにも合わせます）","トレイ・終了の確認・設定から、アプリを再起動できるようにしました"]},{"version":"0.1.40","items":["チャットなどを動かすと画面の一部が押せなくなる問題を直すため、オーバーレイを画面いっぱいに固定しました（タスクバーは避けます）","フィードバックの「送信する」ボタンが押せないことがある問題を直しました","F12 でフィードバックの入力欄をすぐ開けるようにしました"]},{"version":"0.1.39","items":["設定を開くとオーバーレイが広がり続けて設定がすぐ閉じる・一段ずつガタガタ広がる問題を直しました","チャットの投稿に絵文字でリアクションできるようにしました"]},{"version":"0.1.38","items":["チャット欄などのパネルを画面の反対側へ動かすと、触れなくなることがある問題を直しました"]},{"version":"0.1.37","items":["自分のアバターの表情メニューは、体の上にカーソルを乗せたときだけ出るようにし、離席などのボタンを下のほうへ移しました","設定は右のメニューにカーソルを乗せたり、離れてしばらくすると自動で閉じるようにしました／フィードバックを Ctrl+Enter で送れるようにしました","チャット一覧を開いたりパネルを動かしたときに、アバターが上下に揺れる問題を直しました","ごはんもぐもぐモードも次の起動に引き継ぐようにしました","アップデートを自動で入れる設定を追加しました（10 秒前にお知らせ、止められます）","鳴き声（どうぶつの森風）の音を聞きとりやすくしました","鳴き声（どうぶつの森風）を、本物のしゃべり声らしく作り直しました","両Shift で入力欄を開いた直後の 1 文字目が、エラー音とともに消えることがある問題を直しました","DM を開いて表示しているのに未読の数が増えていく問題を直しました","もぐもぐ中の人が話し始めたときの音を、短く歯切れのいい音に変えました"]},{"version":"0.1.36","items":["DM などのパネルを動かしたあと、透明な部分がクリックできなくなることがある問題の対策をしました","鳴き声（どうぶつの森風）を、自分の発言とチャットのメッセージにも使えるようにしました"]},{"version":"0.1.35","items":["動かしたパネルを画面の端に置くと、ウィンドウの大きさが動き続けてしまう問題を直しました（動かしてあったパネルは一度だけ元の位置に戻ります）","自分のアバターにカーソルを乗せると、表情と「離席・マイク・声を聞く・もぐもぐ・カメラ」のボタンがまわりに出るようにしました（表情はドックからこちらへ移りました。離席はもう一度押すまで続きます）"]},{"version":"0.1.34","items":["左右の Shift の同時押しで開いた入力欄を、もう一度同時押しで閉じられるようにしました","曲の共有を Spotify と YouTube Music で別々に選べるようにしました（YouTube Music は最初はオフ）","もぐもぐ中の人が話し始めたとき、小さな音で知らせるようにしました","もぐもぐ中の人の発言を、どうぶつの森みたいなピコピコ声で聞けるオプションを追加しました（設定の音の欄、最初はオフ）","端の人の名前にカーソルを乗せても設定のバーが出てこないようにしました。自分の名前をクリックでプロフィールとステータスの設定、ほかの人の名前をクリックでプロフィールカードを表示します","自分のプロフィールで表示名と色も変えられるようにしました","アバターや名前にカーソルを乗せると、その人の少し前までの発言（最大 3 件）が見られるようにしました","Chrome の文字起こしが止まったときに自動でやり直し、画面でお知らせするようにしました","DM を別のウィンドウで開けるようにしました（好きな画面に動かせて、位置と大きさを覚えます）","ドックを整理しました（チャット一覧をいつも表示、DM はなかまの中へ、画面共有・YouTube・早押しは「お楽しみ」ボタンにまとめました）"]},{"version":"0.1.33","items":["起動した直後や、管理者権限のウィンドウが前面にあるときなどに、左右の Shift の同時押しで入力欄が開かないことがある問題の対策をしました"]},{"version":"0.1.32","items":["別ウィンドウのチャットを動かすと、止まらずにガタガタ動き続けたり、奥のウィンドウがクリックできなくなったりしていたのを直しました","左右の Shift の同時押しで入力欄が出ないことがある問題を調べるため、くわしい記録を残すようにしました","アップデートが見つかったときのお知らせに、その版の変更点を表示するようにしました（次のアップデートから表示されます）"]},{"version":"0.1.31","items":["iPhone の iFacialMocap で顔をトラッキングできるようにしました（設定の「顔の入力元」で選べます）"]},{"version":"0.1.30","items":["左右の Shift の同時押しで入力欄が出ないことがあったのを直しました","@メンションを追加しました（名前の候補が出ます）。メンションされた吹き出しは、クリックするまで残ります","拡大した共有画面を、上のバーで動かしたり、角で大きさを変えたりできるようにしました（位置と大きさは覚えておきます）","YouTube Music など、ブラウザで聴いている曲も共有できるようにしました","アップデートのあと自動で通話に戻るとき、マイクとスピーカーはアップデート前の状態のまま戻るようにしました","マイクと「声を聞く」のオン・オフを、次に起動したときも前回のまま引き継ぐようにしました（オフのときは起動時にお知らせします）","早押しボタンを追加しました（通話中のドック）。最初に押した人がみんなの画面で光り、2番目以降は順番が出ます"]},{"version":"0.1.29","items":["設定画面で、右のアバターにマウスを乗せるとフレームレートが大きく下がっていたのを直しました"]},{"version":"0.1.28","items":["人数が多いときや共有画面を大きくしたときは、表示の範囲が必要な分だけ広がるようにしました（画面全体を覆わないので、後ろのウィンドウはこれまでどおり押せます）","表情メニューを追加しました（ドックのボタン）。モデルの表情を選んで固定できます","Boop にたまにレアな演出が出るようにしました","人が入ってきたときの音を、通知の音とは違う控えめな音にしました","となりの人と吹き出しが重ならないようにしました","左右の Shift の同時押しが、しばらくすると効かなくなることがあったのを直しました"]},{"version":"0.1.27","items":["0.1.26 でメニューなどが押せなくなっていたため、いったん 0.1.25 の状態に戻しました（0.1.26 で入った画面いっぱいの表示・表情メニューなどは、直してからあらためてお届けします）","画像や動画を開いて閉じたあと、その場所の後ろのウィンドウがクリックできなくなっていたのを直しました"]},{"version":"0.1.25","items":["参加している人が多くてアバターが小さいときに、名前の札が「…」で切れて読めなかったのを直しました（名前にカーソルを近づけると、札が広がって全部見えます）","参加している人が多いときは、受け取る映像の画質が自動で下がるようにしました（4〜6 人は「中」、7 人以上は「低」まで。名前の札から画質を選んだ人はそのままです）","10 人以上で集まると、一部のアバターが表示されなくなることがあったのを直しました","パソコンのグラフィック機能で映像を軽く送れるときは、そちらを使うようにしました"]},{"version":"0.1.24","items":["設定の「アバターの大きさ」を 30%〜300% まで変えられるようにしました","左右の Shift を同時に押しても、メッセージの入力欄が出なくなっていたのを直しました","「ごはんもぐもぐモード」を追加しました（ドックのおにぎりボタン）。食べている音は送らず、話したことは文字起こしでみんなに届きます","名前を押したときのメニューが、画面の下で切れて操作できなくなることがあったのを直しました（アバターが画面の下に並んでいるときは、名前の上に開きます）","画面の右側に置いているとき、設定を閉じる×ボタンがボタンの列（ドック）に重なっていたのを直しました"]},{"version":"0.1.23","items":["チャットを別のウィンドウで開いて表示しているあいだは、新しいメッセージが未読の数に数えられないようにしました","顔が映らないカメラ（仮想カメラなど）がオンになっていると、すぐに「離席中」になってしまうことがあったのを直しました（そのときはキーボード・マウス・声が 10 分ないときだけ離席中になります）","7 人以上で集まると、はしのアバターが画面の外に見切れてしまうのを直しました（人数に合わせてアバターが小さくなり、全員が収まります）"]},{"version":"0.1.22","items":["配信画面の全画面ボタンを押すとアプリが消えて、トレイのアイコンからしか戻せなくなることがあったのを直しました（消えてもすぐ自動で元に戻ります）","DM の画面の中で、少しだけスクロールしてしまうことがあったのを直しました","相手ごとの声の音量を 200% まで上げられるようにしました（名前の札をクリックして出る音量のスライダーから）"]},{"version":"0.1.21","items":["チャット欄を別のウィンドウで開けるようにしました。チャット欄の右上のボタンから開くと、好きな画面に動かしたり大きさを変えたりできます（位置は次回も覚えています。ピンのボタンでほかのウィンドウより手前に固定できます）"]},{"version":"0.1.20","items":["ゲームなどほかのアプリを前に出したとき、アバターがそのうしろに隠れてしまうことがあったのを直しました","画面共有や YouTube の全画面で、アプリがほかのウィンドウのうしろに隠れてしまう件をもう一度直しました（全画面はタスクバーを避けた広さになります）"]},{"version":"0.1.19","items":["サーバーに入ったままアップデートすると、再起動のあと同じサーバーに自動で戻るようにしました（次のアップデートから効きます）"]},{"version":"0.1.18","items":["画面共有や YouTube の全画面ボタンを押すと、アプリがほかのウィンドウのうしろに隠れてしまうことがあったのを直しました","設定の表示に「アバターをクリックで Boop する」を足しました。オフにすると、アバターの上のクリックがうしろのウィンドウに通り抜けます"]},{"version":"0.1.17","items":["設定の表示に「ログの濃さ」を足しました。チャット一覧を薄くして、うしろの画面を透かせます（マウスを乗せている間は元の濃さに戻ります）","設定の「全体」に今のバージョンと「アップデートを確認」ボタンを足しました。押すとすぐに新しいバージョンがないか確かめます"]},{"version":"0.1.16","items":["マイクをオンにした直後などに、文字起こしがエラーになって止まってしまうことがあったのを直しました"]},{"version":"0.1.15","items":["フレンドと1対1でメッセージ（DM）を送れるようにしました。ドックの封筒ボタンか、フレンド一覧の封筒ボタンから使えます","開発チームから、いただいたフィードバックについて DM でお返事や質問が届くようになりました","目の調整（キャリブレーション）のときの案内が消えなくなることがあったのを直しました","アップデートのあとなどに、文字起こしがしばらく動かないことがあったのを直しました","離席から戻って「マイクをオンに戻しました」と出たのに、ミュートのままになることがあったのを直しました","アバターの大きさを 50%〜200% まで変えられるようにしました","設定の表示に「濃さ」を足しました。アバターと吹き出しを薄くして、うしろのゲームや作業のウィンドウを透かせます","設定のフェイシャルトラッキングに「首の動き」を足しました。首を動かしたときのアバターの頭の動きを控えめ（または大きめ）にできます"]},{"version":"0.1.14","items":["0.1.13 に更新したあと、スタートメニュー（アプリの一覧）やデスクトップから DesktopChat Neo が消えてしまうことがあったのを直しました。起動すると自動で元に戻ります"]},{"version":"0.1.13","items":["アプリの土台を Electron から Tauri に入れ替えました。インストーラーが小さくなり、メモリの使用量も減ります","ログイン状態・設定・アバターは前のアプリから自動で引き継ぎます。前のアプリは自動でアンインストールされます（パソコン全体にインストールしていた場合は、一度だけ確認画面が出ます）","画面共有で共有するものを選ぶときは、Windows の選択画面が出るようになりました"]},{"version":"0.1.12","items":["次のアップデートで、アプリの土台を軽くて速い新しいしくみ（Tauri）に入れ替えます。そのための準備をしました","次のアップデートのときに、ログイン状態・設定・アバターをそのまま新しいアプリへ引き継ぎます"]},{"version":"0.1.11","items":["チャットの入力欄からも画像・動画を送れるようにしました。貼り付け（Ctrl+V）、ドラッグ＆ドロップ、左の画像ボタンで添付できます","相手のアバターがうまく届かず表示されないとき、自動でつなぎ直して表示されるようにしました","設定を何度も開くと、自分のアバターが自分の画面だけで見えなくなることがあったのを直しました"]},{"version":"0.1.10","items":["アイコンを設定できるようになりました。なかまパネルで自分の丸いマークを押して画像を選ぶと、チャット・フレンド一覧・名前タグなどに出ます","YouTube を「みんなで再生」しても、まずはサムネイルだけ出るようにしました。押すと読み込んで再生がはじまります","YouTube を誰が一緒に見ているか、アイコンでわかるようにしました（頭の上のカードと、プレイヤーのバーに出ます）","チャットを好きな場所に動かせるようにしました。大きさはそのままで動き、右下の角をつかむと大きさも変えられます（ヘッダーのダブルクリックで元に戻ります）","アバターの大きさを変えられるようにしました（設定の「アバター」）。キーボード・マウス・マイクの大きさはそのままです","Discord と Spotify との連携を追加しました（設定の「連携」）。Discord に参加中のサーバーを表示したり、Spotify で再生中の曲をフレンドに見せたりできます","Windows のサウンド設定でマイクやスピーカーを変えたときに、文字起こしが止まってしまうことがあったのを直しました","文字起こしの表示が実際の状態とずれることがあったのを直しました"]},{"version":"0.1.9","items":["画面共有でパソコンの音も届けられるようになりました（通話の声は入りません）。共有パネルの「パソコンの音も共有する」で切り替えられます","大きく表示した画面共有に、音量の調節とミュート、全画面のボタンを付けました（音量は人ごとに覚えます）","大きく表示した画面共有や YouTube より、アバターを手前に出せるようにしました。設定の「表示」か、画面共有のバーのボタンで切り替えられます","頭の上の画面共有は、しばらく触らないと「配信中…」の小さな札になります。マウスを乗せると元に戻ります"]},{"version":"0.1.8","items":["YouTube を共有しても、ほかの人の画面では自動で開かなくなりました。共有した人の頭の上にカードが出るので、見たい人だけ「見る」で一緒に再生できます","画像を大きく表示したときに、中身が出ないことがあったのを直しました","画像の表示に全画面ボタンと保存ボタンを付けました（保存を押すと画像が画面に残って消せなくなることがあったのを直しました）","パソコンの調子でアバターが白く消えたままになることがあったのを、自動で元に戻るようにしました","新しいバージョンのお知らせが届かないことがあったのを直しました。スリープから戻ったときにも確認します"]},{"version":"0.1.7","items":["文字起こしがパソコンの Google Chrome の音声認識を使えるようになりました。設定の「自動」では Chrome → Windows → Whisper の順に使えるものを選び、うまくいかないときは次に切り替えます","ノイズ除去（強）を追加しました。キーボードの音やファン、生活音を消してから相手に届けます","Windows の文字起こしが別のマイクを聞いているときに、お知らせを出すようにしました","左のメニューにカメラのボタンを追加しました。オフにすると、ほかのアプリでカメラを使えます。カメラが切れても、使えるようになったら自動でつなぎ直します","アバターごとに、キーボード・マウスと手の位置を自動で合わせるようにしました（設定から調整し直すこともできます）","「手をキーボードとマウスに固定」を追加しました。カメラの手は使わず、いつもキーボードとマウスに手を置いた姿勢になります","「マテリアルを MToon にする」を追加しました。Standard などの質感をアニメ調に変えます","マウスやキーボードを使っていると、アバターが手元やカーソルのほうを見るようになりました","話しているとマイクのアイコンが光るようになりました。オフのアイコンは赤になり、相手の声を聞いていない人には印が付きます","YouTube を「みんなで再生」か「自分だけで再生」か選べるようになりました","ステータスの文字が、変えるとすぐにみんなの画面に反映されるようになりました","フィードバックの書きかけが、閉じても残るようになりました","左のメニューが電源ボタンの上に重なったままになるようにしました"]},{"version":"0.1.6","items":["VRChat 向けのアバター（.unitypackage）をそのまま読み込めるようになりました（髪の揺れなどは付きません）","読み込んだアバターをパソコンに保存して、設定の「アバター」から切り替えられるようになりました","設定に「フィードバック・不具合の報告」を追加しました（ログも一緒に送れます）","文字起こしはいつもオンになり、文字起こしボタンは表示するかどうかの切り替えになりました","アバターの並び順が、だれの画面でも同じになりました","みんなで見ている動画を閉じると、全員の画面から消えるようになりました","後から部屋に入った人にも、再生中の動画が出るようになりました","YouTube の音量や字幕のボタンが押せなかったのを直しました","表情の設定がない VRM でも、口のシェイプキーを探して口を動かすようにしました","はじめて起動したときは新規登録の画面から始まるようにしました"]},{"version":"0.1.5","items":["Boop！ 部屋にいる人のキャラをクリックすると、上からつぶれてポヨンと戻ります（だれが Boop したか名前が出ます）","Boop されると「○○さんに Boop されました！」とお知らせします","キーボードやマウスに乗せる手の位置を、前より大きく動かせるようにしました"]},{"version":"0.1.4","items":["キーボードやマウスに乗せる手の位置（高さ・左右・間隔）を調整できるようになりました","カメラを使っているときは、顔が5秒映らないと離席中になります（カメラなしは10分）","離席中になったらマイクを自動でミュートし、戻ってきたらオンに戻します","お知らせをキャラのすぐ上に出すようにしました","新しいバージョンを出したとき、起動中のアプリにすぐお知らせが届くようになりました（次のバージョンから）","「通知はありません」が出たままになる不具合を直しました"]},{"version":"0.1.3","items":["アップデートが見つかったら「アップデートしますか？」と聞くようになりました","アップデートしたあと、この「アップデート情報」が出るようになりました","カメラに映っているときや話しているときは、離席中にならないようにしました","スペースキーを左手で打つようにしました"]},{"version":"0.1.2","items":["カメラがなくても、頭や目が自然に動くようになりました（タイピング中は手元を見ます）","キーボードとマウスを10分さわらないと「離席中」と表示されます","部屋やサーバーに人が来たら、ピンポーンでお知らせします","起動したとき、だれかがいるサーバーへの参加をおすすめします","名札のメニューから、その人の声の音量とフレンド申請ができるようになりました","サーバー一覧で、フレンド以外の人も「いる」と表示されるようになりました","終了したとき、裏で動いていたものもすべて終わるようにしました"]},{"version":"0.1.1","items":["YouTube プレーヤーを大きくし、ドラッグで移動・角でサイズ変更できるようにしました","YouTube を画面全体の全画面で見られるようにしました"]},{"version":"0.1.0","items":["最初のリリースです","フレンドと 1 対 1 で電話ができます","着信・フレンド申請・招待・メッセージを、ベルの通知とピンポーンでお知らせします","Ctrl+Alt+矢印で画面の端へ、Ctrl+Alt+Shift+矢印で別のディスプレイへ移動できます","新しいバージョンが自動で届きます"]}]`);export{e as default};